\section{Notation, definitions, and already-known results}\label{secdos}
First of all, we set for this section and for the rest of this work the following:

\noindent
{\bf Notation.} For integers $v$ and $w$, with $\gcd(v,w)=1$, $\ord_v(w)$ will denote the {\em multiplicative order} of $w$ modulo $v$. In this work, for positive integers $i$, $m$ and $z$ with $m>1$ and $0\leq z<m$, when we write $z=\residuo{i}{m}$, instead of $z \equiv i \!\pmod{m}$, we refer that $z$ is equal to the remainder that results when $i$ is divided by $m$. By using $q$ we denote a power of a prime number. From now on, $\gamma$ will denote a primitive element of $\bbbf_{q^2}$ and we fix $\alpha=\gamma^{q+1}$ as primitive element of $\bbbf_{q}$. Let $N$ be an integer such that $N|(q^2-1)$. For $i=0,1,\cdots,N-1$, we define ${\cal C}_i^{(N,q^2)}:=\gamma^i \langle \gamma^N \rangle$, where $\langle \gamma^N \rangle$ denotes the subgroup of $\bbbf_{q^2}^*$ generated by $\gamma^N$. The cosets ${\cal C}_i^{(N,q^2)}$ are called the {\em cyclotomic classes} of order $N$ in $\bbbf_{q^2}$. Note that if $i\geq N$, then ${\cal C}_i^{(N,q^2)}:=\gamma^i \langle \gamma^N \rangle=\gamma^{\residuo{i}{N}} \langle \gamma^N \rangle={\cal C}_{\residuo{i}{N}} ^{(N,q^2)}$. Therefore, as a pragmatic approach the subscript $i$, in the cyclotomic class ${\cal C}_i^{(N,q^2)}$, will be seen modulo $N$. By using ``$\Tr_{\bbbf_{q^2}/\bbbf_q}$'' and ``$\N_{\bbbf_{q^2}/\bbbf_q}$'' we will denote, respectively, the {\em trace mapping} and the {\em norm mapping} from $\bbbf_{q^2}$ to $\bbbf_q$. Let $t \in \bbbf_{q}$, and let $V=(v_0,v_1,\cdots,v_{m-1})$ be a vector of length $m$ over $\bbbf_{q}$. We define {\em the number of occurrences of the symbol $t$ in $V$}, denoted by $\Occ(t,V)$, as the number of times that $t$ occurs as an entry in the vector $V$. That is:

$$\Occ(t,V\!=\!(v_0,v_1,\cdots,v_{m-1}))\!:=\!|\{ i \:|\: t=v_i, \:0\leq i < m\}|\;.$$

For any vector $V=(v_0,v_1,\cdots,v_{m-1})$, the circular shift to the right of $V$, denoted by $\sigma(V)$, is defined as 

$$\sigma(V):=(v_{m-1},v_0,v_1,\cdots,v_{m-2})\;,$$

\noindent
and for any integer, $i\geq 0$, the recursively application, for $i$ times, of $\sigma$ to the vector $V$ will be denoted by $\sigma^i(V)$. For example, $\sigma(3,2,2)=(2,3,2)$, $\sigma^0(3,2,2)=(3,2,2)$ and $\sigma^3(2,3,0,2,4)=(0,2,4,2,3)$.

Let $n\geq 1$ be an integer. We recall that the {\em weight enumerator} or {\em Hamming weight enumerator} of a linear code $\CLI$ of length $n$ is defined as the polynomial $1+\sum_{j=1}^{n} A_j z^j$, where $A_j\: (1 \leq j \leq n)$ denotes the number of codewords with Hamming weight $j$ in the code $\CLI$. The sequence $1,\{A_1, A_2,\cdots,A_n\}$ is called the {\em weight distribution} or {\em Hamming weight distribution} of the code. An $M$-\textit{weight} code is a code such that the cardinality of the set of nonzero weights is $M$, that is $M=|\{i:A_i\neq0,i=1,2,\ldots,n\}|$. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The complete weight distribution and the irreducible cyclic codes of dimension 2}
In a similar way, we give now the definition of the complete weight distribution of a linear code:

\begin{definition}\label{defcero} 
Let $\CLI$ be a linear code of length $n$ over $\bbbf_{q}$. Denote the $q$ elements of $\bbbf_{q}$ by using $u_{-1}=0$, $u_0=\alpha^0=1,u_1=\alpha^1,\cdots,u_{q-2}=\alpha^{q-2}$. By denoting $\mathbb{N}_0:=\mathbb{N} \cup \{0\}$, we define the {\em complete weight} of a vector $\mathbf{v}=(v_0,v_1,\cdots,v_{n-1}) \in \bbbf_{q}^n$, as the vector $w_{\rm cplt}(\mathbf{v}):=(f_0,f_1,\cdots,f_{q-2}) \in \mathbb{N}_0^{q-1}$, where $f_i$ ($0 \leq i \leq q-2$) is the number of components $v_j$ ($0 \leq j < n$) of $\mathbf{v}$ that are equal to $u_i=\alpha^i$, that is $f_i=\Occ(\alpha^i,\mathbf{v})$. In addition, for a vector ${\vec f}=(f_0,f_1,\cdots,f_{q-2}) \in \mathbb{N}_0^{q-1}$ we denote by $Z^{\vec f}$ the monomial in the $q-1$ variables $(z_0,z_1,\cdots,z_{q-2})$ given by 

$$Z^{\vec f}:=z_0^{f_0}z_1^{f_1}\cdots z_{q-2}^{f_{q-2}}\;.$$

\noindent
Now, for a linear code $\CLI$ of length $n$ over $\bbbf_{q}$, we define the {\em set of complete nonzero weights} of ${\CLI}$, $W_{\CLI}$, by means of: 

$$W_{\CLI}:=\{w_{\rm cplt}(\mathbf{c}) \:|\: \mathbf{c} \mbox{ is a nonzero codeword in } {\CLI}\}\;,$$

\noindent
and for each complete nonzero weight ${\vec w} \in W_{\CLI}$, we define its frequency, $A_{\vec w}$, as:

$$A_{\vec w}:=|\{\:\mathbf{c} \in {\CLI} \:|\: w_{\rm cplt}(\mathbf{c})={\vec w}\:\}|\;.$$

\noindent
The sequence $1,\{A_{\vec w}\}_{{\vec w} \in W_{\CLI}}$ is called the {\em complete weight distribution} of the linear code $\CLI$, whereas the polynomial  

\begin{equation}\label{eqCWE}
\mbox{\rm CWE}_{\CLI}(Z):=1+\sum_{{\vec w} \in W_{\CLI}} A_{\vec w} \:Z^{\vec w} \;,
\end{equation}

\noindent
is called its {\em complete weight enumerator}.
\end{definition}

\begin{remark}\label{remuno}
Let $n$ and $\mathbf{v}$ be as before, and let $f_{-1}:\mathbb{N}_0^{q-1} \to \mathbb{N}_0$ be the function given by

$$f_{-1}(f_0,f_1,\cdots,f_{q-2}):=n-\sum_{i=0}^{q-2}f_i\;.$$

\noindent
Thus observe that $\Occ(0,\mathbf{v})=f_{-1}(w_{\rm cplt}(\mathbf{v}))$. Therefore, it is important to keep in mind that an alternative definition for the complete weight enumerator (see for example \cite[p. 141]{MacWilliams}) is:

$$\mbox{\rm CWE}_{\CLI}(Z):=z_{-1}^n+\sum_{{\vec w} \in W_{\CLI}} A_{\vec w} \:z_{-1}^{f_{-1}({\vec w})}Z^{\vec w} \;.$$

\noindent
For linear codes these two definitions are equivalent and, for the convenience of this work, we are going to use (\ref{eqCWE}). In addition, observe also that (\ref{eqCWE}) coincides with the Hamming weight enumerator when $q=2$ and contains much more information if $q > 2$.
\end{remark}

The following gives an explicit description of an irreducible cyclic code of length $n$ and dimension $\ord_n(q)\leq 2$ over $\bbbf_q$.

\begin{definition}\label{defuno} 
Let $n$ and $N$ be integers such that $nN=q^2-1$. Then the set 

$$\CLI_{N}:= \{\mathbf{c}_{N}(a) \:|\: a \in \bbbf_{q^2} \}\;,$$

\noindent
where

$$\mathbf{c}_{N}(a):=(\Tr_{\bbbf_{q^2}/\bbbf_q}(a\gamma^{N k}))_{k=0}^{n-1}\;,$$

\noindent
is an {\em irreducible cyclic code} of length $n$ and dimension $\ord_n(q)\leq 2$ over $\bbbf_q$. 
\end{definition} 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The weight distribution of all irreducible cyclic codes of dimension 2}
We end this section by recalling the following result, which characterizes the weight distributions of all irreducible cyclic codes of dimension 2 in terms of their lengths. This characterization shows that all irreducible cyclic codes of dimension 2 have at most two nonzero weights. 

\begin{theorem}\label{teoseis}
\cite[Theorem 7]{Vega1} Let $n$ and $N$ be as before. Fix $u=\gcd(q+1,N)$. Let $\CLI_{N}$ be the irreducible cyclic code of length $n$ over $\bbbf_{q}$. Then:

\begin{enumerate}
\item[\rm (A)] If $u=1$, then $\CLI_{N}$ is an $[n,2]$ one-weight irreducible cyclic code, whose nonzero weight is $\frac{n}{q+1} q$.

\item[\rm (B)] If $2 \leq u < q+1$, then $\CLI_{N}$ is an $[n,2,\frac{n(q+1-u)}{q+1}]$ two-weight irreducible cyclic code whose weight enumerator is 

\[ 1+\frac{(q^2-1)}{u}z^{\frac{n(q+1-u)}{q+1}}+\frac{(q^2-1)(u-1)}{u}z^{n} \; . \] 

\item[\rm (C)] If $u=q+1$, then $\CLI_{N}$ is an $[n,1]$ one-weight irreducible cyclic code, whose nonzero weight is $n$ (which is equivalent to a repetition code of length $n$).

\end{enumerate}
\end{theorem}

