\section{Preliminary results}\label{sectres}
The following result, which is likely already known, identifies all irreducible polynomials of degree two that have the same constant term. For completeness, we include its proof here.

\begin{proposition}\label{prouno}
Let $c \in \bbbf_q^*$ and let $f(x)\neq 1$ be a monic irreducible polynomial in $\bbbf_q[x]$. Let $0\leq i < q-1$ be the unique integer such that $c=\alpha^i$. Then 

\begin{equation}\label{eqcero}
x^{q+1}-c=\prod_{r \in {\cal C}_i^{(q-1,q^2)}}(x-r)\;,
\end{equation}

\noindent
and if $f(x)$ is a divisor of $x^{q+1}-c$ then $f(x)$ is either of the form $f(x)=x^2 \pm bx+c$ or $f(x)=x \pm e$, for some elements $b,e \in \bbbf_q$. More specifically, $f(x)=x^2 \pm bx+c$ iff there exists $r \in {\cal C}_i^{(q-1,q^2)} \setminus \bbbf_q^*$ such that  $b= \Tr_{\bbbf_{q^2}/\bbbf_q}(r)$ and $c=\N_{\bbbf_{q^2}/\bbbf_q}(r)$. Alternatively, $f(x)=x \pm e$ iff $e \in {\cal C}_i^{(q-1,q^2)} \cap \bbbf_q^*$, $c$ is a square in $\bbbf_q$ and $e^2=c$. 
\end{proposition}

\begin{proof}
Let $r \in {\cal C}_i^{(q-1,q^2)}$ and suppose that $r=\gamma^{i+j(q-1)}$ for some $j$. Note that $\N_{\bbbf_{q^2}/\bbbf_q}(r)=r^{q+1}=\gamma^{(q+1)i+(q^2-1)j}=\gamma^{(q+1)i}=\alpha^i=c$. Consequently, (\ref{eqcero}) holds, because $|{\cal C}_i^{(q-1,q^2)}|=q+1$ and $r^{q+1}-c=0$ iff $r \in {\cal C}_i^{(q-1,q^2)}$. Hence we have $(x^{q+1}-c)|(x^{q^2-1}-1)$ and if $f(x) | (x^{q+1}-c)$, then $1\leq \deg(f(x))\leq 2$. Now, if $q$ is even then $-r=r$ and if $q$ is odd then $-r=\gamma^{\frac{q+1}{2}(q-1)}\gamma^{i+j(q-1)}=\gamma^{i+(j+\frac{q+1}{2})(q-1)}\in {\cal C}_i^{(q-1,q^2)}$. On the other hand, whether or not $q$ is even, we have 

$$r^q=\gamma^{i+i(q-1)+j(q-1)(q+1-1)}=\gamma^{i+i(q-1)-j(q-1)}=\gamma^{i+(i-j)(q-1)} \in {\cal C}_i^{(q-1,q^2)}\;.$$ 

\noindent
Therefore $r\in {\cal C}_i^{(q-1,q^2)}$ iff $-r,r^q \in {\cal C}_i^{(q-1,q^2)}$. Clearly, $(x+r)(x+r^q)=x^2+\Tr_{\bbbf_{q^2}/\bbbf_q}(r)x+\N_{\bbbf_{q^2}/\bbbf_q}(r)$ and $(x-r)(x-r^q)=x^2-\Tr_{\bbbf_{q^2}/\bbbf_q}(r)x+\N_{\bbbf_{q^2}/\bbbf_q}(r)$. Hence, the polynomial $f(x)=x^2 \pm bx+c$ is an irreducible divisor of $x^{q+1}-c$ iff there exists $r \in {\cal C}_i^{(q-1,q^2)} \setminus \bbbf_q^*$ such that $b= \Tr_{\bbbf_{q^2}/\bbbf_q}(r)$ and $c=\N_{\bbbf_{q^2}/\bbbf_q}(r)$. Finally, if $e \in {\cal C}_i^{(q-1,q^2)} \cap \bbbf_q^*$ then $0=e^{q+1}-c=e^2-c$ and $f(x)=x \pm e$ is an irreducible divisor of $x^{q+1}-c$. 
\end{proof}

\begin{remark}\label{remtres}
Let $N=q-1$. By Definition \ref{defuno}, the length of the irreducible cyclic code $\CLI_{q-1}$ is $n=\frac{q^2-1}{N}=q+1$ and if $a \in {\cal C}_i^{(q-1,q^2)}$, then

\begin{equation}\label{eqcuatro}
\mathbf{c}_{q-1}(a)=(\Tr_{\bbbf_{q^2}/\bbbf_q}(a\gamma^{(q-1)k}))_{k=0}^{q} \in \CLI_{q-1}\;,
\end{equation}

\noindent
and observe also that if $q$ is even then $|{\cal C}_i^{(q-1,q^2)} \cap \bbbf_q^*|=1$. In fact if $q$ is even and $i=2j$, for $0\leq j \leq \frac{q}{2}-1$, then $\alpha^{j}=\gamma^{2j}\gamma^{(q-1)j}\in {\cal C}_{2j}^{(q-1,q^2)}$ and if $i=2j+1$, for $0\leq j \leq \frac{q}{2}-2$, then $\alpha^{\frac{q}{2}+j}=\gamma^{2j+1}\gamma^{(q-1)(\frac{q}{2}+j+1)}\in {\cal C}_{2j+1}^{(q-1,q^2)}$. Alternatively, if $q$ is odd then $|{\cal C}_i^{(q-1,q^2)} \cap \bbbf_q^*|=2$ if $i$ is even and $|{\cal C}_i^{(q-1,q^2)} \cap \bbbf_q^*|=0$ if $i$ is odd. In fact if $q$ is odd and $i=2j$, for $0\leq j \leq \frac{q-1}{2}$, then $\alpha^{j}=\gamma^{2j}\gamma^{(q-1)j}\in {\cal C}_{2j}^{(q-1,q^2)}$ and $-\alpha^{j}=\gamma^{2j}\gamma^{(q-1)(\frac{q+1}{2}+j)}\in {\cal C}_{2j}^{(q-1,q^2)}$. Now, since $a \in {\cal C}_i^{(q-1,q^2)}$, it is important to note that ${\cal C}_i^{(q-1,q^2)}=\{a\gamma^{(q-1)k}\:|\:0\leq k<q+1\}$. Let $h \in \bbbf_q$. Thus, due to Proposition \ref{prouno} and (\ref{eqcuatro}), we have 

$$\Occ(h,\mathbf{c}_{q-1}(a))=\left\{ \begin{array}{cl}
		\;2 & \mbox{ if there exist } r,r^q \in {\cal C}_i^{(q-1,q^2)} \setminus \bbbf_q^* \\
		    & \mbox{ such that } \Tr_{\bbbf_{q^2}/\bbbf_q}(r)=h , \\
\vspace{-3.5mm}
\\		    
		\;1 & \mbox{ if there exist } e,-e \in {\cal C}_i^{(q-1,q^2)} \cap \bbbf_q^* \\
		    & \mbox{ such that } \Tr_{\bbbf_{q^2}/\bbbf_q}(e)=h , \\
\vspace{-3.5mm}
\\		    
		\;0 & \mbox{ if there does not exist } r \in {\cal C}_i^{(q-1,q^2)} \\
		    & \mbox{ such that } \Tr_{\bbbf_{q^2}/\bbbf_q}(r)=h . \\
			\end{array}
\right .$$

\noindent
Particularly, if $q$ is even then $\Occ(0,\mathbf{c}_{q-1}(a))=1$ and there must exist a unique $e \in {\cal C}_i^{(q-1,q^2)} \cap \bbbf_q^*$ such that $\Tr_{\bbbf_{q^2}/\bbbf_q}(e)=0$. Alternatively, if $q$ is odd and $\Occ(h,\mathbf{c}_{q-1}(a))=1$, then $i$ must be even and there must exist two unique elements $e,-e \in {\cal C}_i^{(q-1,q^2)} \cap \bbbf_q^*$ such that $\Tr_{\bbbf_{q^2}/\bbbf_q}(e)=2e=h$ and $\Tr_{\bbbf_{q^2}/\bbbf_q}(-e)=-2e=-h$. Thus, in any case, the conclusion here is that $0 \leq \Occ(h,\mathbf{c}_{q-1}(a)) \leq 2$ and there exists at least one $u\in \bbbf_q$ such that $\Occ(u,\mathbf{c}_{q-1}(a))=2$.
\end{remark}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Factorization of $x^{q+1}-c$}\label{seccuatro}

Given an element $a\in {\cal C}_i^{(q-1,q^2)}$, the goal is to identify those elements $h\in \bbbf_q$ for which $\Occ(h,\mathbf{c}_{q-1}(a))>0$. By Remark \ref{remtres}, and as detailed below, such elements $h$ are related to the linear coefficient of the irreducible polynomials of degree two over the finite field $\bbbf_q$ and therefore we need a simple criterion to figure out whether a polynomial of degree two is irreducible.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{An easy way to determine when some particular polynomials of degree two are irreducible}
At this point, we are interested in determining whether a polynomial of the form $x^2 \pm\alpha^i x+\alpha^{v} \in \bbbf_{q}[x]$ is irreducible, with $0\leq i<q-1$ and $v \in \{0,1\}$. To this end, and if $q$ is even, we define the sets:

\begin{eqnarray}
R&:=&\{\:0 \leq i < q-1\:|\:\alpha^{i}=\alpha^{k+1}+\alpha^{q-1-k}, \mbox{ with } 0\leq k<\frac{q}{2}-1\:\}\;,\;\;\;\mbox{ and} \nonumber \\
I&:=&\{\:0,1,2,\cdots,q-2\:\} \setminus R\;. \nonumber
\end{eqnarray}

\noindent
Thus, if $0\leq i<q-1$, then $x^2+\alpha^i x+\alpha=(x+\alpha^{k+1})(x+\alpha^{q-1-k})$, for some $0\leq k<\frac{q}{2}-1$, iff $i\in R$, and therefore, $x^2+\alpha^i x+\alpha$ is irreducible iff $i\in I$. Now, if $q$ is odd, we first need to observe that $x^2+\alpha^i x+\alpha^{v}$ is irreducible iff $x^2-\alpha^i x+\alpha^{v}$ is irreducible, and since $-1=\alpha^{\frac{q-1}{2}}$, we can therefore assume, WLOG, that $0\leq i<\frac{q-1}{2}$. In this context, we recall that $\residuo{i}{\frac{q-1}{2}}$ refers to the remainder that results when $i$ is divided by $\frac{q-1}{2}$. In consequence, in the case when $q$ is odd, we define the sets:

\begin{eqnarray}
R_0&:=&\{\:\residuo{i}{\frac{q-1}{2}}\:|\:\alpha^{i}=\alpha^{k}+\alpha^{q-1-k}\;,\mbox{ with } 0\leq k<\left\lceil \frac{q-1}{4} \right\rceil\:\}\;,\nonumber \\
I_0&:=&\{\:0,1,2,\cdots,\frac{q-1}{2}-1\:\} \setminus R_0\;,\nonumber \\
R_1&:=&\{\:\residuo{i}{\frac{q-1}{2}}\:|\:\alpha^{i}=\alpha^{k+1}+\alpha^{q-1-k}\;,\mbox{ with } 0\leq k<\left\lfloor \frac{q-1}{4} \right\rfloor\:\}\;,\;\;\;\mbox{ and} \nonumber \\
I_1&:=&\{\:0,1,2,\cdots,\frac{q-1}{2}-1\:\} \setminus R_1\;, \nonumber
\end{eqnarray}

\noindent
where, for any $y\in \bbbr$, $\lceil y \rceil$ denotes the smallest integer greater than or equal to $y$ and $\lfloor y \rfloor$ denotes the largest integer less than or equal to $y$. Thus, if $0\leq i<\frac{q-1}{2}$, then either $x^2+\alpha^i x+1=(x+\alpha^{k})(x+\alpha^{q-1-k})$ or $x^2-\alpha^i x+1=(x+\alpha^{k})(x+\alpha^{q-1-k})$, for some $0\leq k<\lceil \frac{q-1}{4} \rceil$, iff $i \in R_0$, and therefore, for any integer $i$, $x^2+\alpha^i x+1$ is irreducible iff $\residuo{i}{\frac{q-1}{2}}\in I_0$. Similarly, if $0\leq i<\frac{q-1}{2}$, then either $x^2+\alpha^i x+\alpha=(x+\alpha^{k+1})(x+\alpha^{q-1-k})$ or $x^2-\alpha^i x+\alpha=(x+\alpha^{k+1})(x+\alpha^{q-1-k})$, for some $0\leq k<\lfloor \frac{q-1}{4} \rfloor$, iff $i \in R_1$, and therefore, for any integer $i$, $x^2+\alpha^i x+\alpha$ is irreducible iff $\residuo{i}{\frac{q-1}{2}}\in I_1$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The factorization}
Let $v\in \{0,1\}$. In the previous subsection, we determined when a polynomial of the form $x^2 + \alpha^{i}x+\alpha^{v}$ is irreducible, where we fixed $v=1$ if $q$ is even. The aim of this subsection is to generalize this result to any polynomial of degree $2$, and as a by-product, we find the explicit factorization of the polynomial $x^{q+1}-c$, where $c \in \bbbf_{q}^*$. So, in the case when $q$ is odd, we fix $\delta \in \{0,1\}$ in such a way that $\delta=1$ if $q \equiv 3 \pmod{4}$ and $0$ otherwise. Let $v,w\in \{0,1\}$ and, for integers $j$ and $l$, define the following polynomials over $\bbbf_q$:

$$\eta_v^{(2j+v)}(x):=\left\{ \begin{array}{cl}
		\;(x+\alpha^{j})(x-\alpha^{j}) & \mbox{ if } v=0, \\
\\
		\;1 & \mbox{ otherwise,}
			\end{array}
\right .$$

$$\mu_w^{(l)}(x):=\left\{ \begin{array}{cl}
		\;(x^2+\alpha^{l}) & \mbox{ if } w=1, \\
\\
		\;1 & \mbox{ otherwise.}
			\end{array}
\right .$$

With the previous notations and definitions, we can now present an explicit factorization of any polynomial of the form $x^{q+1}-c$, where $c \in \bbbf_{q}^*$: 

\begin{theorem}\label{MiClas1}
If $q$ is even then, for $0\leq j <q-1$, 

\begin{equation}\label{eq1Teo1}
x^{q+1}+\alpha^{2j+1}=(x+(\alpha^{2j+1})^{1/2})\prod_{i \in I}(x^2+\alpha^{i+j} x+\alpha^{2j+1})\;.
\end{equation}

\noindent
On the other hand, if $q$ is odd then, for $0\leq j <\frac{q-1}{2}$ and $v \in \{0,1\}$,

\begin{equation}\label{eq2Teo1}
x^{q+1}-\alpha^{2j+v}=\eta_v^{(2j+v)}(x)\mu_{\delta\oplus v}^{(2j+v)}(x)\prod_{i \in I_v}(x^2+\alpha^{i+j} x+\alpha^{2j+v})(x^2-\alpha^{i+j} x+\alpha^{2j+v})\;,
\end{equation}

\noindent
where ``$\oplus$'' is the usual XOR operation between two bits.
\end{theorem}

\begin{proof}
Firstly, recall that if $q$ is even then any element $c \in \bbbf_q^*$ has a unique square root and therefore the polynomial $x^2+c$ is always reducible. On the contrary, if $q$ is odd then an element $c \in \bbbf_q^*$ is a square iff $c=\alpha^{2j}$, for some $0\leq j < \frac{q-1}{2}$ and the two square roots of $c$ are $\alpha^j$ and $-\alpha^j$. Additionally, note that the polynomial $x^2+\alpha^{2j}$ is irreducible iff $\delta=1$, while the polynomial $x^2+\alpha^{2j+1}$ is irreducible iff $\delta=0$. Now, due to Proposition \ref{prouno} and the way the sets $I$, $I_0$ and $I_1$ were constructed, we have that if $q$ is even then

\begin{equation}\label{equno}
x^{q+1}+\alpha=(x+\alpha^{1/2})\prod_{i \in I}(x^2+\alpha^{i} x+\alpha)\:=\!\!\!\!\!\prod_{r \in {\cal C}_1^{(q-1,q^2)}}(x-r)\;,
\end{equation}

\noindent
and if $q$ is odd, we have instead

\begin{eqnarray}\label{eqdos}
x^{q+1}-1&=&(x+1)(x-1)\mu_{\delta}^{(0)}(x)\prod_{i \in I_0}(x^2+\alpha^{i} x+1)(x^2-\alpha^{i} x+1)\:=\!\!\!\!\!\prod_{r \in {\cal C}_0^{(q-1,q^2)}}(x-r)\;, \\ \label{eqtres}
x^{q+1}-\alpha&=&\mu_{\delta\oplus 1}^{(1)}(x)\prod_{i \in I_1}(x^2+\alpha^{i} x+\alpha)(x^2-\alpha^{i} x+\alpha)\:=\!\!\!\!\!\prod_{r \in {\cal C}_1^{(q-1,q^2)}}(x-r)\;. 
\end{eqnarray}

\noindent
Clearly, if $q$ is even then $(x+(\alpha^{2j+1})^{1/2})|(x^{q+1}+\alpha^{2j+1})$, for any $0\leq j<q-1$. Alternatively, if $q$ is odd then $(x+\alpha^j)(x-\alpha^j)|(x^{q+1}-\alpha^{2j})$, for any $0\leq j<\frac{q-1}{2}$, and the polynomial $x^2+\alpha^{2j+v}$ is an irreducible divisor of $x^{q+1}-\alpha^{2j+v}$ iff $\delta\oplus v=1$. 

Now, we need to prove that $x^2 + \alpha^{i}x+\alpha^{v}$ is irreducible iff $x^2 + \alpha^{i+j}x+\alpha^{2j+v}$ is irreducible. Clearly, owing to the previous equalities and by fixing $v=1$ when $q$ is even, we know that such a polynomial is irreducible if $j=0$. On the contrary, for $j>0$ assume that $x^2 + \alpha^{i+j}x+\alpha^{2j+v}$ is reducible. Let $r_1,r_2 \in \bbbf_q^*$ such that $(x-r_1)(x-r_2)=x^2 + \alpha^{i+j}x+\alpha^{2j+v}$. Hence, $-r_1-r_2=\alpha^{i+j}$, $r_1r_2=\alpha^{2j+v}$ and $(x-r_1/\alpha^{j})(x-r_2/\alpha^{j})=x^2 + \alpha^{i}x+\alpha^v$, which is a contradiction!

Finally, with $b\neq 0$, suppose that $f(x)=x^2+bx+c \in \bbbf_q[x]$ is irreducible. Thus, if $q$ is even then there must exist a unique $0\leq j<q-1$ such that $c=\alpha^{2j+1}$ and if $q$ is odd then there must exist a unique $0\leq j <\frac{q-1}{2}$ and a unique $v \in \{0,1\}$ such that $c=\alpha^{2j+v}$. Let $0\leq i<q-1$ be the unique integer such that $\alpha^i=b/\alpha^j$. We claim that $x^2 + \alpha^{i}x+\alpha^{v}$ is irreducible, where $v=1$ if $q$ is even. Assume otherwise, and let $r_1,r_2 \in \bbbf_q^*$ such that $(x-r_1)(x-r_2)=x^2 + \alpha^{i}x+\alpha^{v}$. Hence, $-r_1-r_2=\alpha^{i}$, $r_1r_2=\alpha^{v}$ and $(x-\alpha^{j}r_1)(x-\alpha^{j}r_2)=x^2 + \alpha^{i+j}x+\alpha^{2j+v}=x^2+bx+c$, a contradiction! In consequence, with $b\neq 0$, any irreducible polynomial $f(x)=x^2+bx+c \in \bbbf_q[x]$ can be written in the form $f(x)=x^2 + \alpha^{i+j}x+\alpha^{2j+v}$, where $i\in I$ if $q$ is even and $\residuo{i}{\frac{q-1}{2}} \in I_{v}$ if $q$ is odd. 
\end{proof}

\begin{example}\label{ejuno}
