(x^{10}-\alpha^6)&\!\!\!\!\!=\!\!\!\!\!&(x+\alpha^3)(x+\alpha^7)(x^2+\alpha^0x+\alpha^6)(x^2+\alpha^4x+\alpha^6)(x^2+\alpha^2x+\alpha^6)(x^2+\alpha^6x+\alpha^6)\;, \nonumber
