%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{The complete weight distributions of a family of irreducible cyclic codes of dimension two}\label{seccinco}

In the sequel of the paper, we are interested in determining the complete weight distribution for the family of irreducible cyclic codes, $\CLI_{N}$, for which $N|(q-1)$. As detailed below, the key to achieving this goal is the construction of three vectors. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The three vectors $W$, $W_1$, and $W_2$}
We first fix $N=q-1$ and therefore the length of $\CLI_{q-1}$ is $n=\frac{q^2-1}{q-1}=q+1$. Suppose that $q$ is even and assume that $a \in {\cal C}_1^{(q-1,q^2)}$. Thus, owing to (\ref{equno}) and Remark \ref{remtres}, $\Occ(\alpha^i,\mathbf{c}_{q-1}(a))=2$ if $i\in I$, $\Occ(0,\mathbf{c}_{q-1}(a))=1$, and $\Occ(\alpha^i,\mathbf{c}_{q-1}(a))=0$ if $i \not\in I$, for $0\leq i<q-1$. Therefore, by defining $W=(w_0,w_1,\cdots,w_{q-2})$ as the integer vector of length $q-1$ whose entries are given by

$$w_i=\left\{ \begin{array}{cl}
		\;2\; & \mbox{ if } i \in I \\
		\;0\; & \mbox{ otherwise}
			\end{array}
\right .\;,$$

\noindent
we have that $w_{\rm cplt}(\mathbf{c}_{q-1}(a))=W$. In the case when $q$ odd, we first fix, $0\leq s<\frac{q-1}{2}$, to be the unique integer such that either $\alpha^s=2=\Tr_{\bbbf_{q^2}/\bbbf_q}(1)$ or $\alpha^s=-2=-\Tr_{\bbbf_{q^2}/\bbbf_q}(1)$. Here we want to recall that $-1=\alpha^{\frac{q-1}{2}}$ and therefore $x^2+\alpha^i+1$ is irreducible iff $x^2+\alpha^{\frac{q-1}{2}+i}+1$ is irreducible. Now, assume that $a \in {\cal C}_0^{(q-1,q^2)}$. Thus, owing to (\ref{eqdos}) and Remark \ref{remtres}, $\Occ(\alpha^i,\mathbf{c}_{q-1}(a))=2$ if $\residuo{i}{\frac{q-1}{2}} \in I_0$, $\Occ(\alpha^s,\mathbf{c}_{q-1}(a))=1$, and $\Occ(\alpha^i,\mathbf{c}_{q-1}(a))=0$ if $\residuo{i}{\frac{q-1}{2}} \not\in I_0 \cup \{s\}$. Therefore, by defining $W_0=(w_{0,0},w_{0,1},\cdots,w_{0,\frac{q-1}{2}-1})$ as the integer vector of length $\frac{q-1}{2}$ whose entries are given by

$$w_{0,i}=\left\{ \begin{array}{cl}
		\;2\; & \mbox{ if } i \in I_0 \\
		\;1\; & \mbox{ if } i = s \\
		\;0\; & \mbox{ otherwise}
			\end{array}
\right .\;,$$

\noindent
we have that $w_{\rm cplt}(\mathbf{c}_{q-1}(a))=W_0|W_0$, where the operator ``$|$'' stands for the vector concatenation. Similarly, if $a \in {\cal C}_1^{(q-1,q^2)}$ then, owing to (\ref{eqtres}) and Remark \ref{remtres}, $\Occ(\alpha^i,\mathbf{c}_{q-1}(a))=2$ if $\residuo{i}{\frac{q-1}{2}}\in I_1$ and $\Occ(\alpha^i,\mathbf{c}_{q-1}(a))=0$ if $\residuo{i}{\frac{q-1}{2}} \not\in I_1$. Therefore, by defining $W_1=(w_{1,0},w_{1,1},\cdots,w_{1,\frac{q-1}{2}-1})$ as the integer vector of length $\frac{q-1}{2}$ whose entries are given by

$$w_{1,i}=\left\{ \begin{array}{cl}
		\;2\; & \mbox{ if } i \in I_1 \\
		\;0\; & \mbox{ otherwise}
			\end{array}
\right .\;,$$

\noindent
we have that $w_{\rm cplt}(\mathbf{c}_{q-1}(a))=W_1|W_1$.

\begin{example}\label{ejdos}
$ $
\begin{enumerate}
\item[{\rm (A)}] Let $q=8$. In Example \ref{ejuno} {\rm (A)} we found $I=\{1,4,5,6\}$. Therefore $W=(0,2,0,0,2,2,2)$ and if $a \in {\cal C}_1^{(q-1,q^2)}$ then $w_{\rm cplt}(\mathbf{c}_{q-1}(a))=W$. 

\item[{\rm (B)}] Let $q=9$. In Example \ref{ejuno} {\rm (B)} we found $I_0=\{1,3\}$ and $I_1=\{1,2\}$. Since $2=-1=\alpha^4$, $-2=1=\alpha^0$ and $s=0$. Therefore $W_0=(1,2,0,2)$ and $W_1=(0,2,2,0)$. Furthermore, 

$$w_{\rm cplt}(\mathbf{c}_{q-1}(a))=\left\{ \begin{array}{cl}
		\;W_0|W_0=(1,2,0,2,1,2,0,2)\; & \mbox{ if } a \in {\cal C}_0^{(q-1,q^2)} \\
		\;W_1|W_1=(0,2,2,0,0,2,2,0)\; & \mbox{ if } a \in {\cal C}_1^{(q-1,q^2)}
			\end{array}
\right .\;.$$

\item[{\rm (C)}] Let $q=11$. In Example \ref{ejuno} {\rm (C)} we found $I_0=\{0,4\}$ and $I_1=\{1,2,4\}$. Since $2=\alpha^1$, $s=1$. Therefore $W_0=(2,1,0,0,2)$ and $W_1=(0,2,2,0,2)$. Furthermore,

$$w_{\rm cplt}(\mathbf{c}_{q-1}(a))=\left\{ \begin{array}{cl}
		\;W_0|W_0=(2,1,0,0,2,2,1,0,0,2)\; & \mbox{ if } a \in {\cal C}_0^{(q-1,q^2)} \\
		\;W_1|W_1=(0,2,2,0,2,0,2,2,0,2)\; & \mbox{ if } a \in {\cal C}_1^{(q-1,q^2)}
			\end{array}
\right .\;.$$
\end{enumerate}
\end{example}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The complete weight of any codeword in $\CLI_{q-1}$}
Up to this point we are able to determine, by means of vectors $W$, $W_0$ and $W_1$, the complete weight of a codeword $\mathbf{c}_{q-1}(a) \in \CLI_{q-1}$ when $a \in {\cal C}_1^{(q-1,q^2)}$, if $q$ is even, and $a \in {\cal C}_0^{(q-1,q^2)} \cup {\cal C}_1^{(q-1,q^2)}$, if $q$ is odd. Thus, it remains to determine the complete weights for the other possible values of the finite field element $a \in \bbbf_{q^2}^*$. The following result not only gives a solution to this, but even more importantly it shows that such complete weights can also be obtained by means of the same vectors $W$, $W_0$ and $W_1$.

\begin{proposition}\label{prodos}
Let $W$, $W_0$, and $W_1$ be as before. If $q$ is even, then, for any $b \in {\cal C}_{2j+1}^{(q-1,q^2)}$ with $0\leq j<q-1$, we have

\begin{equation}\label{pr2eq1}
w_{\rm cplt}(\mathbf{c}_{q-1}(b))=\sigma^j(W)\;.
\end{equation}

\noindent
On the other hand, if $q$ is odd, then, for any two elements $b \in {\cal C}_{2j}^{(q-1,q^2)}$ and $b' \in {\cal C}_{2j+1}^{(q-1,q^2)}$ with $0\leq j<\frac{q-1}{2}$, we have

\begin{eqnarray}\label{pr2eq2}
w_{\rm cplt}(\mathbf{c}_{q-1}(b))&=&\sigma^j(W_0)|\sigma^j(W_0)\;,  \\
\label{pr2eq3}
w_{\rm cplt}(\mathbf{c}_{q-1}(b'))&=&\sigma^j(W_1)|\sigma^j(W_1)\;. 
\end{eqnarray}
\end{proposition}

\begin{proof}
Suppose that $q$ is even and let $b \in {\cal C}_{2j+1}^{(q-1,q^2)}$ with $0\leq j<q-1$. From our previous discussion, we know $w_{\rm cplt}(\mathbf{c}_{q-1}(a))=W$ for any $a \in {\cal C}_1^{(q-1,q^2)}$. Now, due to the proof of Theorem \ref{MiClas1}, $\residuo{i}{q-1} \in I$ iff $x^2 + \alpha^{i}x+\alpha$ is irreducible iff $x^2 + \alpha^{i+j}x+\alpha^{2j+1}$ is irreducible. Consequently, $\Occ(\alpha^k,\mathbf{c}_{q-1}(b))=2$ iff $\residuo{k}{q-1} \in j+I:=\{\residuo{j+i}{q-1} \:|\: i\in I\}$ and $\Occ(\alpha^k,\mathbf{c}_{q-1}(b))=0$ if $\residuo{k}{q-1} \not\in j+I$. Therefore, by defining $Y=(y_0,y_1,\cdots,y_{q-2})$ as the integer vector of length $q-1$ whose entries are given by

$$y_i=\left\{ \begin{array}{cl}
		\;2\; & \mbox{ if } i \in j+I \\
		\;0\; & \mbox{ otherwise}
			\end{array}
\right .\;,$$

\noindent
we have $w_{\rm cplt}(\mathbf{c}_{q-1}(b))=Y=\sigma^j(W)$. In the case when $q$ is odd, we again fix, $0\leq s<\frac{q-1}{2}$, to be the unique integer such that either $\alpha^s=2=\Tr_{\bbbf_{q^2}/\bbbf_q}(1)$ or $\alpha^s=-2=-\Tr_{\bbbf_{q^2}/\bbbf_q}(1)$. Assume that $b \in {\cal C}_{2j}^{(q-1,q^2)}$, for some $0\leq j<\frac{q-1}{2}$. Since $\alpha^j=\gamma^{2j}\gamma^{(q-1)j} \in {\cal C}_{2j}^{(q-1,q^2)}$, note that either $\Tr_{\bbbf_{q^2}/\bbbf_q}(\alpha^j)=\alpha^{s+j}$ or $\Tr_{\bbbf_{q^2}/\bbbf_q}(\alpha^j)=-\alpha^{s+j}$. Thus, in like manner, $\residuo{i}{\frac{q-1}{2}} \in I_0$ iff $x^2 + \alpha^{i}x+1$ is irreducible iff $x^2 + \alpha^{i+j}x+\alpha^{2j}$ is irreducible. Consequently, $\Occ(\alpha^k,\mathbf{c}_{q-1}(b))=2$ iff $\residuo{k}{\frac{q-1}{2}} \in j+I_0:=\{\residuo{j+i}{\frac{q-1}{2}} \:|\: i\in I_0\}$, $\Occ(\alpha^k,\mathbf{c}_{q-1}(b))=1$ if $\residuo{k}{\frac{q-1}{2}} =\residuo{s+j}{\frac{q-1}{2}}$, and $\Occ(\alpha^k,\mathbf{c}_{q-1}(b))=0$ if $\residuo{k}{\frac{q-1}{2}} \not\in (j+I_0) \cup \{\residuo{s+j}{\frac{q-1}{2}}\}$. Therefore, by defining $Y=(y_0,y_1,\cdots,y_{\frac{q-1}{2}-1})$ as the integer vector of length $\frac{q-1}{2}$ whose entries are given by

$$y_i=\left\{ \begin{array}{cl}
		\;2\; & \mbox{ if } i \in j+I_0 \\
		\;1\; & \mbox{ if } i = \residuo{s+j}{\frac{q-1}{2}} \\
		\;0\; & \mbox{ otherwise}
			\end{array}
\right .\;,$$

\noindent
we have $w_{\rm cplt}(\mathbf{c}_{q-1}(b))=Y|Y=\sigma^j(W_0)|\sigma^j(W_0)$. In a quite similar way, it is easy to see that if $b' \in {\cal C}_{2j+1}^{(q-1,q^2)}$, for some $0\leq j<\frac{q-1}{2}$, then $w_{\rm cplt}(\mathbf{c}_{q-1}(b'))=\sigma^j(W_1)|\sigma^j(W_1)$. 
\end{proof}

