\subsection{The functions ${\cal G}$, ${\cal R}$, and ${\cal R}_k$}
As we will see later on, the vectors $W$, $W_0$ and $W_1$ are the key to obtaining the complete weight distribution of any irreducible cyclic code $\CLI_{N}$, with $N|(q-1)$. However, before that, we need to introduce some new notations. Thus, for positive integers $k$ and $l$, such that $k|(q-1)$ and $l|k$, we define the functions ${\cal G}:\bbbz^{k} \times \bbbz \to \bbbz^l$, ${\cal R}:\bbbz^l \to \bbbz^{q-1}$, and ${\cal R}_k:\bbbz^l \to \bbbz^{k}$ given by

\begin{eqnarray}
{\cal G}((v_0,v_1,\cdots,v_{k-1}),l)\!&:=&\sum_{i=0}^{\frac{k}{l}-1}(v_{il},v_{il+1},\cdots,v_{il+l-1})\;, \nonumber \\
{\cal R}((v_0,v_1,\cdots,v_{l-1}))\!&:=&\overbrace{(v_0,v_1,\cdots,v_{l-1})|(v_0,v_1,\cdots,v_{l-1})|\cdots|(v_0,v_1,\cdots,v_{l-1})}^{\frac{q-1}{l} \mbox{ times}}\;, \nonumber \\
{\cal R}_k((v_0,v_1,\cdots,v_{l-1}))\!&:=&\overbrace{(v_0,v_1,\cdots,v_{l-1})|(v_0,v_1,\cdots,v_{l-1})|\cdots|(v_0,v_1,\cdots,v_{l-1})}^{\frac{k}{l} \mbox{ times}}\;, \nonumber
\end{eqnarray}

\noindent
where the previous sum is over the vectors of length $l$ with integer components and, again, the operator ``$|$'' stands for the vector concatenation. 

There exist some interesting relationships among the functions $\sigma$, ${\cal G}$, ${\cal R}$, and ${\cal R}_k$:

\begin{remark}\label{remrel}
Let $k$ and $l$ be as before. Let $V\in \bbbz^{k}$, $Y\in \bbbz^{l}$. Then observe that

$$\sum_{m=0}^{\frac{k}{l}-1}\sigma^{lm}(V)={\cal R}_k({\cal G}(V,l))\;\;\;\mbox{ and}$$
$${\cal R}(Y)=\overbrace{{\cal R}_k(Y)|{\cal R}_k(Y)|\cdots|{\cal R}_k(Y)}^{\frac{q-1}{k} \mbox{ times}}\;.$$
\end{remark}


For example, if $q=13$, $k=6$, $l=2$ and $V=(2,2,0,1,0,2)$, then ${\cal G}(V,6)=V$ whereas ${\cal G}(V,2)=(2,2)+(0,1)+(0,2)=(2,5)$. Thus ${\cal R}({\cal G}(V,6))=(2,2,0,1,0,2,2,2,0,1,0,2)$, $\frac{k}{l}=3$, 

\begin{eqnarray}
\sum_{m=0}^{2}\sigma^{2m}(V)&=&{\cal R}_k({\cal G}(V,2))={\cal G}(V,2)|{\cal G}(V,2)|{\cal G}(V,2)=(2,5,2,5,2,5)\;,\;\;\mbox{ and} \nonumber \\
{\cal R}({\cal G}(V,2))&=&{\cal R}_k({\cal G}(V,2))|{\cal R}_k({\cal G}(V,2))=(2,5,2,5,2,5,2,5,2,5,2,5)\;. \nonumber
\end{eqnarray}

For our vectors $W$, $W_0$, and $W_1$ we have the following:

\begin{proposition}\label{prorel}
Let $W$, $W_0$, and $W_1$ be as before, and let $N$ and $t$ be positive integers such that $N|(q-1)$ and $t=\frac{q-1}{N}$. Let $j$ be an integer such that $0\leq j<\frac{N}{2}$ if $N$ is even and $0\leq j<N$ otherwise. Additionally, let $e$ be a positive integer. Then,

\begin{equation}\label{rm3eq1}
\sum_{m=0}^{t-1} \sigma^{j+Nm}(W)={\cal R}(\sigma^j({\cal G}(W,N)))\;,
\end{equation}

\noindent
while if $q$ is odd and $N$ is even, then, for $v \in \{0,1\}$, we have:

\begin{equation}\label{rm3eq2}
\sum_{m=0}^{t-1} \sigma^{j+\frac{N}{2}m}(W_v|W_v)={\cal R}(\sigma^j({\cal G}(W_v,\frac{N}{2})))\;, 
\end{equation}

\noindent
and if $q$ is odd and $N$ is odd, then we have:

\begin{equation}\label{rm3eq3}
\sum_{m=0}^{\frac{t}{2}-1} \sigma^{j+Nm}(W_0|W_0)+\sigma^{j+e+Nm}(W_1|W_1)={\cal R}(\sigma^j({\cal G}(W_0+\sigma^e(W_1),N)))\;.
\end{equation}
\end{proposition}

\begin{proof} Suppose that $q$ is odd and $N$ is odd. Then

\begin{eqnarray}
\sum_{m=0}^{\frac{t}{2}-1} \sigma^{j+Nm}(W_0|W_0)+\sigma^{j+e+Nm}(W_1|W_1)\!\!\!&=&\!\!\!\sum_{m=0}^{\frac{t}{2}-1}\sigma^{Nm}(\sigma^{j}(W_0+\sigma^e(W_1))|\sigma^{j}(W_0+\sigma^e(W_1)))\;, \nonumber \\
\!\!\!&=&\!\!\!\sum_{m=0}^{\frac{t}{2}-1}\sigma^{Nm}(\sigma^{j}(W_0+\sigma^e(W_1)))|\sum_{m=0}^{\frac{t}{2}-1}\sigma^{Nm}(\sigma^{j}(W_0+\sigma^e(W_1)))\;. \nonumber
\end{eqnarray} 

\noindent
Since $N$ is odd, $N|\frac{q-1}{2}$. Let $k=\frac{q-1}{2}$ and note that $\frac{k}{N}=\frac{t}{2}$. Then, owing to Remark \ref{remrel},

$$\sum_{m=0}^{\frac{t}{2}-1}\sigma^{Nm}(\sigma^{j}(W_0+\sigma^e(W_1)))={\cal R}_k({\cal G}(\sigma^{j}(W_0+\sigma^e(W_1)),N))\;.$$

\noindent
Therefore

\begin{eqnarray}
\sum_{m=0}^{\frac{t}{2}-1} \sigma^{j+Nm}(W_0|W_0)+\sigma^{j+e+Nm}(W_1|W_1)\!\!\!&=&\!\!\!{\cal R}_k({\cal G}(\sigma^{j}(W_0+\sigma^e(W_1)),N))|{\cal R}_k({\cal G}(\sigma^{j}(W_0+\sigma^e(W_1)),N))\;, \nonumber \\
\!\!\!&=&\!\!\!{\cal R}({\cal G}(\sigma^{j}(W_0+\sigma^e(W_1)),N))\;, \nonumber \\
\!\!\!&=&\!\!\!{\cal R}(\sigma^j({\cal G}(W_0+\sigma^e(W_1),N)))\;. \nonumber
\end{eqnarray} 

\noindent
In a similar way, (\ref{rm3eq1}) and (\ref{rm3eq2}) can be proved. 
\end{proof}

\begin{example}\label{ejtres}
$ $
\begin{enumerate}
\item[{\rm (A)}] Let $\bbbf_{16}=\bbbf_2(\alpha)$, with $\alpha^4+\alpha+1=0$. Note that $\langle \alpha \rangle=\bbbf_{16}^*$. Then it is not difficult to obtain that $\frac{q}{2}=8$, $R=\{4,13,8,6,3,7,0\}$, $I=\{1,2,5,9,10,11,12,14\}$ and therefore 

\begin{equation}\label{eq16}
W=(0,2,2,0,0,2,0,0,0,2,2,2,2,0,2)\;.
\end{equation}

\noindent
Let $(N,j)=(5,2)$, thus $t=3$ and

\begin{eqnarray}
\sigma^{2+5(0)}(W)&=&\sigma^{\;2}(W)=(0,2,0,2,2,0,0,2,0,0,0,2,2,2,2)\;, \nonumber \\
\sigma^{2+5(1)}(W)&=&\sigma^{\;7}(W)=(0,2,2,2,2,0,2,0,2,2,0,0,2,0,0)\;, \nonumber \\
\sigma^{2+5(2)}(W)&=&\sigma^{ 12}(W)\!=(0,0,2,0,0,0,2,2,2,2,0,2,0,2,2)\;. \nonumber
\end{eqnarray}

\noindent
On the other hand, note that ${\cal G}(W,N)=(0,2,2,0,0)+(2,0,0,0,2)+(2,2,2,0,2)=(4,4,4,0,4)$, $\sigma^2({\cal G}(W,N))=(0,4,4,4,4)$  and clearly

$$\sigma^{2}(W)+\sigma^{7}(W)+\sigma^{12}(W)=(0,4,4,4,4,0,4,4,4,4,0,4,4,4,4)={\cal R}(0,4,4,4,4)\;,$$

\noindent
which is in accordance with (\ref{rm3eq1}).

\item[{\rm (B)}] Let $(q,N)=(9,4)$. Thus $t=2$, $\frac{N}{2}=2$, and from Example \ref{ejdos} {\rm (B)}, $W_0=(1,2,0,2)$. With $j=1$, we have

\begin{eqnarray}
\sigma^{1+2(0)}(W_0|W_0)&=&\sigma^{1}(W_0|W_0)=(2,1,2,0,2,1,2,0)\;, \nonumber \\
\sigma^{1+2(1)}(W_0|W_0)&=&\sigma^{3}(W_0|W_0)=(2,0,2,1,2,0,2,1)\;. \nonumber
\end{eqnarray}

\noindent
On the other hand, note that ${\cal G}(W_0,2)=(1,2)+(0,2)=(1,4)$, $\sigma^1(1,4)=(4,1)$ and clearly

$$\sigma^{1}(W_0|W_0)+\sigma^{3}(W_0|W_0)=(4,1,4,1,4,1,4,1)={\cal R}(4,1)\;,$$

\noindent
which is in accordance with (\ref{rm3eq2}).

\item[{\rm (C)}] Let $(q,N,e)=(11,5,2)$. Thus $t/2=1$ and from Example \ref{ejdos} {\rm (C)}, $W_0=(2,1,0,0,2)$ and $W_1=(0,2,2,0,2)$. With $j=3$, we have

\begin{eqnarray}
\sigma^{3+5(0)}(W_0|W_0)&=&\sigma^{3}(W_0|W_0)  =(0,0,2,2,1,0,0,2,2,1)\;, \nonumber \\
\sigma^{3+2+5(0)}(W_1|W_1)&=&\sigma^{5}(W_1|W_1)=(0,2,2,0,2,0,2,2,0,2)\;. \nonumber
\end{eqnarray}

\noindent
On the other hand, ${\cal G}(W_0+\sigma^2(W_1),5)={\cal G}((2,3,0,2,4),5)=(2,3,0,2,4)$, $\sigma^3(2,3,0,2,4)=(0,2,4,2,3)$ and clearly

$$\sigma^{3}(W_0|W_0)+\sigma^{5}(W_1|W_1)=(0,2,4,2,3,0,2,4,2,3)={\cal R}(0,2,4,2,3)\;,$$

\noindent
which is in accordance with (\ref{rm3eq3}).
\end{enumerate}
\end{example}

