\subsection{The complete weight enumerator of the family of irreducible cyclic codes $\CLI_{N}$ with $N|(q-1)$}
We are now interested in extending our previous result to the family of irreducible cyclic codes of length $n$, such that $Nn=q^2-1$ and $N|(q-1)$. So, once again in terms of the three vectors $W$, $W_0$, and $W_1$, and for any $N|(q-1)$, the following result determines the complete weight enumerator for any irreducible cyclic code, $\CLI_N$, of length $n=\frac{q^2-1}{N}$ and dimension $2$ over any finite field $\bbbf_q$.

\begin{theorem}\label{teotres}
Let $W$, $W_0$, and $W_1$ be as before and let $N$ be a positive integer such that $N|(q-1)$. If $N$ is odd, fix $e=\frac{N-1}{2}$. Then $\CLI_{N}$ is a cyclic code of length $n=\frac{q^2-1}{N}$ and dimension $2$. In addition, if $q$ is even, then $\CLI_{N}$ is an $[n,2]$ one-weight irreducible cyclic code whose nonzero weight is $q\frac{q-1}{N}$ and whose complete weight enumerator is:

\begin{equation}\label{teo3eq1}
\mbox{\rm CWE}_{\CLI_N}(Z)=1+n\sum_{j=0}^{N-1} \:Z^{{\cal R}(\sigma^j({\cal G}(W,N)))} \;.
\end{equation}

\noindent
If $q$ is odd and $N$ is even, then $\CLI_{N}$ is an $[n,2]$ two-weight irreducible cyclic code whose nonzero weights are $n-\frac{2n}{q+1}$ and $n$, and whose complete weight enumerator is:

\begin{equation}\label{teo3eq2}
\mbox{\rm CWE}_{\CLI_N}(Z)=1+n\sum_{j=0}^{\frac{N}{2}-1} \:[Z^{{\cal R}(\sigma^j({\cal G}(W_0,\frac{N}{2})))}+Z^{{\cal R}(\sigma^j({\cal G}(W_1,\frac{N}{2})))}]\;,
\end{equation}

\noindent
and if $q$ is odd and $N$ is odd, then $\CLI_{N}$ is an $[n,2]$ one-weight irreducible cyclic code whose nonzero weight is $q\frac{q-1}{N}$ and whose complete weight enumerator is:

\begin{equation}\label{teo3eq3}
\mbox{\rm CWE}_{\CLI_N}(Z)=1+n\sum_{j=0}^{N-1} \:Z^{{\cal R}(\sigma^j({\cal G}(W_0+\sigma^e(W_1),N)))}\;.
\end{equation}
\end{theorem}

\begin{proof}
Since $q+1 \leq n=\frac{q^2-1}{N}$, $\ord_{n}(q)=2$, therefore in accordance with Definition \ref{defuno}, $\CLI_{N}$, is a cyclic code of length $n$ and dimension $2$. Clearly $u=\gcd(q+1,N)=1$ if ether $q$ is even or $q$ is odd and $N$ is odd. On the other hand, $u=2$ if $q$ is odd and $N$ even. Therefore, owing to Theorem \ref{teoseis}, if ether $q$ is even or $q$ is odd and $N$ is odd, then $\CLI_{N}$ is an $[n,2]$ one-weight irreducible cyclic code whose nonzero weight is $\frac{n}{q+1}q$, and if $q$ is odd and $N$ even, then $\CLI_{N}$ is an $[n,2]$ two-weight irreducible cyclic code whose nonzero weights are $n-\frac{2n}{q+1}$ and $n$.   

Fix $t=\frac{q-1}{N}$ and note that, for any integer $l$, we have

$${\cal C}_{l}^{(N,q^2)}=\bigcup_{m=0}^{t-1} {\cal C}_{l+Nm}^{(q-1,q^2)}\;.$$

Assume that $q$ is even and let $a \in {\cal C}_{i}^{(N,q^2)}$, for some $0\leq i<N$. Since $N$ is odd, there must exist a unique integer $0\leq j<N$ such that $i=\residuo{2j+1}{N}$, where we recall here that $\residuo{2j+1}{N}$ is the remainder of the division of $2j+1$ by $N$. Similarly, observe that 

$$\{\: Nm \:|\:0\leq m<t\: \}=\{\: \residuo{2Nm}{q-1} \:|\:0\leq m<t\: \}\;,$$ 

\noindent
thus

$$\{\: \residuo{2j+1+Nm}{q-1} \:|\:0\leq m<t\: \}=\{\: \residuo{2(j+Nm)+1}{q-1} \:|\:0\leq m<t\: \}\;.$$

\noindent
Therefore 

$${\cal C}_{i}^{(N,q^2)}={\cal C}_{2j+1}^{(N,q^2)}=\bigcup_{m=0}^{t-1} {\cal C}_{2j+1+Nm}^{(q-1,q^2)}=\bigcup_{m=0}^{t-1} {\cal C}_{2(j+Nm)+1}^{(q-1,q^2)}\;.$$

\noindent
Let $a_0,a_1,\cdots,a_{t-1} \in {\cal C}_{i}^{(N,q^2)}$ such that $a_m \in {\cal C}_{2(j+Nm)+1}^{(q-1,q^2)}$, for $m=0,1,\cdots,t-1$. But 

\begin{eqnarray}
{\cal C}_{i}^{(N,q^2)}&=&\{\: a\gamma^{N k} \:|\:0\leq k<n=(q+1)t \:\}\;\;\;\mbox{ and } \nonumber \\
{\cal C}_{2(j+Nm)+1}^{(q-1,q^2)}&=&\{\: a_m\gamma^{(q-1) k} \:|\:0\leq k<q+1 \:\}\;,  \nonumber
\end{eqnarray}

\noindent
thus

\begin{eqnarray}
w_{\rm cplt}(\mathbf{c}_{N}(a))&=&\sum_{m=0}^{t-1}w_{\rm cplt}(\mathbf{c}_{q-1}(a_m))\;,  \nonumber \\
&=&\sum_{m=0}^{t-1} \sigma^{j+Nm}(W)\;,  \nonumber \\
&=&{\cal R}(\sigma^j({\cal G}(W,N)))\;, \nonumber
\end{eqnarray}

\noindent
where the second and the third equalities come from (\ref{pr2eq1}) and (\ref{rm3eq1}), respectively. In consequence (\ref{teo3eq1}) now follows from the fact that $0\leq j<N$ and $|{\cal C}_{i}^{(N,q^2)}|=\frac{q^2-1}{N}=n$.

Assume that $q$ is odd and $N$ is even. Let $a \in {\cal C}_{i}^{(N,q^2)}$, for some $0\leq i<N$. Then, there must exist unique integers $0\leq j<\frac{N}{2}$ and $v\in\{0,1\}$ such that $i=2j+v$. Therefore, 

$${\cal C}_{i}^{(N,q^2)}={\cal C}_{2j+v}^{(N,q^2)}=\bigcup_{m=0}^{t-1} {\cal C}_{2j+v+Nm}^{(q-1,q^2)}=\bigcup_{m=0}^{t-1} {\cal C}_{2(j+\frac{N}{2}m)+v}^{(q-1,q^2)}\;.$$

\noindent
Let $a_0,a_1,\cdots,a_{t-1} \in {\cal C}_{i}^{(N,q^2)}$ such that $a_m \in {\cal C}_{2(j+\frac{N}{2}m)+v}^{(q-1,q^2)}$, for $m=0,1,\cdots,t-1$. Thus, in a quite similar way as before, and by using now (\ref{pr2eq2}), (\ref{pr2eq3}), and (\ref{rm3eq2}), we have

$$w_{\rm cplt}(\mathbf{c}_{N}(a))=\sum_{m=0}^{t-1}w_{\rm cplt}(\mathbf{c}_{q-1}(a_m))=\sum_{m=0}^{t-1} \sigma^{j+\frac{N}{2}m}(W_v|W_v)={\cal R}(\sigma^j({\cal G}(W_v,\frac{N}{2})))\;.$$

\noindent
In consequence (\ref{teo3eq2}) now follows from the fact that $0\leq j<\frac{N}{2}$, $v\in\{0,1\}$, and $|{\cal C}_{i}^{(N,q^2)}|=\frac{q^2-1}{N}=n$.

Assume that $q$ and $N$ are odd. Observe that $t$ is even. Let $a \in {\cal C}_{i}^{(N,q^2)}$, for some $0\leq i<N$. Then, there must exist a unique integer $0\leq j<N$ given by 

$$j=\left\{ \begin{array}{cl}
		\;\frac{i}{2}\; & \mbox{ if $i$ is even,} \\
		\\
		\;\frac{i+N}{2}\; & \mbox{ if $i$ is odd.}
			\end{array}
\right .$$

\noindent
Thus, it is not difficult to see that

\begin{eqnarray}
\{\: i+Nm\:|\:0\leq m<t\: \}&=&\{\: 2(j+Nm)\:|\:0\leq m<\frac{t}{2}\: \}\cup \nonumber \\
&&\{\: \residuo{2(j+e+Nm)+1}{q-1}\:|\:0\leq m<\frac{t}{2}\: \}\;,  \nonumber
\end{eqnarray}

\noindent
therefore 

$${\cal C}_{i}^{(N,q^2)}=\bigcup_{m=0}^{t-1} {\cal C}_{i+Nm}^{(q-1,q^2)}=\bigcup_{m=0}^{\frac{t}{2}-1} \left({\cal C}_{2(j+Nm)}^{(q-1,q^2)}\cup {\cal C}_{2(j+e+Nm)+1}^{(q-1,q^2)}\right)\;.$$

\noindent
Let $a_0,a_1,\cdots,a_{\frac{t}{2}-1},a'_0,a'_1,\cdots,a'_{\frac{t}{2}-1} \in {\cal C}_{i}^{(N,q^2)}$ such that $a_m \in {\cal C}_{2(j+Nm)}^{(q-1,q^2)}$ and $a'_m \in {\cal C}_{2(j+e+Nm)+1}^{(q-1,q^2)}$, for $m=0,1,\cdots,\frac{t}{2}-1$. Thus, in a quite similar way as before, and by using now (\ref{pr2eq2}), (\ref{pr2eq3}), and (\ref{rm3eq3}), we have

\begin{eqnarray}
w_{\rm cplt}(\mathbf{c}_{N}(a))&=&\sum_{m=0}^{\frac{t}{2}-1}\left(w_{\rm cplt}(\mathbf{c}_{q-1}(a_m))+w_{\rm cplt}(\mathbf{c}_{q-1}(a'_m))\right)\;,  \nonumber \\
&=&\sum_{m=0}^{\frac{t}{2}-1} \sigma^{j+Nm}(W_0|W_0)+\sigma^{j+e+Nm}(W_1|W_1)\;,  \nonumber \\
&=&{\cal R}(\sigma^j({\cal G}(W_0+\sigma^e(W_1),N)))\;. \nonumber
\end{eqnarray}

\noindent
In consequence (\ref{teo3eq3}) now follows from the fact that $0\leq j<N$ and $|{\cal C}_{i}^{(N,q^2)}|=\frac{q^2-1}{N}=n$.
\end{proof}

