    \item \textbf{Encoder architecture:} Linear Compression Encoder (LCE), MLP, Vanilla Transformer (take last $\text{N}_\text{out}$ output embeddings), Funnel Transformer \cite{Dai2020FunnelTransformerFO}
\end{enumerate}

