\begin{lemma}\label{lemma:genIrules}
  We have the following results:
  \begin{enumerate}
    \item\label{genIrules:1} $\widr$ is derivable in $\BiV$;
    \item\label{genIrules:2} $\biur$ is derivable in $\SIBV$; 
    \item\label{genIrules:3} $\baiur$, $\wqur$, and $\bqur$ are derivable in $\BiV\cup\set{\biur,\tuur,\luur}$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  The first point is proven by induction on $A$ as shown in \Cref{fig:genIrule}.
  The second point is proven dually. For the third point, $\baiur$ is a special case of $\biur$, and derivability of $\wqur$ and $\bqur$ follows via the derivations shown in ~\Cref{fig:derive-up}, 
  where $P$ and $Q$ \resp{$R$ and $S$} are the premise and conclusion of $\wqur$ \resp{$\bqur$}.
  \qed
\end{proof}


\begin{lemma}\label{lemma:TFA}
  The following are equivalent:
  \begin{enumerate}
    \item $\proves[\BiV]A\limp B$;
    \item $\proves[\BiV]\cP[A]\limp \cP[B]$ for any positive context $\cP$;
    \item $\proves[\BiV]\cN[B]\limp \cN[A]$ for any negative context $\cN$;
  \end{enumerate}
\end{lemma}
\begin{proof}
  Note that 1 is a special case of 2. We prove $1\Rightarrow 2$ and $1\Rightarrow 3$ and $2\Leftrightarrow 3$ simultaneously by induction on the context, see \eqref{eq:contexts}. We show only two cases:
  %
