            \ltens
            \odnP{\lunit}{\widr}{C\limp C}{}
          }{}
        }
      }{\wlsr}{
        \left(\od{
          \odo{
            \odi{
              \odh{(\cN[B]\limp \cN[A])\limp C} 
            }{\blsr}{
              \cN[B]\ltens (\cN[A]\limp C)
            }{\brule}
          }{\tcomr}{
            (\cN[A]\limp C)\ltens \cN[B]
          }{}
        }\right)
        \limp C
      }{\wrule}
    }{\curry}{
      (\cN[A]\limp C) \limp (\cN[B] \limp C)
    }{}
  }
  \qquad\qquad
  \od{
    \odd{\odh{\lunit}}{\IH}{
      \odt{
