\begin{theorem}[Deduction Theorem]\label{thm:deduction}
  Let $A$ and $B$ be formulas. Then
  $$\proves[\SBiV]A\limp B  \iff \mbox{ there is a derivation } \od{\odd{\odh{A}}{\dDp}{B}{\SBiV}} \mydot$$
\end{theorem}
\begin{proof}
  Via the following two derivations:
  \begin{equation}\label{eq:deduction}
    \tag*{\normalsize\qed}
    \scriptsize
    \od{
      \odo{
        \odi{
          \odo{\odh{A}}{\tudr}{
            A\ltens 
            \left(\od{\odd{\odh{\lunit}}{}{A\limp B}{\SBiV}}\right)
            }{}
        }{\wtsr}{
          \odnP{A\limp A}{\biur}{\lunit}{\brule}
          \limp B
        }{\wrule}
      }{\luur}{
        B
      }{}
    }
    \qquad\qquad
    \od{
      \odi{\odh{\lunit}}{\widr}{
        A\limp \left(\od{\odd{\odh{A}}{}{B}{\SBiV}}\right)
      }{\wrule}
    }
  \end{equation}
\end{proof}
\begin{corollary}\label{cor:deduction}
  If $\proves[\SBiV]A\limp B$, then 
  \begin{itemize}
    \item there is a derivation in $\SBiV$ with premise $\cP[A]$ and conclusion $\cP[B]$ for any positive context $\cP$;
    \item there is a derivation in $\SBiV$ with premise $\cN[B]$ and conclusion $\cN[A]$ for any negative context $\cN$;
  \end{itemize}
\end{corollary}
\begin{proof}
  Consequence of the Deduction Theorem and \Cref{lemma:TFA}.
  \qed
\end{proof}


We conclude this section by proving that the \emph{Modus Ponens} is a valid logical inference in $\SBiV$.
\begin{corollary}[Modus Ponens]\label{cor:MP}
  Let $A$ and $B$ be formulas.
  If $\proves[\SBiV]A\limp B$ and $\proves[\SBiV]A$, then $\proves[\SBiV] B$.
\end{corollary}
\begin{proof}
  By hypothesis, we have a proof $\dDp_A$ with conclusion $A$, and the Deduction Theorem ensures the existence of a derivation $\dDp_{A\limp B}$ with premise $A$ and conclusion $B$.
  We conclude by composing `vertically' the two derivations.
\qed
\end{proof}


