A \defn{formula interpretation} of a sequent $B_1,\ldots,B_n \vdash A$ is a formula of the shape $(B_1\ltens \cdots\ltens B_n)\limp A$ for any bracketing of the $\ltens$. If $n=0$ then the unique \defn{formula interpretation} is just $A$. 
%\begin{remark}\label{rem:formulaInt}
Note that any two formula interpretations of a sequent are interderivable in $\IBV$ using the rules $\tcomr$ and $\tassr$. This allows us to define 
a sequent $\Gamma \vdash B$ to be \defn{derivable} in $\BiV$ if any of its formula interpretations is derivable in $\BiV$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lemma:IMLLtoIBV}
  Let $\rrule$ be an inference rule of $\MiLL$.
  If every premise of and instance of $\rrule$ is derivable in $\BiV$, then so is its conclusion.
\end{lemma}
\begin{proof}
  For the rules $\lunit$ and $\lltens$ this is trivial.
  %
  For  $\axrule$ it follows by a single instance of $\aidr$.
  %
  For $\rlimp$, observe that a formula interpretation of its conclusion can be obtained via  the $\curryrule$-rule from a formula interpretation of its premise.
  %
  Finally, for the rules $\llimp$ and $\rltens$, formula interpretations of their conclusions are derived via the following derivations:
  % 
  $$
  \adjustbox{max width=\textwidth}{$
  \od{\odp{\dD'}{
    \od{
      \odo{
        \odi{\odh{
            (\Gamma\limp A) 
            \ltens 
            \odtP{
              (\Delta\ltens B) \limp C
            }{\curryrule}{
              B\limp (\Delta\limp C)
            }{}
          }
        }{\wlsr}{
          \odnP{(\Gamma\limp A)\limp (B \ltens \Delta)}{\btsr}{
            \odnP{(\Gamma\limp A)\limp B}{\blsr}{
              \Gamma\ltens (A\limp B)
            }{\brule}
            \ltens \Delta
          }{\brule}
          \limp C
        }{\wrule}
      }{\curry}{
        (\Gamma \ltens \Delta \ltens (A\limp B)) \limp C
      }{}
    }
  }{}}
  \quand
  \od{\odp{\dD'}{
    \od{\odo{\odi{
      \odh{(\Gamma \limp A)\ltens (\Delta \limp B)}
    }{\wtsr}{
      \Gamma 
      \limp 
      \left(
        \od{
          \odi{
            \odo{\odh{A\ltens (\Delta \limp B)}}{\tcomr}{
              (\Delta \limp B)\ltens A
            }{}
          }{\wtsr}{\Delta\limp (A\ltens B)}{\wrule}}
      \right)
    }{\wrule}}{\uncurry}{
      (\Gamma\ltens \Delta) \limp (A\ltens B)
    }{}}
    }{}}
  $}
  $$
  where $\dD'$ are derivations of formula interpretations of their premises.
  \qed
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lemma:IBVtoIMLL}
  (i) Let $\rrule\in\BiV$, and let $A$ and $B$ be formulas not containing any occurrence of~$\lseq$. If $\nodn{A}{\rrule}{B}{\wrule}$ then $A\vdash B$ is derivable in $\MiLL$, and if $\nodn{A}{\rrule}{B}{\brule}$ then $B\vdash A$ is derivable in $\MiLL$.
  %
  (ii) Let $\cP$ and $\cN$ be a positive and a negative $\lseq$-free context, respectively. If $A\vdash B$ is derivable in $\MiLL$, then so are $\cP[A]\vdash\cP[B]$ and $\cN[B]\vdash\cN[A]$.
\end{lemma}
\begin{proof}
  (i)
  Cases for the rule $\tudr$, $\ludr$, $\tcomr$, and $\tassr$ are the standard derivations to prove that associativity and commutativity of $\ltens$, and the fact that $\lunit$ is the unit for $\ltens$ and the left-unit of $\limp$.
  Cases for rules $\waidr$ and $\curryrule$ are the following:
  % 
  $$
  \adjustbox{max width=\textwidth}{$
  \vlderivation{
    \vlin{\llimp}{}{\lunit \vdash a\limp a}{
      \vlin{\lunitl}{}{\lunit,a\vdash a}{
        \vlin{\axrule}{}{a\vdash a}{\vlhy{}}
      }
    }
  }
  \qquad
  \vlderivation{
    \vliq{\rlimp+\lltens}{}{
      A\limp (B\limp C)\vdash (A\ltens B)\limp C
    }{
      \vliiiq{2\times\llimp}{}{A\limp (B\limp C), A,B\vdash C}{
        \vlin{\axrule}{}{A\vdash A}{\vlhy{}}
      }{
        \vlin{\axrule}{}{B\vdash B}{\vlhy{}}
      }{
        \vlin{\axrule}{}{C\vdash C}{\vlhy{}}
      }
    }
  }
  \qquad
  \vlderivation{
    \vliq{2\times \rlimp}{}{
      (A\ltens B)\limp C\vdash A\limp (B\limp C)
    }{
      \vliiiq{\llimp+\rltens}{}{(A\ltens B)\limp C, A,B\vdash C}{
        \vlin{\axrule}{}{A\vdash A}{\vlhy{}}
      }{
        \vlin{\axrule}{}{B\vdash B}{\vlhy{}}
      }{
        \vlin{\axrule}{}{C\vdash C}{\vlhy{}}
      }
    }
  }
  $}
  $$
  % 
  If $\rrule\in\set{\wlsr,\wtsr,\btsr,\blsr}$, then we have either the following derivations
  \begin{equation}\label{eq:srulesIMLL}
  \small
  \vlderivation{
    \vliq{\rlimp+\lltens}{}{
      (A\limp B)\ltens C \vdash A\limp(B\ltens C)
    }{
      \vliiiq{\llimp+\rltens}{}{
        (A\limp B),C, A\vdash B\ltens C
      }{
        \vlin{\axrule}{}{A\vdash A}{\vlhy{}}
      }{
        \vlin{\axrule}{}{B\vdash B}{\vlhy{}}
      }{
        \vlin{\axrule}{}{C\vdash C}{\vlhy{}}
      }
    }
  }
  \qquad\quad
  \vlderivation{
    \vliq{\rlimp+\lltens}{}{
      A \ltens (B\limp C) \vdash (A\limp B) \limp C
    }{
      \vliiiq{2\times\llimp}{}{
        A , B\limp C , A\limp B \vdash C
      }{
        \vlin{\axrule}{}{A\vdash A}{\vlhy{}}
      }{
        \vlin{\axrule}{}{B\vdash B}{\vlhy{}}
      }{
        \vlin{\axrule}{}{C\vdash C}{\vlhy{}}
      }
    }
  }
  \end{equation}
  (ii) is shown by induction on the context, where both statements are proved simultaneously.
  \qed
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}\label{thm:BiVextensMiLL}
  $\BiV$ is a conservative extension of $\MiLL$.
\end{theorem}
\begin{proof}
  Given a proof $\pi$ in $\MiLL$, we can construct by induction a proof in $\BiV$ of the formula interpretation of its conclusion using \Cref{lemma:IMLLtoIBV}.

  Conversely, assume we have proof $\dDp_A$ in $\BiV$ of a formula $A$ in $\BiV$.
  We construct a proof $\pi_A$ in $\MiLL$ with the same conclusion by induction on the number of rules in $\dDp_A$.
  We consider as base case $\aidr$, whose conclusion derivable in $\MiLL$ using $\axrule$ and~$\rlimp$.
  For the inductive case, consider a bottommost rule instance $\rrule$ in $\dDp_A$, as shown on the left below. The desired cut-free derivation in $\MiLL$ is obtained by applying cut-elimination (\Cref{thm:cutElimIMLL}) to the derivation in the middle below:
  \begin{equation}\label{eq:de-deeping}
    \dDp_A=
    \od{
      \odp{}{\cC[\odn{B'}{\rrule}{B}{}]}{\BiV}
    }
    % 
  \;\rightsquigarrow\;
    %
    \vlderivation{
      \vliin{\cutr}{}{\vdash \cC[B]}{
        \vlhtrl{\pi_1}{}{}{\cC[B']}{~~} 
      }{
        \vlhtrl{\pi_2}{}{}{\cC[B']\vdash \cC[B]}{~~} 
      }
    }
    %
  \;\xRightarrow{\text{cut-elim.}}\;
    %
    \vlderivation{\vlhtrl{\pi_A}{}{}{\vdash \cC[B]}{~~}}
  \end{equation}
  where $\cC$ is positive if $\rrule$ is a $\wsymb$-rule and negative if $\rrule$ is a $\bsymb$-rule.
  %
  Then $\pi_1$ exists by induction hypothesis and the existence of $\pi_2$ is guaranteed by \Cref{lemma:IBVtoIMLL}.
  \qed
\end{proof}
