  $$
  \begin{array}{c}
      \vlinf{\axrule}{}{\vdash a,\cneg a}{}
  \quad
      \vlinf{\lpar}{}{\vdash \Gamma, A\lpar B}{\vdash \Gamma, A, B}
  \quad
      \vliinf{\ltens}{}{\vdash  \Gamma, \Delta, A\ltens B}{\vdash \Gamma,A}{\vdash \Delta, B}
  \quad
      \vliinf{\lprec}{n\geq 0}{
        \vdash \Gamma, \Delta, A_1\lprec B_1, \ldots, A_n\lprec B_n
      }{
        \vdash \Gamma , A_1, \ldots,A_n
