%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



The argument of Tiu~\cite{tiu:SIS-II} that there is no shallow proof system for $\BV$ makes crucial use of the associativity of~$\lseq$. 
This inspired~\cite{acc:man:PN} to design the logic $\NML$, which is a conservative extension of $\MLL$ with a non-commutative and \emph{non-associative} self-dual connective, and which has a cut-free sequent calculus.

In this section, we investigate the intuitionistic version of that logic, that we call \defn{$\INML$}, and which is obtained from the sequent calculus of $\IMLL$ (shown in Figure~\ref{fig:IMLL}) extended by the rule~$\lseq$ shown below: 
\begin{equation}\label{eq:precRule}
  \vliinf{\lprec}{n\geq 0}{\Gamma,\Delta, A_1\lprec B_1, \ldots, A_n\lprec B_n \vdash A\lprec B}{
    \Gamma,A_1, \ldots, A_n\vdash A
  }{
    \Delta, B_1, \ldots, B_n \vdash B
  }
\end{equation}
\begin{theorem}
  The rule $\AXrule$ is derivable in $\NiML$.
\end{theorem}
\begin{theorem}
  The rule $\cutr$ is admissible in $\NiML$.
\end{theorem}
\begin{proof}
  The proof is the same as for $\IMLL$, with one cut-elimination step added for the $\lseq$-rule:
  $$\adjustbox{max width=\textwidth}{$
    \vlderivation{
      \vliin{\cutr}{}{
        \Gamma,\Delta \vdash C\lprec D
      }{
        \vliin{\lprec}{n}{\Gamma\vdash A\lprec B}{
          \vlhy{\Gamma_1\vdash A}
        }{
          \vlhy{\Gamma_2\vdash B}
        }
      }{
        \vliin{\lprec}{m+1}{A\lprec B, \Delta \vdash C\lprec D}{
          \vlhy{A,\Delta_1 \vdash C}
        }{
          \vlhy{B,\Delta_2 \vdash D}
        }
      }
    }
    % 
  \;\rightsquigarrow\;
    % 
    \vlderivation{
      \vliin{\lprec}{n+m}{
        \Gamma,\Delta \vdash C\lprec D
      }{
        \vliin{\cutr}{}{\Gamma_1,\Delta_1\vdash C}{
          \vlhy{\Gamma_1\vdash A}
        }{
          \vlhy{A,\Delta_1 \vdash C}
        }
      }{
        \vliin{\cutr}{}{\Gamma_2, \Delta_2 \vdash D}{
          \vlhy{\Gamma_2\vdash B}
        }{
          \vlhy{B,\Delta_2 \vdash D}
        }
      }
    }
    $}$$
  where $\Gamma$ (resp.~$\Delta$) can contain formulas of the shape $E\lseq F$, which are decomposed in $\Gamma_1$ and $\Gamma_2$ (resp.~$\Delta_1$ and $\Delta_2$).
  \qed
\end{proof}
The logic $\INML$ is indeed the same logic as we would obtain by removing associativity of $\lseq$ from $\IBV$.

\begin{restatable}{theorem}{BiVextensNiML}\label{thm:BiVextensNiML}
  Let $A$ be a formula.
  Then ~$\proves[\NiML]A$ ~iff~ $\proves[\IBV\setminus\set{\sassr,\sassl}]A$~.
\end{restatable}
\begin{proof}
  Most of the work has already been done in Lemmas~\ref{lemma:IMLLtoIBV} and~\ref{lemma:IBVtoIMLL}. It remains to show that (i) Lemma~\ref{lemma:IMLLtoIBV} also applies to the rule $\lseq$ in~\eqref{eq:precRule}, and that $\sassr$, $\sassl$ are not needed for this, and (ii) that Lemma~\ref{lemma:IBVtoIMLL} also applies to the $\qdr$-, $\sqir$-, and $\refrule$-rules, when we use $\INML$ instead of $\IMLL$. 
  Details in \Cref{app:assoc}.
  \qed
\end{proof}

Unsurprisingly, we have for $\INML$ the same conservativity results as we proved for $\IBV$ in the previous two sections.

\begin{theorem}
  $\NiML$ is a conservative extension of $\MiLL$.
\end{theorem}
\begin{proof}
  It suffices to remark that all rules in $\NiML$ have the subformula property, so any proof of a $\lseq$-free formula in $\NiML$ can only use rules in $\MiLL$.
  \qed
\end{proof}

We now would like to show that $\NML$ is conservative over $\INML$, but we encounter the same problems with the units as in $\BV$. We therefore consider only unit-free formulas, and the unit-free version of $\NML$, that we call \defn{$\NMLm$}, and which is shown in~\Cref{fig:NML}.
\begin{restatable}{theorem}{NMLextensNiML}\label{thm:NMLextensNiML}
  Let $A$ be a unit-free formula.
  We have~ $\proves[\INML]A$ ~iff~ $\proves[\NMLm]{\emb{A}}$~.
\end{restatable}
\begin{proof}
  This follows in the same way as (unit-free) $\MLLx$ is conservative over unit-free $\IMLL$.
  See \Cref{app:assoc} for details.
\qed
\end{proof}


We conclude this section by observing that the cut restricted to associativity of $\lseq$ is enough to obtain from $\INML$ a sequent calculus for $\IBV$.
To this end, we introduce the following \defn{associative-cut} rules:
\begin{equation}\label{eq:asso-cut}
  \adjustbox{max width=.9\textwidth}{$
  \vliinf{\acutl}{}{
    \Gamma \vdash D
  }{
    \Gamma \vdash (A\lprec B) \lprec C 
  }{
    A\lprec (B \lprec C) , \Delta \vdash D
  }
  \qquad
  \vliinf{\acutr}{}{
    \Gamma \vdash D
  }{
    \Gamma \vdash A\lprec (B \lprec C) 
  }{
     (A\lprec B) \lprec C,\Delta \vdash D
  }
  $}
\end{equation}


\begin{restatable}{theorem}{BiVextensNiMLcut}\label{thm:BiVextensNiMLcut}
  Let $A$ be a formula.
  Then $\proves[\BiV]A$ ~iff~ $\proves[\NiML\cup\set{\acutl,\acutr}]A$.
\end{restatable}
\begin{proof}
  As before, it suffices to extend Lemmas~\ref{lemma:IMLLtoIBV} and~\ref{lemma:IBVtoIMLL}.
  Note that for simulating $\acutl$ and $\acutr$ in $\IBV$, we use $\biur$ and then apply Corollary~\ref{cor:iur}.
  \qed
\end{proof}

\begin{remark}
  A sequent calculus for $\BV$ could be obtained by adding to the cut-free sequent system $\NML$ with the unit 
  from \cite{acc:man:PN} the one-side version of the rule $\acutr$.
\end{remark}


