\section{Proof for Footnote~\ref{fn:collapse}}\label{app:collapse}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{proposition}\label{prop:collapse}
  If $(\lunit\lseq A)\limp A$ and  $(A\lseq \lunit)\limp A$ were provable in $\IBV$, then $\lseq$ and $\ltens$ would collapse (in the sense that $A\lseq B$ and $A\ltens B$ would be logically equivalent formulas).
\end{proposition}
\begin{proof}
  The implication $(A \ltens B) \limp (A \lseq B)$ already holds in $\BV$ and $\IBV$ (it suffices to apply a $\brr$ and a $\widr$).
  For the other implication $(A\lseq B) \limp (A\ltens B)$, assume we have  $(\lunit\lseq A)\limp A$ and $(A\lseq \lunit)\limp A$ for every $A$. By \Cref{lemma:TFA}, there should be negative derivations $\dD_{\lunit\lseq}$ and $\dD_{\lseq\lunit}$ in $\SIBV$ with premise $A$ and conclusion $\lunit\lseq A$ and $A\lseq \lunit$ respectively, for any formula $A$.
  Then, we could construct a proof of $(A\lseq B) \limp (A\ltens B)$ in $\IBV$ by applying up-rules elimination (\Cref{thm:uprules}) to the following derivation in $\SIBV$:
  $$\small
  \odn{\lunit}{\idr}{
    \odnP{
      \oddbP[\dD_{\lseq\lunit}]{A}{A\lseq \lunit}
      \ltens 
      \oddbP[\dD_{\lunit\lseq}]{B}{\lunit\lseq B}
    }{\bqdr}{
      \odtP{A\ltens \lunit}{\tuur}{A}{}
      \lseq
      \odtP{\lunit\ltens B}{\tuur}{B}{}
    }{\brule}
    \limp
    (A\ltens B)
  }{\wrule}
  $$
\qed
\end{proof}




