\contextReduction*
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proof}
  By induction on the structure of each context --- see \eqref{eq:contexts}.
  We here only discuss here the cases for the positive contexts, since the arguments for the same cases for the negative contexts are analogous, with some minor differences in the (polarities of the) rules used.
  \begin{itemize}
    \item 
    If $\cP=H\limp \ctx $ we conclude immediately by letting $H=K$ and $\dD_X$ being the identity derivation.

    \item 
    If $\cP=H\limp(J\ltens \cPp)$, then we can apply splitting to get derivations 
    $$\small
      \oddb[\dD_H]{H_J\ltens H_P}H
    \quand
      \odpr[\dD_J]{H_J\limp J}
    \quand
      \odpr{H_P\limp \cPp[A]}
    $$
    We can then apply the inductive hypothesis on $H_P\limp \cPp[A]$, giving us derivations
    \begin{equation}\label{eq:contextReduction:1}\small
      \oddr[\dD_P]{K\limp X}{H_P \limp \cPp[X]}
    \quand
      \odpr[\dD_A]{K\limp A}
    \qquad \mbox{for any formula $X$.}
    \end{equation}
    We conclude since we have the following derivation for any formula $X$:
    $$\small
    \od{
      \odo{
        \odo{
          \odh{\oddr[\dD_P]{K\limp X}{
            H_P 
            \limp 
            \odnP{\oddrP[\dD_J]{\lunit}{H_J\limp J}\ltens \cPp[X]
            }{\wtsr}{
              H_J\limp (J \ltens \cPp[X])
            }{\wrule}
          }}
        }{\uncurry}{
          \oddbP[\dD_H]{H_J\ltens H_P}H
          \limp 
          (J\ltens \cPp[X])
        }{}
      }{\defr}{
        \cP[X]
      }{}
    }
    $$

    \item 
    The case $\cP=H\limp(\cPp\ltens J)$ is similar to the previous one.

    \item
    If $\cP=H\limp (J\lseq \cPp)$, then we can apply splitting to get derivations 
    $$\small
      \oddr[\dD_H]{H_J\lseq H_P}H
    \quand
      \odpr[\dD_J]{H_J\limp J}
    \quand  
      \odpr{H_P\limp \cPp[A]}
    $$
    and we can apply the inductive hypothesis on $H_P\limp \cPp[A]$, giving us derivations as in \Cref{eq:contextReduction:1}.
    We conclude since we have the following derivation for any formula $X$:
    $$\small
      \od{
        \odo{
          \odi{\odi{\odh{\oddr[\dD_P]{K\limp X}{H_P \limp \cPp[X]}}
            }{\wsudr}{
              \oddrP[\dD_J]{\lunit}{H_J\limp J} \lseq (H_P \limp \cPp[X])
            }{\wrule}
          }{\wqdr}{
            \oddbP[\dD_H]{H_J\lseq H_P}H
            \limp 
            (J\lseq \cPp[X])
          }{\wrule}
        }{\defr}{
          \cP[X]
        }{}
      }
    $$

    \item 
    The case $\cP=H\limp (\cPp\lseq  J)$ is similar to the previous one.

    \item 
    If $\cP=(\cPp\limp J)\limp H$, then we can apply splitting to get derivations
    $$\small
      \oddr[\dD_H]{H_P\limp H_J}H
    \quand
      \odpr[\dD_J]{J\limp H_J}
    \quand
      \odpr{H_P\limp \cPp[A]}
    $$
    and we can apply the inductive hypothesis on $H_P\limp \cPp[A]$, giving us derivations as in \eqref{eq:contextReduction:1}.
    We conclude since we have the following derivation for any formula $X$:
    $$\small
      \od{
        \odo{
          \odo{
            \odo{
              \odh{
                \oddr[\dD_P]{K\limp X}{
                  H_P 
                  \limp 
                  \left(\od{
                    \odi{
                      \odo{\odh{\cPp[X]}
                      }{\tudr}{
                        \cPp[X]\ltens \oddrP[\dD_J]\lunit{J\limp H_J}
                      }{}
                    }{\wlsr}{
                      (\cPp[X]\limp J)\limp H_J
                    }{\wrule}
                  }\right)
                }
              }
            }{\uncurry}{
              \odtP{
                H_P \ltens (\cPp[X]\limp J)
              }{\tcomr}{
                (\cPp[X]\limp J)\ltens H_P
              }{}
              \limp H_J
            }{}
          }{\curry}{
            (\cPp[X]\limp J)\limp \oddrP[\dD_H]{H_P\limp H_J}{H}
          }{}
        }{\defr}{
          \cP[X]
        }{}
      }
    $$

    \item 
    If $\cP=(J\limp \cN)\limp H$, then we can apply splitting to get derivations
    $$\small
      \oddr[\dD_H]{H_J\limp H_P}{H}
    \quand
      \odpr[\dD_J]{H_J\limp J}
    \quand
      \odpr{\cN[A]\limp H_P}
    $$
    and we can apply the inductive hypothesis on $\cN[A]\limp H_P$, giving us the following derivations:
    \begin{equation}\label{eq:contextReduction:2}
      \small
      \oddr[\dD_P]{K\limp X}{\cN[X]\limp H_P}
    \quand
      \odpr[\dD_A]{K\limp A}
    \qquad \mbox{for any formula $X$.}
    \end{equation}
    We conclude since we have the following derivation for any formula $X$:
    $$\small
    \oddr[\dD_P]{K\limp A}{
      \od{
        \odo{
          \odo{
            \odh{
              \left(\od{
                \odo{
                  \odi{
                    \odo{\odh{\cN[X]}}{\ludr}{
                    \oddrP[\dD_J]{\lunit}{H_J\limp J}
                    \limp
                    \cN[X]
                    }{}
                  }{\blsr}{
                    H_J\ltens (J\limp \cN[X])
                  }{\brule}
                }{\tcomr}{
                  (J\limp \cN[X])\ltens H_J
                }{}
              }\right)
              \limp 
              H_P
            }
          }{\curry}{
            (J\limp \cN[X])
            \limp 
            \oddrP[\dD_H]{H_J\limp H_P}H
          }{}
        }{\defr}{
          \cP[X]
        }{}
      }
    }
    $$


    \item 
    If $\cP=(\cN\lseq J)\limp H$, then we can apply splitting to get derivations
    $$\small
      \oddr[\dD_H]{H_P\lseq H_J}H
    \quand
      \odpr[\dD_J]{J\limp H_J}
    \quand
      \odpr{\cN[A]\limp H_P}
    $$
    and we can apply the inductive hypothesis on $\cN[A]\limp H_P$, giving us derivations as in \eqref{eq:contextReduction:2}.
    We conclude since we have the following derivation for any formula $X$:
    $$\small
      \od{
        \odo{
          \odi{\odi{\odh{X\limp K}}{\wcudr}{
              \oddrP[\dD_P]{X\limp K}{\cN[X]\limp H_P}
              \lseq 
              \oddrP[\dD_J]{\lunit}{J\limp H_J}
            }{\wrule}
          }{\wqdr}{
            (\cN[X]\lseq J)
            \limp 
            \oddrP[\dD_H]{H_P\lseq H_J}H
          }{\wrule}
        }{\defr}{
          \cP[X]
        }{}
      }
    $$

    \item 
      The case $\cP=(J\lseq \cN)\limp H$ is similar to the previous one.
      \qed
  \end{itemize}
\end{proof}
