\uprules*
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proof}
  We provide a procedure to remove the up rules from a derivation in $\SBiV$ proceeding top-down, showing that whenever there is a derivation of the conclusion of the up rule, then there is a derivation of its premise.
  \begin{itemize}
    \item 
    In the case of $\rrule_\uparrow^\bullet\in \set{\tuur,\luur,\bsudr,\bcudr}$,
    we only show the case $\tuur$, since the other are similar.
    We have a derivation of the form {\small$\odpr{\cN[\odn{\lunit \ltens A}{\rrule_\uparrow^\bullet}{A}{\brule}]}$} and we apply \Cref{lemma:contextReduction} to $\cN[\lunit \ltens A]$ to get derivations
    \begin{equation}
      \small
      \oddr[\dD_X]{X\limp K}{\cN[X]}
      \quand
      \odpr[\dD']{(\lunit\ltens A)\limp K}
    \end{equation}
    for any formula $X$.
    The Splitting Lemma~\ref{lemma:splitting} applied to $(\lunit\ltens A)\limp K$ gives us derivations: 
    $$\small
    \oddr[\dD_K]{\lunit \ltens K_A}{K}
    \quand
    \odpr[\dD_{K_A}]{A\limp K_A}
    \quand
    \oodh{\lunit}
    \mydot
    $$
    We conclude by constructing the following derivation:
    $$\small
    \oddr[\dD_A]{
      \odpr[\dD_{K_A}]{
        A 
        \limp 
        \odtP{K_A}{\tudr}{\oddr[\dD_{K}]{\lunit\ltens K_A}{K}}{}
      }
    }{\cN[A]}
    $$

    \ 

    \item 
    In the case of $\baiur$, we have a derivation of the form {\small$\odpr{\cN[\odn{a\limp a}{\baiur}{\lunit}{\brule}]}$}.
    We apply \Cref{lemma:contextReduction} to $\cN[a\limp a]$ to get a formula $K$ such that there are derivations
    \begin{equation}\label{eq:upElim:1}
      \small
      \oddr[\dD_X]{X\limp K}{\cN[X]}
      \quand
      \odpr[\dD_a]{(a\limp a)\limp K}
    \end{equation}
    for any formula $X$.
    The Splitting Lemma~\ref{lemma:splitting} applied to $(a\limp a)\limp K$ gives us derivations: 
    $$\small
    \oddr[\dD_K]{K_L\limp K_R}{K}
    \quand
    \odpr{K_L\limp a}
    \quand
    \odpr{a\limp K_R}
    \mydot
    $$
    To which we apply the Atomic Splitting Lemma~\ref{lemma:atomicSplitting}, and we can conclude by constructing the following derivation:
    $$\small
    \od{
      \odo{
        \odi{\odh{\lunit}}{\waidr}{
          \oddr[\dD_K]{
            \oddbP[\dD_L]{a}{K_L}
            \limp 
            \oddrP[\dD_R]{a}{K_R}
          }{K}
        }{\wrule}
      }{\ludr}{
        \oddr[\dD_\lunit]{\lunit\limp K}{\cN[\lunit]}
      }{}
    }
    $$
    where 
    $\dD_L$ and $\dD_R$ are obtained applying \Cref{lemma:atomicSplitting} to $K_L\limp a$ and $a\limp K_R$, and where $\dD_\lunit$ is the instantiation of the derivation $\dD_X$ form with $X=\lunit$.

    \item 
    In the case of $\wqur$ applied in a positive context, we have a derivation of the form 
    {\small $\odpr{\cP[\odn{(A\lseq C)\ltens(B\lseq D)}{\wqur}{(A\ltens B)\lseq (C\ltens D)}{\wrule}]}$}.
    We apply \Cref{lemma:contextReduction} to the conclusion to get a formula $K$ and the following derivations:
    \begin{equation}\label{eq:upElim:3}
      \oddr[\dD_X]{K\limp X}{\cP[X]}
      \quand
      \odpr[\dD_a]{((A\ltens B)\lseq (C\ltens D))\limp K}
      \mydot
    \end{equation}
    The fact that $\proves[\BiV](A\lseq C)\ltens(B\lseq D)\limp K$ allows us to apply the Splitting \Cref{lemma:splitting} to get the following derivations:
    $$
    \oddb[\dD_K]{K_L\ltens K_R}{K}
    \quand
    \odpr{K_L\limp (A\lseq C)}
    \quand
    \odpr{K_R\limp (B\lseq D)}
    \mydot
    $$
    We conclude because of the existence of the following derivation:
    $$\small
    \od{
      \odd{
        \odo{\odi{
          \odo{\odh{\lunit}}{\wsudr}{
            \oddrP[\dD_A]{\lunit}{K_A\limp A}\lseq \oddrP[\dD_C]{\lunit}{K_C\limp C}
          }{}
        }{\wqdr}{
          (K_A\lseq K_C) 
          \limp
            \odnP{
                \left(\od{\odi{\odo{\odh A}{\tudr}{\oddrP[\dD_B]{\lunit}{K_B \limp B} \ltens A}{}
                  }{\wlsr}{
                    K_B \limp (B\ltens A)
                  }{\wrule}
                }\right)
              \lseq 
                \left(\od{\odi{\odo{\odh C}{\tudr}{\oddrP[\dD_D]{\lunit}{K_D \limp D} \ltens C}{}
                  }{\wlsr}{
                    K_D \limp (D\ltens C)
                  }{\wrule}
                }\right)
            }{\wqdr}{
              (K_B\lseq K_D)\limp ((B\ltens A)\lseq(D\ltens C))
            }{\wrule}
        }{\wrule}}{\curryrule}{
          \oddbP[\dD_K]{
            \oddbP{K_A\lseq K_C}{K_L}
            \ltens 
            \oddbP{K_B\lseq K_D}{K_R}
          }{K}
          \limp 
          \left(
            \odtP{B\ltens A}{\defr}{A \ltens B}{}
            \lseq
            \odtP{D\ltens C}{\defr}{C \ltens D}{}
          \right)
        }{}
      }{\dDp_{(A\ltens B)\lseq(C\ltens D)}}{
        \cP[(A\ltens B)\lseq(C\ltens D)]
      }{}
    }
    $$
    where the existence of derivations 
    $\dD_A$, $\dD_C$, and $\dD_L$ \resp{$\dD_B$, $\dD_D$, and $\dD_R$}
    are guaranteed by \Cref{lemma:splitting} applied to 
    $K_L\limp (A\lseq C)$ \resp{$(B\lseq D)\limp K_R$}, 
    and where $\dD_P$ is the instantiation of the derivation $\dD_X$ with $P=(A\lseq C)\ltens(B\lseq D)$.

    \item 
    In the case of $\bqur$ applied in a negative context, we have a (positive) derivation of the form 
    {\small $\odpr{\cN[\odn{(A\lseq C)\limp(B\lseq D)}{\bqur}{(A \limp B) \lseq (C\limp D)}{\brule}]}$}.
    We apply \Cref{lemma:contextReduction} to the conclusion to get a formula $K$ and the following derivations:
    \begin{equation}\label{eq:upElim:2}
      \oddb[\dD_X]{X\limp K}{\cN[X]}
      \quand
      \odpr[\dD_a]{((A \limp B) \lseq (C\limp D))\limp K}
      \mydot
    \end{equation}
    The fact that $\proves[\BiV](A\lseq C)\limp(B\lseq D)\limp K$ allows us to apply the splitting lemma \Cref{lemma:splitting} to get the following derivations:
    $$
    \oddr[\dD_K]{K_L\limp K_R}{K}
    \quand
    \odpr{K_L\limp (A\lseq C)}
    \quand
    \odpr{(B\lseq D)\limp K_R}
    \mydot
    $$
    We conclude because of the existence of the following derivation:
    $$\small
    \od{
      \odd{
        \odo{\odi{
          \odi{\odh{\lunit}}{\wsudr}{
            \oddrP[\dD_B]{\lunit}{B\limp K_B}\lseq \oddrP[\dD_D]{\lunit}{D\limp K_D}
          }{\wrule}
        }{\wqdr}{
          \odnP{
            \left(\od{
              \odi{\odo{\odh B}{\ludr}{\oddrP[\dD_A]{\lunit}{K_A\limp A} \limp B}{}}{\wlsr}{(A\limp B) \ltens K_A}{\wrule}
            }\right)
            \lseq 
            \left(\od{
              \odi{\odo{\odh D}{\ludr}{\oddrP[\dD_C]{\lunit}{K_C\limp C} \limp D}{}}{\wlsr}{(C\limp D) \ltens K_C}{\wrule}
            }\right)
          }{\bqdr}{
            ((A\limp B)\lseq(C\limp D))\ltens(K_A\lseq K_C)
          }{\brule}
          \limp
          (K_B\lseq K_D)
        }{\wrule}}{\curry}{
          ((A\limp B)\lseq(C\limp D))
          \limp 
          \oddrP[\dD_K]{
            \oddrP[\dD_L]{K_A\lseq K_C}{K_L}
            \limp 
            \oddrP[\dD_R]{K_B\lseq K_D}{K_R}
          }{K}
        }{}
      }{\dDn_{(A\limp B)\lseq (C\limp D)}}{
        \cN[(A\limp B)\lseq (C\limp D)]
      }{}
    }
    $$
    where the existence of derivations 
    $\dD_A$, $\dD_C$, and $\dD_L$ \resp{$\dD_B$, $\dD_D$, and $\dD_R$}
    are guaranteed by \Cref{lemma:splitting} applied to 
    $K_L\limp (A\lseq C)$ \resp{$(B\lseq D)\limp K_R$}, 
    and where $\dD_P$ is the instantiation of the derivation $\dD_X$ with $P=(A\lseq C)\limp(B\lseq D)$.
\qed

  \end{itemize}
\end{proof}
