          \vlin{\AXrule}{}{(A\lprec B)\lprec C \vdash (A\lprec B)\lprec C}{\vlhy{}}
        }{
          \vlin{\AXrule}{}{A \lprec (B\lprec C) \vdash A \lprec (B\lprec C)}{\vlhy{}}
        }
    }
  $$
  A similar derivation can be defined for $\sassl$ using the rule $\acutr$.

  For the right-to-left direction, we show that if the formula interpretation of both premises of the rule $\acutr$ are derivable in $\IBV$, then also the formula interpretation of the conclusion is provable in $\IBV$ (using $\sassr$).
  $$
  \od{
    \odo{
      \odi{
        \odh{
          \left(
            \Gamma^{\ltens} 
            \limp 
            (A\lprec (B \lprec C))
          \right)
          \ltens
          \odtP{
            \left(
              \odnP{(A\lprec B) \lprec C}{\sassr}{
                A\lprec (B\lprec C)
              }{}  
              \ltens 
              \Delta^{\ltens}
            \right) 
            \limp  D
          }{\curry}{
            (A\lprec (B\lprec C))  \limp (\Delta^{\ltens} \limp  D)
          }{}
        }
      }{\wlsr}{
        \left(\od{
          \odo{
            \odi{
              \odh{
                (
                  \Gamma^{\ltens} 
                  \limp 
                  (A\lprec (B\lprec C))
                )
                \limp 
                (A\lprec (B\lprec C))
              }
            }{\blsr}{
              \Gamma^{\ltens} 
              \ltens
              \odnP{(A\lprec (B\lprec C))\limp (A\lprec (B\lprec C))}{\baiur}{\lunit}{\brule}
            }{\brule}
          }{\tuur}{
            \Gamma^{\ltens} 
          }{}
        }\right)
        \limp 
        (\Delta^{\ltens} \limp  D)
      }{\wrule}
    }{\uncurry}{
      (\Gamma^{\ltens} \ltens \Delta^{\ltens}) \limp  D
    }{}
  }
  $$
  where $\Gamma^{\ltens}$ \resp{$\Delta^{\ltens}$} are formulas obtained by conjunction ($\ltens$) of all formulas in $\Gamma$ \resp{$\Delta$}.
  A similar argument applies for $\acutl$.
  \qed
\end{proof}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Remarks on \Cref{sec:IBVtoBV}}
\label{app:IBVtoBV}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

With the results of \Cref{sec:assoc}, we can give another proof of \Cref{thm:BVm}, which makes use of the sequent calculus instead of the deep inference system. The first observation is that a similar result as \Cref{thm:BiVextensNiML} also holds for $\NML$ and $\BV$. For this, let us define the \defn{system $\hBV$}, to be $\BVm$ (as defined in \Cref{fig:BVm}) where $\feq$ is replaced by $\hfeq$, which is defined via:
\begin{equation}
    \begin{array}{c@{\qquad}c}
      A\ltens (B\ltens C) \hfeq (A\ltens B)\ltens C
      &
      A\ltens B \hfeq B\ltens A
      \\ \\[-1ex]
      A\lpar (B\lpar C) \hfeq (A\lpar B)\lpar C
      &
      A\lpar B \hfeq B\lpar A 
    \end{array}
\end{equation}
i.e., $\feq$ with associativity for $\lseq$ removed. We now have the following:


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}
  Let $A$ be a $\BVm$-formula. Then ~$\proves[\NMLm]A$~ iff ~$\proves[\hBV]A$~.
\end{theorem}
\begin{proof}
  The proof is similar to the proof of \Cref{thm:BiVextensNiML}, using one-sided sequents $\vdash \cneg A,B$ instead of $A\vdash B$ (see also~\cite{gug:str:01} and~\cite{acc:man:PN}).
  \qed
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}
  Let $A$ be a $\BVm$-formula. Then ~$\proves[\BVm]A$~ iff ~$\proves[\hBV\cup\set{\sassr,\sassl}]A$~.
\end{theorem}
\begin{proof}
  This is trivial, as the rules $\sassr$, $\sassl$ can alway be used instead of the equality       $A\lseq (B\lseq C) \feq (A\lseq B)\lseq C$, and vice versa.
\qed
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


Note that the two rules $\sassr$ and $\sassl$ are applicable to $\IBV$-formulas and $\BVm$-formulas. With some abuse of notation, we can also allow them to be applied in a sequent calculus, as rewrite rules inside an arbitrary formula context. We can thus define two new proof systems:
\begin{equation}
  \begin{array}{rcl}
    \NMLp&~=~&\NMLm\cup\set{\sassr,\sassl}\\[1ex]
    \INMLp&~=~&\INML\cup\set{\sassr,\sassl}
  \end{array}
\end{equation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{corollary}\label{cor:BVm}
    Let $A$ be a $\BVm$-formula. Then ~$\proves[\BVm]A$~ iff ~$\proves[\NMLp]A$~.
\end{corollary}
\begin{proof}
  Immediately from the previous two theorems.
  \qed
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{corollary}\label{cor:IBV}
    Let $A$ be a $\IBV$-formula. Then ~$\proves[\IBV]A$~ iff ~$\proves[\INMLp]A$~.
\end{corollary}
\begin{proof}
  Immediately from \Cref{thm:BiVextensNiML} and the argument above.
  \qed
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


We now have the following:

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}\label{thm:INMLstar}
  Let $A$ be a unit-free formula. Then ~$\proves[\INMLp]A$~ iff ~$\proves[\NMLp]\emb A$~.
\end{theorem}
\begin{proof}
  This proof is almost literally the same as the proof of \Cref{thm:NMLextensNiML}. We only need to observe that the two rules  $\sassr$ and $\sassl$ do not change the polarity of the formula they are applied to.
  \qed
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


We now immediately have our desired result:

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\thmBVm*
\begin{proof}
  For a unit-free formula $A$, we have ~$\proves[\IBV]A$~ iff ~$\proves[\IBVm]A$. Therefore, the theorem follows from \Cref{thm:INMLstar} and \Cref{cor:BVm} and \Cref{cor:IBV}.
\qed
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\end{document}
