\section{\boldmath $K_{3,t}$-Minor-Free Graphs}

This section proves upper bounds on the size of grid minors in  $K_{3,t}$-minor-free graphs with given radius. 
It is easily seen that $K_{2,t}$ is a minor of a $O(\sqrt{t})\times O(\sqrt{t})$ grid. So by 
\cref{ApexGridMinor}, every $K_{3,t}$-minor-free graph with radius $r$ has no $O(rt^{3/2}) \times O(rt^{3/2})$ grid minor. We can do better, as follows.



\begin{lem}
\label{K3tGridRadius}
Let $G$ be a graph with radius $r\geq 1$ and centre $\alpha$. If $G-\alpha$ has an $n\times m$ grid minor, then $K_{3,t}$ is a minor of $G$ for some
$$t\geq \frac{(n-4r+2)(m-4r+2)}{8r(2r-1)} .$$
\end{lem}

\begin{proof}
Let   $(X_{i,j}:1\leq i\leq n, 1\leq j \leq m)$ be a model of the $n\times m$ grid minor in $G-\alpha$. 
Let $G'$ be the graph obtained from $G$ by contracting $X_{i,j}$ to a vertex $(i,j)$ (for all $i,j$). 
So $G'-\alpha$ has an $n\times m$ grid subgraph $J$ with vertex-set 
$\{1,\dots,n\}\times\{1,\dots,m\}$. 

For $j\in\{1,\dots,m\}$, let $R_j:= \{ (i,j) \in V(J) : 1\leq i\leq n\}$ be the $j$-th row in $J$. 
For $i\in\{1,\dots,n\}$, let $C_i:= \{ (i,j) \in V(J) : 1\leq j\leq m\}$ be the $i$-th column in $J$. 

Since contractions do not increase distances, $G'$ has radius at most $r$ with centre $\alpha$. 
So for each vertex $x\in V(G')$ there is a path $P_x$ in $G'$ from $x$ to $\alpha$ with at most $r-1$ internal vertices. Let $I_x$ be the set of internal vertices of $P_x$, which may be empty if $x\alpha\in E(G')$.


Let $s:=2r-1$. We may assume that $m>2s$ and $n>2s$, otherwise the claim is trivial. Let $p:= \floor{(n-2r+1)/2r)}$, so $p\geq 1$ and $n \geq 2rp+(2r-1)$.

Let $A:=\{ (2ir,j) \in V(J): 1\leq i\leq p, s+1\leq j\leq m-s\}$. So $|A|=p(m-2s)$. 

For $i\in\{1,\dots,p+1\}$, 
let $a_i$ be a random element in $\{2(i-1)r+1,\dots,2ir-1\}$, where each element is chosen with probability $\frac{1}{2r-1}$. 
Let 
$X:=\bigcup\{C_{a_i}: \text{odd }i\in\{1,\dots,p+1\} \}$ and
$Y:=\bigcup\{C_{a_i}: \text{even }i\in\{1,\dots,p+1\} \}$.
So $X\cup Y$ is a set of pairwise disjoint columns in $J$, alternating between $X$ and $Y$, as illustrated in \cref{FindK3t}.

\begin{figure}[!t]
\centering
\includegraphics{FindK3t}
\caption{Proof of \cref{K3tGridRadius}: the subgraphs $X'$ and $Y'$ are shown in red and blue; the vertical paths in $X'\cup Y'$ are chosen randomly from within each shaded block; and the vertices $x\in A'''$ are green, enlarged into the paths $Z_x$.}
\label{FindK3t}
\end{figure}

Let $A':= \{ x \in A: I_x \cap (X\cup Y)=\emptyset\}$. 
We now estimate $|A'|$. 
Consider $x\in A$.
Let $I_x$ be 1 if $x\in A$ and 0 otherwise. 
For each $y\in P_x$, the column containing $y$ is added to $X\cup Y$ with probability at most $\frac{1}{2r-1}$, so $\mathbb{P}(y\in X\cup Y)\leq\frac{1}{2r-1}$.
Since $|P_x|\leq r-1$, by the union bound, 
$\mathbb{P}(P_x \cap (X\cup Y)\neq\emptyset ) \leq\frac{r-1}{2r-1}<\frac12$.
So $\mathbb{P}(x \in A') >\frac12$, and
$\mathbb{E}(I_x)>\frac12$.
By definition, $|A'|=\sum_{x\in A}I_x$. 
By linearity of expectation, 
$\mathbb{E}(|A'|)=\sum_{x\in A}\mathbb{E}(I_x)>\sum_{x\in A}\frac12 = \frac12|A|$.
So there exists $a_1,\dots,a_{p+1}$ such that $|A'|>\frac12|A|$. 

For each $x\in A'$ let $Z_x$ be the maximal horizontal path in $J-(X\cup Y)$ including $x$. By the definition of $X$ and $Y$, the endpoints of $Z_x$ are adjacent to $X$ and $Y$. 

Consider the digraph $Q$ with $V(Q):=A'$, where $(x,y)\in E(Q)$ if $I_x\cap Z_y\neq\emptyset$. By construction, 
$Z_x\cap Z_y=\emptyset$ for distinct $x,y\in A'$. Thus $\deg^+_Q(x)\leq |I_x|\leq r-1$. Hence $|E(Q)|\leq(r-1)|V(Q)|$. Let $\overline{Q}$ be the undirected graph underlying $Q$. So $\overline{Q}$ has average degree $2|E(\overline{Q})|/|V(\overline{Q})|\leq 2|E(Q)|/|V(Q)|\leq 2(r-1)$. By Tur\'an's Theorem, $\overline{Q}$ has an independent set $A''$ with $|A''|\geq \frac{1}{2r-1}|A'|\geq 
\frac{1}{4r-2}|A|$. For distinct $x,y\in A''$, we have  
$I_x\cap Z_y=\emptyset$ and $I_y\cap Z_x=\emptyset$.



For each $j\in\{1,\dots,s\}$, 
let $L_j$ be the set of vertices $x\in A''$ such that 
$I_x\cap (R_j\cup R_{n-j+1})\neq\emptyset$. 
Since $|I_x|\leq r-1$, we have 
$\sum_{j=1}^s|L_j|\leq (r-1)|A''|$. 
Thus, 
$|L_q|\leq \frac{r-1}{s} |A''|
\leq \frac{1}{2} |A''|$ for some $q\in\{1,\dots,s\}$. 
Let $A''' := A''\setminus L_q$. Thus 
\begin{align*}
    |A'''| 
\geq \frac12 |A''| 
\geq \frac{|A|}{8r-4}
= \frac{p(m-2s)}{8r-4} 
& = \floor*{\frac{n-2r+1}{2r}} 
\left(\frac{m-4r+2)}{8r-4} \right) \\
& \geq \frac{(n-4r+2)(m-4r+2)}{8r(2r-1)}.
\end{align*}

Let $X':= X \setminus (R_{n-s+1}\cup \dots \cup R_n)\cup R_q$ and $Y':= Y \setminus (R_1 \cup \dots \cup R_s) \cup R_{n-q+1}$. Observe that $J[X']$ and $J[Y']$ are connected and disjoint. 
Let $R:=\{\alpha\}\cup\bigcup\{ P_x: x\in V(A''') \}$. 
So $G'[R]$ is connected, and $X,Y,R,\bigcup\{Z_x:x\in A'''\}$ are pairwise disjoint. 
Each $x\in A'''$ has a neighbour in $R$, and $Z_x$ is adjacent to both $X$ and $Y$. 
Thus $G'[R],G'[X'],G'[Y']$ and $\{Z_x:x\in A'''\}$ form a $K_{3,|A'''|}$ model in $G'$. 
\end{proof}

\cref{K3tGridRadius} leads to a proof of the following result from \cref{Intro}.

\blah*

\begin{proof}
Suppose for contradiction that there is an $n\times n$ grid minor in $G$. 
Let $\alpha$ be a centre of $G$.
So $G-\alpha$ has an $(n-1)\times (n-1)$ grid minor. 
By \cref{K3tGridRadius}, $G$ has a $K_{3,s}$ minor with 
\begin{align*}
    s
  \geq 
 \frac{(n-4r+1)^2}{8r(2r-1)}
\geq\frac{ ( n-4r+1 )^2}{16r^2} 
\end{align*}
Thus
$ ( n-4r+1 )^2 \leq  16r^2s \leq  16r^2(t-1)$, 
implying
$ n \leq  4r\sqrt{t-1}+4r-1 < 4r( 1+\sqrt{t-1})$, a contradiction.
\end{proof}

