\title{Transferable Sequential Recommendation with Vanilla Cross-Entropy Loss}


\author{
    \IEEEauthorblockN{Hao Fan\IEEEauthorrefmark{1}\IEEEauthorrefmark{4}, Yanrong Hu\IEEEauthorrefmark{1}\IEEEauthorrefmark{3}, Kai Fang\IEEEauthorrefmark{1}\IEEEauthorrefmark{3}, Qingyang Liu\IEEEauthorrefmark{2}\IEEEauthorrefmark{4}, Hongjiu Liu\IEEEauthorrefmark{1}}
