\begin{lemma}
    \label{lem:tiling-link}
    If \Imc is a model of $\Tmc_{P}$, then the binary relations $h^{\Imc} \circ v^{\Imc}$ and $v^{\Imc} \circ h^{\Imc}$ coincide and are functional.
\end{lemma}
%
\begin{proof}
    If \Imc be a model of $\Tmc_{P}$, \eqref{eqn:tiling-successors} guarantees that for every $d \in \Delta^{\Imc}$ that there are four individuals $d_1,d_2,e_1,e_2 \in \Delta^{\Imc}$ such that $(d,d_1) \in h^{\Imc}$, $(d_1,d_2) \in v^{\Imc}$, $(d,e_1) \in v^{\Imc}$ and $(e_1,e_2) \in h^{\Imc}$.
    %
    By~\eqref{eqn:tiling-super} and~\eqref{eqn:tiling-local} we deduce that $d \in A_{ij}^{\Imc}$ iff $(d,d_2) \in r_{ij}^{\Imc}$ and $(d,e_2) \in r_{ij}^{\Imc}$ for $i,j \in \{0,1\}$.
    %
    Moreover, $d_2$ and $e_2$ are both different from $d_1$ and $e_1$, since the concepts $A_{ij}$ are disjoint for $i,j \in \{0,1\}$ and by~\eqref{eqn:tiling-local}.
    %
    Together with~\eqref{eqn:tiling-successors}, this implies that $d_2, e_2 \notin h^{\Imc}(d)$ and $d_2, e_2 \notin v^{\Imc}(d)$.
    %
    Then, we conclude by~\eqref{eqn:tiling} that $d_2 = e_2$ must hold and that $h^{\Imc} \circ v^{\Imc}$ and $v^{\Imc} \circ h^{\Imc}$ coincide.
    %
    \qed
\end{proof}

\begin{lemma}
    \label{lem:tiling-reduction}
    %
    The tiling problem $P$ has a solution iff $\Tmc_{P}$ is consistent.
\end{lemma}
%
\begin{proof}
    Let \Imc be a model of $\Tmc_{P}$. We define the mapping $\pi \colon \mathbb{N} \times \mathbb{N} \to \Delta^{\Imc}$ inductively, as follows.
    %
    First, let $\pi(0,0)$ be an arbitrary individual in \Imc, which exists since this set must be non-empty.
    %
    Assuming that for $i,j \in \mathbb{N}$ the value $\pi(i,j) := d$ is defined, we define $\pi(i+1,j)$ as the unique $h$-successor of $d$ in \Imc $\pi(i,j+1)$ as the unique $v$-successor of $d$ in \Imc.
    %
    \Cref{lem:tiling-link} guarantees that $\pi$ is well-defined: indeed, the individual $\pi(i+1,j+1)$ is supposed to be both the unique $h$-successor of $\pi(i,j+1)$ and the unique $v$-successor of $\pi(i,j+1)$, and the lemma ensures that these are indeed the same elements.
    %
    Clearly, for all $i, j \in \mathbb{N}$
    %
    \begin{equation}
      \label{eqn:tiling-correct}
      (\pi(i,j),\pi(i+1,j)) \in h^\Imc \; \text{and} \; (\pi(i,j),\pi(i,j+1)) \in v^\Imc.
    \end{equation}
    Using $\pi$, we define $\pi_P \colon \mathbb{N} \times \mathbb{N} \to T$ as $\pi_P(i,j) := t$ iff $\pi(i,j) \in A_t^\Imc$. Then, the fact that $\Imc$ satisfies~\eqref{eqn:tiling-successors} and~\eqref{eqn:tiling-correct} ensures that $\pi_P$ is a solution of $P$.

    Next, let $\pi$ be a solution of $P$.
    %
    We define the interpretation $\Imc_\pi$ with domain $\mathbb{N} \times \mathbb{N}$ as follows.
    %
    For each tile type $t \in T$, we set $A_t^{\Imc_\pi}$ as the set of elements $(m,n)$ for which $\pi(m,n) = t$.
    %
    For each element $(m,n)$ in the domain, we add $((m,n),(m+1,n))$ to $h^{\Imc_\pi}$ and $((m,n),(m,n+1))$ to $v^{\Imc_\pi}$.
    %
    Then, writing $(m \equiv i \mod 2)$ to denote that the remainder of the division of $m \in \Nbb$ by $2$ is $i$ (and similarly for $n$ and $j$), we set for $i,j \in \{0,1\}$
    %
    \begin{align*}
        A_{ij}^{\Imc_\pi} &:= \{ (m,n) \in \Delta^{\Imc_\pi} \mid m \equiv i \mod 2,\ n \equiv j \mod 2 \} \\
        h_{i}^{\Imc_\pi} &:= \{ ((m,n),(m+1,n)) \mid (m,n) \in A_{ij}^{\Imc_\pi} \} \\
        v_{j}^{\Imc_\pi} &:= \{ ((m,n),(m,n+1)) \mid (m,n) \in A_{ij}^{\Imc_\pi} \} \\
        r_{ij}^{\Imc_\pi} &:= h_{i}^{\Imc_\pi} \cup v_{j}^{\Imc_\pi} \cup \{ ((m,n),(m + 1,n + 1)) \mid (m,n) \in A_{ij}^{\Imc_\pi}\}
    \end{align*}
    %
    It is straightforward to verify that $\Imc_\pi$ is a model of $\Tmc_{P}$.
    %
    \qed
  \end{proof}

\paragraph{Considerations.} While the above reduction is not syntactically using transitive roles within number restrictions, the semantics of \SSCC is such that every $\suc$-restriction implicitly ranges over the transitive roles, as well.
%
If we disallow role complement as used in~\eqref{eqn:tiling}, we could still enforce correctness of the reduction by adding
%
$A_{ij} \sqsubseteq \suc(|A_{(1-i)(1-j)}| = 1)$
%
to $\Tmc_P$, which works because of the implicit ranging over role successors induced by the semantics of \SSCC.

One may ask if lifting this semantic condition allows us to regain decidability.
%
If we consider the extension $\SSCC^{++}$ of \SSCC, defined in the same spirit of \ALCSCCpp w.r.t. \ALCSCC, we can replace~\eqref{eqn:tiling} with $A_{ij} \sqsubseteq \sat(|r_{ij} \cap A_{(1-i)(1-j)}| = 1)$ to cause undecidability.
%
While only using coefficients $0$ or $1$, this variant requires an explicit usage of transitive roles in number restrictions.
%
It is unclear if the same can effect can be achieved while disallowing transitive roles within numerical constraints.

