\begin{theorem}\label{formulaCanonical}\hskip 0pt\\
Consider the parabola $\mathcal{N}$ and the circle $\mathcal{M}$, as above.
\begin{enumerate}
\item  $\mathcal{M}$ and $\mathcal{N}$  are separated iff $\Delta >0$, and $c_1 >0$ or $c_2 >0$.%\textcolor{red}{idem}
\item  $\mathcal{M}$ and $\mathcal{N}$  are externally tangent iff $\Delta =0$, and $c_1 >0$ or $c_2 >0$.%\textcolor{red}{idem}

\item  $\mathcal{M}$ is inside $\mathcal{N}$ iff either $\Delta >0$, $c_1 <0$, $c_2<0,$ and
the number of sign changes in $-c_0$, $c_1'$, $-c_2'$, $c_3'$ is 1; or $c_3'=0$, $c_2'=0$, $a^2>\delta$.%\textcolor{red}{MEJORA}

\item  $\mathcal{M}$ and $\mathcal{N}$ have only two intersection points iff $\Delta <0$.%\textcolor{red}{idem}

\item  $\mathcal{M}$ and $\mathcal{N}$ have four points of intersection iff $\Delta >0, c_2'< 0, c_1'<0 . $%\textcolor{red}{MEJORA}

\item  $\mathcal{M}$ and $\mathcal{N}$ have two points of intersection and an inner tangent point iff $a^2 \leq \delta$,
$\Delta=0$, $\Delta'\neq 0$, $c_2' <0, c_1' <0$.%\textcolor{red}{MEJORA}

\item  $\mathcal{M}$ and $\mathcal{N}$ have only an inner tangent point iff
\begin{itemize}
\item either $\Delta=0$, $c_1 <0,c_2 <0$, $c_3'<0$, and $c_2' >0$ or $c_1'>0$; %either $a^2\neq \delta$,
\item or $\Delta=0$, $c_1 <0,c_2 <0$, $c_3' =0$, $c_1' >0$, $c_2' <0$.  %\textcolor{red}{(that implies $a^2 > \delta$)}
\item or $c_1'=c_2'=c_3'=0.$

\end{itemize}
%\textcolor{red}{ FALAI INCOMPLETO}

\item  $\mathcal{M}$ and $\mathcal{N}$ have two inner tangent points iff $a^2<\delta$,
$c_3' =0$, and $c_2'=0$.%\textcolor{red}{MEJORA}

 \item  $\mathcal{M}$ and $\mathcal{N}$ have only an intersection point and an inner tangent point iff $\Delta=0$, $\Delta'=0$, $c_1'<0$ and $c_3'<0$. %esto implica conditions $a^2<\delta, y $c_2'<0$ $  
%\textcolor{red}{new}
\end{enumerate}
\end{theorem}

Comparing Theorem \ref{formulaCanonical} and results of Section III in \cite{Min-Chen:2008}, one can see that the number of conditions have been reduced in Points 3., 5., 6. and 8., and Point 7. has been completed.
