 t_1= t_3, &t_2 = \dfrac{1}{t_3^3},& t_3\neq 0,\quad t_3^2  \neq 1.
 \end{eqnarray*}
 Hence, 
 \begin{itemize}
 \item For the solution  $t_1 = t_2=t_3, t_3 \neq 0$, the intersection point of multiplicity three is 
$ \left( \frac{a(t_3^2 - 1)}{2t_3}, \frac{b(t_3^2 + 1)}{2t_3} \right) $ and the one of multiplicity one is $\left( \frac{-a(t_3^6 - 1)}{2t_3^3}, \frac{b(t_3^6 + 1)}{2t_3^3} \right) $.

  \item For the solution $t_1 =t_2, t_3 = \dfrac{1}{t_2^3}, t_2 \neq 0$, the intersection point of multiplicity three is 
   $ \left( \frac{a(t_2^2 - 1)}{2t_2}, \frac{b(t_2^2 + 1)}{2t_2} \right) $ and the one of multiplicity one is $\left( \frac{-a(t_2^6 - 1)}{2t_2^3}, \frac{b(t_2^6 + 1)}{2t_2^3} \right) $.

%a 
  \item For the solution $ t_1 = \dfrac{1}{t_3^3},t_2=t_3, t_3 \neq 0$, the intersection point of multiplicity three is 
   $ \left( \frac{a(t_3^2 - 1)}{2t_3}, \frac{b(t_3^2 + 1)}{2t_3} \right) $ and the one of multiplicity one is $\left( \frac{-a(t_3^6 - 1)}{2t_3^3}, \frac{b(t_3^6 + 1)}{2t_3^3} \right) $.

  \item For the solution $t_1 =t_3, t_2 = \dfrac{1}{t_3^3}, t_3 \neq 0$, the intersection point of multiplicity three is 
   $ \left( \frac{a(t_3^2 - 1)}{2t_3}, \frac{b(t_3^2 + 1)}{2t_3} \right) $ and the one of multiplicity one is $\left( \frac{-a(t_3^6 - 1)}{2t_3^3}, \frac{b(t_3^6 + 1)}{2t_3^3} \right) $.
