%
\medskip
In a similar way,
let $q(\lambda)=f(\lambda+b^2)=a_3''\lambda^3+a_2''\lambda^2+a_1''\lambda+a_0''$, with
\begin{eqnarray*}
a_3''&=&-\frac{1}{a^{2} b^{2}}  \, ,\\
a_2''&=&a_2+3a_3b^2 \\
&=&-\frac{\mathit{x_c}^{2}+\mathit{y_c}^{2}+a^{2}+2 b^{2}-\delta^{2}}{a^{2} b^{2}}  \, ,\\
a_1''&= &3a_3b^4 + 2a_2b^2 + a_1\\
&=&-\frac{a^{2} b^{2}-a^{2} \delta^{2}+b^{4}-b^{2} \delta^{2}+b^{2} \mathit{x_c}^{2}+a^{2} \mathit{y_c}^{2}+2 b^{2} \mathit{y_c}^{2}}{a^{2} b^{2}}\\
&=&-\frac{(b^2 - \delta^2)(a^2 + b^2)+b^{2} \mathit{x_c}^{2}+a^{2} \mathit{y_c}^{2}+2 b^{2} \mathit{y_c}^{2}}{a^{2} b^{2}}  \, , \\
a_0''&=&-\frac{\mathit{y_c}^{2} \left(a^{2}+b^{2}\right)}{a^2} \, .
\end{eqnarray*}
