\end{pmatrix},$$

$$b_{5}=a_{33}, \, (b_3,b_4)=(a_{31},a_{32})P .$$

Since this transformation is defined by a isometry, it follows that $b_0b_2>0$ and $(b_0+b_2)\det {\bf B}=(b_0+b_2)\det {\bf M}<0$, and, consequently, both $b_0, b_1$ must be positive. Next, consider another affine transformation defined by the diagonal matrix $\rm diag(\sqrt{b_0},\sqrt{b_2},1)$ and after completing the square, we obtain
\begin{align*}
 {\cal X}{\bf M}{\cal X}^{t}&={\cal X}_1{\bf B}{\cal X}_1^{t}\\
 &={\cal X}_2\rm diag(1/\sqrt{b_0},1/\sqrt{b_2},1) {\bf B}\rm diag(1/\sqrt{b_0},1/\sqrt{b_2},1) {\cal X}_2^{t}\\
 &=(X_2-X_c)^2+(Y_2-Y_c)^2+\frac{L_3}{T_1},
\end{align*}
with
$${\cal X}_2^{t}=\rm diag(\sqrt{b_0},\sqrt{b_2},1){\cal X}_1^t, \quad X_c=-\frac{b_3}{\sqrt{b_0}},\quad Y_c=-\frac{b_4}{\sqrt{b_2}}.
$$
In consequence,
$$
\mathcal{M}_1 : (X_2-X_c)^2 +(Y_2-Y_c)^2 = \frac{-L_3}{T_1}
$$
Then, the affine transformation which transforms $\mathcal{M}$ into $\mathcal{M}_1$, denoted by $\mathcal{S}_1$, will be defined by the matrix
$$
\bf A= \rm diag(\sqrt{b_0},\sqrt{b_2},1) \left(\begin{array}{cc}P^t&  \\ & 1\end{array}\right)
$$
%%
\medskip
In parallel, we also had a parabola $\mathcal{N}$ defined by
\begin{equation}\label{conic}
b_{11}X^{2}+b_{22}Y^{2}
+2b_{12}XY+2b_{13}X+2b_{23}Y
+b_{33}=0,
\end{equation}
which is transformed by $\mathcal{S}_1$ into
$$
\mathcal{N}_1  :d_{11} X_2^2 + d_{22}Y_2^2+2 d_{12}X_2Y_2+2d_{13}X_2+2d_{23}Y_2 +d_{33} =0.
$$
The next step is to obtain the canonical form of $\mathcal{N}_1$. Under another orthogonal transformation $\mathcal{S}_2$ and after completing the square, we obtain
$$
\mathcal{M}_1 : (X_3-X'_c)^2 +(Y_3-Y'_c)^2 = \frac{-L_3}{T_1},
$$
$$
\mathcal{N}_2  :E_1 X_3^2 -2E_2Y_3 =0,
$$
where
$$E_1=d_{11}+ d_{22}=\frac{T}{T_1};
$$
$$
E_2=\dfrac{d_{12} d_{13}-d_{11} d_{23}   }{\sqrt{d_{11}^2 + d_{12}^2}}.
$$
Since $d_{12}^2=d_{11}d_{22}$,  after performing the necessary calculations, we have
$$
E_2=\dfrac{\sqrt{ d_{11}d_{23}^2 - 2d_{12}d_{13}d_{23} + d_{22}d_{13}^2}}{\sqrt{d_{11} + d_{22}}}
=\dfrac{\sqrt{\dfrac{-L_0}{T_1}} }{\sqrt{\dfrac{T}{T_1}}}=\dfrac{\sqrt{ -L_0 } }{\sqrt{  T }}.
$$
Thus,
$$
\dfrac{E_1}{E_2}=\dfrac{T\sqrt{T}}{T_1\sqrt{-L_0}}
$$
Following the notation of the paper, $a^2$ and $\delta^2$ should be equal to:
$$
a^2=\dfrac{E_2}{E_1}=\dfrac{T_1\sqrt{-L_0}}{T\sqrt{T}},\delta^2=\frac{-L_3}{T_1}.
$$
{\color{red}Aclaraci\'on: si se coge una par\'abola con $\det N <0$ y se calcula la forma can\'onica, te sale $traza(N)x^2-2E_2Y=0$, con $E_2^2=-\det N/traza(N)$, por lo que la traza es positiva. Entonces al ser par\'abola real, tenemos que $E_2$ debe ser positivo con lo cual, $E_2=\sqrt{- \det N /traza N}$. Esto es lo que se aplica a ${\cal N}_1$ Adem\'as, al ser la traza positiva y $T_1$ positivo, vemos que $T$ debe ser positivo. }

