\section{Tracking marked up steps on both paths}
\label{sec:jointUpSteps}

We will now apply the same decomposition as in the previous sections, but consider paths with a marked up step, rather than a marked abscissa. As mentioned in the introduction, the reason to do that is that in this setting we are able to study the joint law of the heights of the two paths. Our goal is to prove Theorem~\ref{thm:mixed}.

Recall that we let $\tilde P(j)$ be the height (of the initial point of) the $j$-th up step of the path $P$.

We write $\mathrm{contact'}_{\leq j}(P), \mathrm{contact'}_{\geq j}(P)$ for the number of contacts of $P$ weakly before, or after, the $j$-th up step of $P$, respectively.

\subsection{The enriched equation}


We introduce the generating function
$$
J(x,y)\equiv J(t,x,y,r,s) := \sum_{n\geq 0} t^n \sum_{(P,Q)\in \mathcal{I}_n}  \sum_{j=1}^{n}
%s^{Q(i)} 
r^{\tilde{P}(j)}s^{\tilde{Q}(j)} 
x^{\mathrm{contact'}_{\leq j}(P)}y^{\mathrm{contact'}_{\geq j}(P)}.
$$
%In order to prove our wanted asymptotic theorem, we will only need to work under the specialisation $s=w, r=w^{-2}$, but for the sake of clarity in writing the next equation, we prefer to work with the two variables $r$ and $s$. 
%We write $H_1(x):=H(x,s)_{|s=1}$, this series has been computed in the previous section.
We have
\begin{proposition}\label{prop:catalyticTamariMixed}
	The generating function $J(x,y)\equiv J(t,x,y,r,s)$ of Tamari intervals where the $j$-th up step of each path is marked for some integer $j$, where $r$ marks the lower height and $s$ the upper height is solution of the equation:
\begin{align}
	J(x,y) &=
	x\frac{F(y)-y}{y} 
	+  rstx\frac{J(1,y)-J(1,1)}{y-1} F(y) 
	+  stx^2\frac{J(x,y)-J(1,y)}{(x-1)y}F(y)
	+xtJ(x,y)\frac{F(x)-F(1)}{x-1}.
\label{eq:catalyticTamariMixed}
\end{align}
\end{proposition}
\begin{figure}
	\centering
	\includegraphics[width=\linewidth]{decomp13.pdf}
	\caption{The decomposition of Figure~\ref{fig:decomp1}, where the $j$-th up step for some $j\in[n]$ is marked on both paths. There are four cases to consider,  corresponding to the four terms in Equation~\eqref{eq:catalyticTamariMixed}.}\label{fig:decomp13}
\end{figure}

\begin{proof}
	The proof is very similar to the proof of Proposition~\ref{prop:catalyticTamariLower}, except that we keep track of the height on both paths. It is actually less involved since there are less cases to consider.
	Given an interval $(P,Q)$ of size $n+1$ with a marked $j\in [n]$, we apply again the decomposition of Section~\ref{sec:decomp}.
We let $U, V$ be the $j$-th up step of $P$ and $Q$, respectively.
	As before we let $v_1$, $v_2$, be the first non-initial contacts of the paths $P$ and $Q$.
	We distinguish four cases, see Figure~\ref{fig:decomp13},
\begin{itemize}
	\item Case 1: $U=V$ is the first step of the path ($j=1$).
		In this case we are only counting intervals by contacts as in the series $F(y)$. However we have to exclude the empty interval (hence a correcting term $-y$), and we should count all contacts with weight $y$ except for the first one, hence a correcting factor $x/y$. This gives the first term in~\eqref{eq:catalyticTamariMixed}.
	\item Case 2: $U$ is not the initial step of $P$, but $U$ appears before $v_1$. In this case $V$ belongs to $Q_1$. In this case, after applying the decomposition, $U,V$ give rise naturally to marked contacts $\tilde{U},\tilde{V}$ of $P_1,Q_1$ appearing before the vertex $\tilde v$. The height of both steps is shifted by $1$, hence the factor $rs$. The remaining factors are understood in a similar way as in case 2 of the proof of Proposition~\ref{eq:catalyticTamariLower}. Namely, an interval $(\tilde{P_1}, \tilde{Q_1})$ with marked up steps $\tilde{U}, \tilde{V}$, with respectively $k$ and $\ell$ contacts  before and after $\tilde{U}$ (thus having a contribution of $x^ky^\ell$ in $J(x,y)$) gives rise to $\ell$ intervals contributing to this case, with a contribution of 
		$$
		x^1 y^{\ell-1} + x^1 y^{\ell-2} + \dots + x^1 y^0 = x \frac{y^\ell-1}{y-1}.
		$$
In total, the contribution for the first interval is thus $x \frac{J(1,y)-J(1,1)}{y-1}$. The contribution of the second interval $(P_2,Q_2)$ is just $F(y)$, since all corresponding contacts appear after the marked abscissa. In total, we obtain the second term in~\eqref{eq:catalyticTamariMixed}.

	\item Case 3: $U$ appears (weakly) after $v_1$ but before $v_2$. In this case again $V$ belongs to $Q_1$. In this case, after applying the decomposition, $U,V$ give rise naturally to marked contacts of of $P_1,Q_1$ appearing (weakly) after the vertex $\tilde v$. Only the height of the steps of the upper path is shifted by $1$, hence the factor $s$. The rest of factors are understood in a similar way as in case 4 of the proof of Proposition~\ref{prop:catalyticTamariLower}, but is simpler.
		%since we need not consider the case where the marked up step is the last step of the path.
		Namely,   an interval $(\tilde{P_1}, \tilde{Q_1})$ with marked up steps $\tilde{U},\tilde{V}$, with respectively $k$ and $\ell$ contacts  before and after $\tilde{U}$ (thus having a contribution of $x^ky^\ell$ in $G(x,y)$) gives rise to $k$ intervals contributing to this case, with a contribution of 
		$$
		x^{k+1} y^{\ell} + x^{k-1} y^{\ell-1} + \dots + x^2 y^{\ell-1} = \frac{x^2}{y}\frac{x^k-1}{x-1} y^\ell.
		$$
In total, the contribution for the first interval is thus 
		$$t\frac{x^2}{y} \frac{J(x,y)-J(1,y)}{x-1}.$$
		(Note that the situation is simpler than in Proposition~\ref{prop:catalyticTamariLower} since we do  not have to deal with the subtle case where the vertex whose height is considered is the last on the path -- since we mark only \emph{up} steps).
			Moreover, the contribution of the second interval $(P_2,Q_2)$ is just $F(y)$, and in total we obtain the third term in~\eqref{eq:catalyticTamariMixed}.

	\item Case 4: $U$ appears (weakly) after $v_2$. In this case $V$ belongs to $Q_2$. This case is similar to the last case of the proof of Proposition~\ref{eq:catalyticTamariLower} and directly gives the fourth term in~\eqref{eq:catalyticTamariMixed}
\end{itemize}
\end{proof}

\subsection{The specialized equation}
In view of proving Theorem~\ref{thm:mixed}, we will consider the 
following specialisation of the function $J(x,y)$:
$$
M(x,y)\equiv M(t,x,y,w) := J(x,y)\Big|_{s=w,r=w^{-3}}
=
\sum_{n\geq 0} t^n \sum_{(P,Q)\in \mathcal{I}_n}  \sum_{j=1}^{n}
%s^{Q(i)} 
w^{\tilde{Q}(j)-3\tilde{P}(j)} 
x^{\mathrm{contact'}_{\leq j}(P)}y^{\mathrm{contact'}_{\geq j}(P)}.
$$
From Proposition~\ref{prop:catalyticTamariMixed} it satisfies the equation
\begin{align}
	M(x,y) &=
	x\frac{F(y)-y}{y} 
	+  w^{-2} tx\frac{M(1,y)-M(1,1)}{y-1} F(y) 
	+  wtx^2F(y)\frac{M(x,y)-M(1,y)}{(x-1)y}
	+xt\frac{F(x)-F(1)}{x-1}M(x,y).
\label{eq:catalyticTamariMixedM}
\end{align}
We will now solve this equation.

\subsection{Solving the equation}

Our method to solve~\eqref{eq:catalyticTamariMixedM} is similar to the one used in Section~\ref{sec:solutionLow}, except that the equation to be solved in the second step will now be quadratic instead of linear.


\subsubsection{\noindent \bf First step: eliminating variable $x$ (or $u$).}

We start by writing Equation~\eqref{eq:catalyticTamariMixedM} in kernel form
\begin{align}\label{eq:kernelForm2M}
	\mathbf{K}_2(x,y) M(x,y)=&
	x\frac{F(y)-y}{y} 
	+  w^{-2} tx\frac{M(1,y)-M(1,1)}{y-1} F(y) 
	+  wtx^2F(y)\frac{-M(1,y)}{(x-1)y}
\end{align}
with
\begin{align}\label{eq:kernel2M}
	\mathbf{K}_2(x,y) = -1 + 
	+  wtx^2F(y)\frac{1}{(x-1)y}
	+xt\frac{F(x)-F(1)}{x-1}.
\end{align}


We will again work under the change of variables~\eqref{eq:zuv}.
We write respectively $\tilde{M}(u,v), \tilde{M}_1(v), \tilde{M}_{11}, \tilde{\mathbf{K}}_2$ for the quantities $M(x,y),M(1,y),M(1,1),\mathbf{K}_2$ expressed in the variables $z,u,v$ after the substitutions~\eqref{eq:zuv}.


By~\eqref{eq:solutionTamariSimple}, the kernel $\tilde{\mathbf{K}}_2$ is an explicit rational function of $z,u,v$.  Its numerator is a polynomial $\tilde{\mathbf{k}}_2(u,v)\equiv\tilde{\mathbf{k}}_2(z,u,v,w)$ which, computations made~\cite{maple}, is given by 
\begin{align*}
	\tilde{\mathbf{k}}_2(u,v)=
u^2v^2wz^4+2uv^2wz^4+3u^2vwz^3+v^2wz^4-u^2vwz^2-u^2z^4+6uvwz^3+2u^2wz^2+3u^2z^3
	\\-2uvwz^2+3vwz^3-u^2wz-3u^2z^2+4uwz^2-uz^3-vwz^2+u^2z-2uwz+3uz^2+2wz^2-3uz-wz+u.
\end{align*}
The equation $\tilde{\mathbf{k}}_2=0$ has a unique root $\mathbf{U}_0\equiv \mathbf{U}_0(z,v)$ which is a power series in $z$. It satisfies $\mathbf{U}_0=wz+O(z^2)$.

Making the substitutions~\eqref{eq:zuv} and using the known expressions of $F(x)$, $F(y)$, Equation~\eqref{eq:kernelForm2M} takes the form
$$
\tilde{\mathbf{K}}_2 (u,v) \tilde{M}(u,v) = \tilde{\mathbf{L}}_2(z,u,v,\tilde{M}_1(v),\tilde M_{11})
$$
for some rational function $\tilde{\mathbf{L}}_2$ that can be written explicitly (its numerator has 99 terms, \cite{maple}).
Substituting $u=\mathbf{U}_0$ in this equation, we cancel the left-hand side,
hence we also cancel the right-hand side.
We are thus left with the following polynomial equation satisfied by 
$z,v,w, \tilde{M}_1(v)$ and $\tilde{M}_{11}$,
\begin{align}
	\tilde{\mathbf{L}}_2(z,\mathbf{U}_0(z,v),v,\tilde{M}_1(v),\tilde M_{11})=0.
\end{align}
We can eliminate $\mathbf{U}_0$ between this equation and $\tilde{\mathbf{k}}_2 (\mathbf{U}_0(z,v),v)$, and we thus obtain~\cite{maple} a polynomial equation of the form 
\begin{align}\label{eq:BM}
	B(z,v,w, \tilde{M}_1(v),\tilde{M}_{11})=0.
\end{align}
This polynomial has 854 terms, and it has degree two in $\tilde{M}_1(v)$.
At this stage, we have eliminated the unknown $\tilde{M}(u,v)$ and the  variable $u$.

\subsubsection{\noindent \bf Second step: eliminating variable $y$ (or $v$).}


Let us write polynomial equation~\eqref{eq:BM} in the form.
$$
\mathbf{a}(\tilde{M}_{11},v,z,w)\tilde{M}_1(v)^2+
\mathbf{b}(\tilde{M}_{11},v,z,w)\tilde{M}_1(v)+
\mathbf{c}(\tilde{M}_{11},v,z,w)=0.
$$
We will solve this equation using (a variant of) the quadratic method (see \cite{BMJ} and references therein).
%We first claim that there exists a series $V_0(z)$ such that substituting $v=V_0(z)$ 
Introduce notation:
\begin{align}\label{eq:quadraticMethodBM}
	B(v):=	 \mathbf{a}(v) \tilde{M}_1(v)^2 
	+\mathbf{b}(v) \tilde{M}_1(v) 
	+\mathbf{c}(v) \ \ , \ \ 
	B_2(v):= 2 \mathbf{a}(v) \tilde{M}_1(v) 
	+\mathbf{b}(v),
\end{align}
where in the notation we only indicate dependencies in the variable $v$, for example $\mathbf{a}(v)=\mathbf{a}(\tilde{M}_{11},v,z,w)$.
We first claim that there exists a formal power series $V_0(z) = zw^{-1} + O(z^2)$ such that $B_2(V_0(z))=0$. To see this, we generate the first few terms of the series $\tilde{M}_1(v)$
to see~\cite{maple} that
$$
B_2(v) = a_{2,0} v^2 + a_{1,1} vz  + a_{1,2} v z^2  + a_{2,1} v^2 z + a_{3,0} v^3
+O_4(z,v)
$$
where the $a_{i,j}$ are explicit  polynomials in $w$  and where $O_4(z,v)$ is a formal power series in $z,v$ (and coefficients polynomial in $w$) with all terms of homogeneous degree at least 4.
Therefore the equation $B_2(V_0)=0$ can be written 
$$
V_0 = -(a_{2,0})^{-1} ( a_{1,1} z  + a_{1,2} z^2  + a_{2,1} V_0 z + a_{3,0} V_0^2 +V_0^{-1} O_4(z,V_0)).
$$
This is enough to see that the equation $B_2(V_0)=0$ has a formal power series root $V_0(z)$ of the form
$V_0(z) = \frac{-a_{1,1}}{a_{2,0}} z +O(z^2)$. Indeed all coefficients of $V_0$ can be computed inductively from this germ. This proves the claim (note that this is essentially a Newton-Puiseux argument).  Making constants explicit, we have $V_0(z) = zw^{-2} +O(z^2)$. There is also another power series root $V_0$ with constant coefficient $-1$ but we will not use it.




We can now apply (a variant of) the quadratic method. We have two equations involving the series $V_0$: the one that defines it, and the one obtained by substituting $v=V_0$ in~\eqref{eq:BM}. Namely:
$$
B(z,V_0,w, \tilde{M}_1(V_0),\tilde{M}_{11})=0 \ \ ,\ \  B_2(z,V_0,w, \tilde{M}_1(V_0),\tilde{M}_{11})=0.
$$
We can eliminate the series $\tilde{M}_1(V_0)$ between these two equations (which amounts to saying that the discrinant $\mathbf{b}^2-4\mathbf{ac}$ vanishes), and we obtain an equation of the form
$$
P(z,V_0,w,\tilde{M}_{11})=0.
$$
Computations made~\cite{maple}, this equation has three nontrivial irreducible factors, $P_1,P_2,P_3$, where only $P_3$ depends (in fact, linearly) on $\tilde M_{11}$. It is a direct check than none of the $v$-roots of $P_1$ and $P_2$ is equal to $V_0$ (in fact none is a formal power series in $z$), from which we conclude that $P_3(z,V_0,w,\tilde{M}_{11})=0$. This equation can be written as a rational expression of $\tilde M_{11}$ in the variable $V_0$, namely~\cite{maple} we have $\tilde{M}_{11}=\mathbf{R}(z,V_0)$ with
\begin{align}\label{eq:paramM11}
	R(z,V)= \frac{(Vz^2-z^2+3z-1)Vw^2}{Vz^4-3Vz^3+3Vz^2+z^3-Vz-3z^2+3z-1}.
\end{align}

One can check that substituting $v=V_0$ and this expression of $\tilde{M}_{11}$ cancels both $\mathbf{b}$ and $\mathbf{c}$. Therefore it also cancels $\mathbf{a}$, which gives us an explicit equation satisfied by $V_0$, namely~\cite{maple} we have $S(V_0,z)=0$ with:
\begin{align}\label{eq:V0}
	\footnotesize 
		&S(V,z,w)=V^5w^5z^5+V^5w^4z^5+V^5w^3z^5+5V^4w^5z^4
	+V^5w^2z^5-2V^4w^5z^3+5V^4w^4z^4-V^3w^4z^5+V^5wz^5\nonumber\\&-2V^4w^4z^3+5V^4w^3z^4+2V^4w^2z^5+8V^3w^5z^3+3V^3w^4z^4-V^3w^3z^5-2V^4w^3z^3+4V^4w^2z^4+2V^4wz^5\nonumber\\&-6V^3w^5z^2+5V^3w^4z^3+3V^3w^3z^4+V^3w^2z^5-2V^2w^4z^4-V^4w^2z^3+4V^4wz^4+V^3w^5z-5V^3w^4z^2\nonumber\\&+5V^3w^3z^3+8V^3w^2z^4+V^3wz^5+4V^2w^5z^2+7V^2w^4z^3-2V^2w^3z^4-V^4wz^3+V^3w^4z-5V^3w^3z^2+\nonumber\\&V^3w^2z^3+8V^3wz^4-4V^2w^5z-5V^2w^4z^2+7V^2w^3z^3+4V^2w^2z^4+V^3w^3z-V^3w^2z^2+V^3wz^3+V^2w^5\nonumber\\&+V^2w^4z-5V^2w^3z^2+6V^2w^2z^3+4V^2wz^4-V^3wz^2-2V^3z^3+V^2w^3z-5V^2w^2z^2+5V^2wz^3+4Vw^2z^3\nonumber\\&+V^3z^2+3V^2w^2z-2V^2wz^2-4V^2z^3-4Vw^2z^2+3Vwz^3-V^2w^2+3Vw^2z-Vwz^2-2Vz^3+V^2z-Vw^2\nonumber\\&-3Vz^2+2Vz-2z^2+z.
\end{align}

We have thus proved:
\begin{theorem}\label{thm:exactMixed}
	The generating function $M(1,1)\equiv M(1,1;t,w)$ is an algebraic function given by
	$$
	M(1,1) = R(z,V_0)
	$$
	where the change of variables $(t,w)\leftrightarrow (z,V)$ is given by~\eqref{eq:z} and by the equation $S(V_0,z,w)=0$.
\end{theorem}
By eliminating $V_0$ in \eqref{eq:paramM11}-\eqref{eq:V0} one obtains an explicit polynomial cancelling $M(1,1)$. Written in the variables $z$ and $w$, it has $601$ terms and degree five in $M(1,1)$. See~\cite{maple}.
Given the previous calculations it is not difficult to see that the full series $M(x,y)$ is algebraic but we will never use it.

We leave to our readers the task of proving algebraicity of the full function $J(1,1)$ (with both variables $r$ and $s$) rather than of its specialization $M(1,1)$ (involving only $w$) as we do here. We suspect that this is possible with similar methods, but by lack of application in mind we have not tried to do so -- therefore we  do not know if the calculations are manageable nor if unexpected dificulties arise.






\section{Asymptotics of moments}
\label{sec:asymptotics}


In this section we prove Theorems~\ref{thm:tamari} and~\ref{thm:tamariLow}. In both cases this will be a direct application of the method of Section~\ref{sec:trick}, in particular Theorem~\ref{thm:trick}, up to computer algebra calculations done in~\cite{maple}.
We will also prove Theorem~\ref{thm:mixed} which is a direct check.

\subsection{Proof of Theorem~\ref{thm:tamari}}

We start with Equation~\eqref{eq:catalyticTamariUpper} in Theorem~\ref{thm:exactUp}. This equation shows that $f(t)=H(t,1,s)\equiv H(1)$ is algebraic, therefore $H(x,r+1)$ is algebraic. Therefore (see e.g.~\cite{Comtet} again), there exists a recurrence formula of the form~\eqref{eq:Dfinite2} to compute its derivatives
$$
f^{(k)}\equiv f^{(k)}(t) :=\left.\left(\left(\frac{d}{ds}\right)^k H(1)\right)\right|_{s=1}.
$$
Given the form of our parametrization, we will prefer to work under the variable $z$ given by~\eqref{eq:z}, and in fact it is even more convenient to introduce the variable $\delta=(1-4z)^{1/2}$.
It is easily cheched~\cite{maple} that the main singularity of $H(1)$ is at $t=\rho:=\frac{27}{256}$, which corresponds to $z=\frac{1}{4}$, i.e. $\delta=0$. In what follows we will still write $f^{(k)}$ for the function $f^{(k)}(t)$ expressed in the variable $\delta$.

Using the package gfun, we immediately find~\cite{maple} that the $f^{(k)}$ satisfy an equation of the form~\eqref{eq:Dfinite2} with $L=6$,
namely 
\begin{align*}
	f^{(k)}(t)= \sum_{d=1}^{L} h_d(t,k)  f^{(k-d)}(t) 
\ \ , \ \  
k \geq L,
\end{align*}
where the $h_d(t,k)$ for $d=1..6$ are Laurent polynomials in $\delta$ with coefficients which are rational functions of $k$.
The degree of $h_1,\dots,h_6$ in $\delta^{-1}$ are respectively $0,6,6,10,10,10$.
Since $\delta$ behaves as $(1-t/\rho)^{1/4}$, this implies that hypothesis (i) of Theorem~\ref{thm:trick} holds with $\beta=\frac{3}{4}$.
One can explicitly check the values of the corresponding constants $a_d(k)$, which are nothing but top coefficients of $h_d$ in $\delta^{-1}$ up to a scaling factor. They are given~\cite{maple} by
\begin{align}\label{eq:explicitAi}
	a_1(k),\dots,a_6(k) = 0, \frac{\sqrt{6}}{96}(3k-4)(3k-8), 0, 0, 0, 0.
\end{align}

Now it only remains to check the initial conditions (ii). From the explicit Equation~\eqref{eq:catalyticTamariUpper}, the dominant singulariy of $f^{(0)}$, and indeed of each given $f^{(i)}$, can be computed automatically. 
We find that $f^{(0)}=\frac{64}{(\delta+3)^3}$, with singular expansion $f^{(0)}\singeq c_0 (1-t/\rho)^\alpha$ with $\alpha=\frac{1}{2}$ and $c_0=-\frac{32\sqrt{6}}{27}$. 

Given $\alpha, \beta$ we compute $\ell_0=L-0=6$, and to check the initial conditions we need to estimate the main singularity of $f^{(1)}, \dots, f^{(6)}$. This is done automatically and one gets $f^{(\ell)}\singeq c_\ell (1-t/\rho)^{\alpha-\beta\ell}$ for $\ell \geq 6$, with 
$$
c_0,\dots,c_6=
-{\frac {32}{27}}\,\sqrt {6},
{\frac {16}{27}}\,{3}^{3/4}\sqrt [4]{2},
{\frac {8}{27}},
{\frac {5}{54}}\,\sqrt [4]{3}{2}^{3/4},
{\frac {8}{81}}\,\sqrt {2}\sqrt {3},
{\frac {385}{2592}}\,{3}^{3/4}\sqrt [4]{2},
{\frac {70}{81}}.
$$


We have now verified al hypotheses of Theorem~\ref{thm:trick}. The main recurrence formula becomes 
$$
c_k=\frac{\sqrt{6}(3k-4)(3k-8)}{96}c_{k-2} \ \ , \ \  k> 6,
$$
with initial conditions above. 
It is a direct check that the solution of this recurrence is given by 
$$
c_k=
{\frac {16}{27}}\,{\frac {\Gamma  \left( \frac{k}{2}+\frac{1}{3} \right) \Gamma 
 \left( \frac{k}{2}-\frac{1}{3} \right) \sqrt {2}{4}^{-k}{6}^{3/4\,k}}{\pi }}
.
$$
for all $k\geq 0$.
Applying Theorem~\ref{thm:trick}, we immediately get:
\begin{align}\label{eq:momentstwoexpr}
		\mathbf{E}\left[ \left(\frac{Q_n(I)}{n^{3/4}}\right)^k \right]\longrightarrow 
	{\frac {\Gamma  \left( \frac{k}{2}+\frac{1}{3} \right) \Gamma  \left( \frac{k}{2}-\frac{1}{3} \right) {4}^{-k}{6}^{3/4\,k}}{\sqrt {3\pi }\Gamma  \left( \frac{3k}{4}-\frac{1}{2}\right) }}
=\frac{\sqrt{3} \cdot2^{-\frac{k}{4}-1}}{\sqrt{\pi}} \frac{\Gamma(\frac{1}{4}k+\frac{1}{3})\Gamma(\frac{1}{4}k+\frac{2}{3})}{\Gamma(\frac{1}{4}k+\frac{1}{2})},
	\end{align}
where the equality follows from  the duplication formula for the Gamma function (see also~\cite{maple}).
This proves Theorem~\ref{thm:tamari}.

\subsection{Proof of Theorem~\ref{thm:tamariLow}}

The proof is similar, we will be more succinct (all calculations are in~\cite{maple}).
We now write $f(t)=G(1,1)$. We start with Equation~\eqref{eq:exactDown} in Theorem~\ref{thm:exactDown}. 
We use this equation to compute a recurrence formula for the functions
$$
f^{(k)}\equiv f^{(k)}(t) :=\left.\left(\left(\frac{d}{dw}\right)^k G(1,1)\right)\right|_{w=1}.
$$
