\begin{figure*}
    \centering
    \subfloat[Rewards of different baselines]{
    \includegraphics[width=0.33\linewidth]{figure/reward-final.png}\label{fig:reward1}}
    \subfloat[Handover frequency of different baselines]{
    \includegraphics[width=0.33\linewidth]{figure/switch.png}\label{fig:switch}} 
