\subsection{Multi-user FAMA and its Variants} % Hanjiang
\subsubsection{Transmission Model}
As shown in Fig.~\ref{Fig_FAMA}, the received signal of at the $n$-th port of user $u$ is modelled as
\begin{equation}
r_n^{(u)} = h_n^{(u,u)} s^{(u)} + \sum_{\substack{\tilde{u}=1\\\tilde{u}\neq u}}^{U} h_n^{(\tilde{u},u)} s^{(\tilde{u})} + \eta_n^{(u)},
\end{equation} 
where $h_n^{(\tilde{u},u)}$ is the channel from the $\tilde{u}$-th BS antenna to UE $u$ at the $n$-th port, $\eta_n^{(u)}$ is the AWGN with variance of $\sigma_\eta^2$, and $s^{(u)}$ is the transmitted symbol for UE $u$ with $\mathbb{E} [|s^{(u)}|^2] = \sigma_s^2$.

The key point of FAMA is to select the antenna port(s) with the highest SINR at each UE for multiple access, i.e., 
\begin{equation}\label{Eq:PortSelect}
n^* = \arg \max_{n} \gamma_n,~ n = 0, \dots, N^* -1 \text{,}
\end{equation}
where $\gamma_n$ is the SINR metric of the $n$-th port, whose definition varies between \emph{s}-FAMA and \emph{f}-FAMA. 

In \emph{s}-FAMA \cite{H6_wong2023sFAMA}, $\gamma_n$ is the average SINR calculated as
\begin{equation}
\gamma_n^{{\rm{s}-FAMA}} = \frac{\sigma_s^2 \lvert h_n^{(u,u)}\rvert ^2}{\sigma_s^2 \sum_{\substack{\tilde{u}=1\\\tilde{u}\neq u}}^{U} \lvert h_n^{(\tilde{u},u)}\rvert ^2 + \sigma_\eta^2}.
\end{equation}
The outage probability of \emph{s}-FAMA is thus defined as
\begin{equation}\label{Eq:pout_sFAMA}
  p_{\rm s-FAMA} \!\triangleq\! {\rm Prob} \!\left(\! \max_{n} \frac{\sigma_s^2 \lvert h_n^{(u,u)}\rvert ^2}{\sigma_s^2 \sum_{\substack{\tilde{u}=1\\\tilde{u}\neq u}}^{U} \lvert h_n^{(\tilde{u},u)}\rvert ^2 + \sigma_\eta^2} < \gamma \!\right)\!,
\end{equation}
where $\gamma$ now denotes the SINR threshold.

For \emph{f}-FAMA \cite{H4_wong2022FAMA,H5_wong2023fast}, on the other hand, $\gamma_n$ is the instantaneous SINR calculated as
\begin{equation}
  \gamma_n^{{\rm {f}-FAMA}} = \frac{\lvert h_n^{(u,u)} s^{(u)}\rvert ^2}{\lvert \tilde{h}_n^{(u)} \rvert ^2}.
\end{equation}
where $\tilde{h}_n^{(u)}\triangleq \sum_{\substack{\tilde{u}=1\\\tilde{u}\neq u}}^{U} h_n^{(\tilde{u},u)} s^{(\tilde{u})} + \eta_n^{(u)}$ represents the instantaneous data-dependent interference and noise. The outage probability of \emph{s}-FAMA can be defined as
\begin{equation}\label{Eq:pout_fFAMA}
  p_{\rm f-FAMA} \!\triangleq\! {\rm Prob} \left(\! \max_{n} \frac{\lvert h_n^{(u,u)} s^{(u)}\rvert ^2}{\lvert \tilde{h}_n^{(u)} \rvert ^2} < \gamma \!\right)\!.
\end{equation}

The multiplexing gain that measures the capacity scaling is an important performance indicator in FAMA. Assume a fixed rate is transmitted to every user, the multiplexing gain in FAMA can be defined as
\begin{equation}
  m_{\rm FAMA} = (1-p_{\rm FAMA})U,
\end{equation}
where $p_{\rm FAMA}$ is given by \eqref{Eq:pout_sFAMA} or \eqref{Eq:pout_fFAMA}.

In the simplified channel model \eqref{model1}, if $|\mu_2| = \dots = |\mu_N| = \mu$, the outage probability of \emph{s}-FAMA is upper bounded by \cite[Theorem 3]{H6_wong2023sFAMA}
\begin{equation}
  p_{\rm s-FAMA} \!<\! \left[ 1-N\left(\frac{\mu^2}{\gamma+1}\right)^{U-1} - N\left(\frac{1-\mu^2}{\gamma}\right)^{U-1} \right]^{+},
\end{equation}
where the operation $(a)^{+} = \max\{0,a\}$ is to ensure that the bound is never negative. Hence, the multiplexing gain of the \emph{s}-FAMA network, $m$, is bounded by \cite[Theorem 4]{H6_wong2023sFAMA}
\begin{equation}
  U \geq m \geq \min \left\{ NU\left(\frac{1-\frac{1}{\pi W}}{\gamma}\right)^{U-1},U \right\}.
\end{equation}
In \emph{f}-FAMA, the outage probability is upper bounded by \cite[Theorem 3]{H4_wong2022FAMA}
\begin{align}
  p_{\rm f-FAMA} \!\lesssim & \frac{1-\mu^2}{4\mu^2}\exp{\frac{1-\mu^2}{4\mu^2}} \nonumber\\ & \times \!\! \sum_{n = 0}^{N-1} \frac{\binom{N-1}{n}(-1)^{n}}{\left(\frac{\sigma_I^2\sigma_s^2\gamma}{\sigma^2}\right)^{n}} e^{\frac{n}{4}}E_k\left(\frac{n}{4}+\frac{1-\mu^2}{4\mu^2}\right),
\end{align}
where $E_k(\cdot)$ represents the generalized exponential integral, $\sigma_I^2 = \sum_{\substack{\tilde{u}=1\\\tilde{u}\neq u}}^{U} \mathbb{E} [|h^{(\tilde{u},u)}_n|^2]\sigma_s^2$ is the variance of interference. Accordingly, the multiplexing gain of the \emph{f}-FAMA network is bounded by \cite[Corollary 2]{H4_wong2022FAMA}
%\begin{equation}
\begin{align}
  U \geq m & \gtrsim \min \left\{ \frac{(N-1)(1-\mu^2)U}{\left( \frac{\sigma_I^2 \sigma_s^2 \gamma}{\sigma^2} \right)}, U\right\} \nonumber\\ & \approx \min \left\{ \frac{(N-1)(1-\mu^2)}{\gamma}, U\right\}.
\end{align}
%\end{equation}

However, the channel model \eqref{model1} is not quite accurate and may lead to artificially optimistic performance predictions as analyzed in Section \ref{subsec:chan}. Nevertheless, the derivation in the more accurate channel model \eqref{h_jkn} is much more complicated. The outage probability of the two-user FAMA case in the more accurate channel model \eqref{h_jkn} was derived in \cite{H8_Xu2024revisiting}, and \cite{H7_Espinosa2024Anew} derived the outage probability of \emph{s}-FAMA. 

