\section{Propagation of chaos of the particle system}

\label{sec:chaos}

In this section we quantitatively study the relation between the swarm-based optimization with jumps, and the related non-linear mono-particle process obtained formally in Section \ref{sec:2} under the propagation of chaos assumption. Specifically, we aim to demonstrate that, as the number of particles $N \to \infty$ the law of the $N$-particle system converges to that of the corresponding mean-field dynamics and each particle process becomes asymptotically independent. We will consider a modified version of the dynamics where particles explore a bounded search domain and are subject to non-degenerate diffusion.

This convergence property is commonly referred to as propagation of chaos. With the results of propagation of chaos, we can justify using mean-field equation as a particle system in further analysis. Our proof is based on a coupling method, which is one of several established techniques used to derive such results. For a comprehensive overview of the various methods and developments in the theory of propagation of chaos, we refer the reader to \cite{chaintronPropagationChaosReview2022}.

\subsection{Notations and preliminaries}
\label{sec:notation}

For $x=(x_1, \dots, x_d)^\top \in \RR^d$, we denote with $|x|$ the standard Euclidean norm, while $\lVert x \rVert_1 := \sum_{\ell=1}^d|x_\ell|$, $\lVert x \rVert _\infty:=\max_{\ell=1,\dots,d} |x_\ell|$. With $B_r(x)$ and $B_r^\infty(x)$ we denote the closed balls centred in $x$ with radius $r>0$ for the Euclidean and $\ell^\infty$ norm, respectively.

If a random variable $X$ follows a Bernoulli distribution with parameter $p\in[0,1]$, we write $X \sim \text{Bern}(p)$. If $X$ follows a Gaussian distribution with mean $m \in \RR^d$ and covariance matrix $\Sigma \in \RR^{d\times d}$, we write $X \sim \mathcal{N}(m, \Sigma)$.
Let $\mathcal{P}(\mathcal{X})$ be the set of probability measures on a Polish space $\mathcal{X}$, and $\mathcal{P}_p(\mathcal{X})$ the set of probability measures with finite moments of order $p$, that is, $M_p(\mu) := \left(\int |x|^p \mu(dx) \right) ^{\frac{1}{p}} < \infty$. For a measure $\mu \in\mathcal{P}(\mathcal{X})$ and a Borel map $T:\mathcal{X}\to \mathcal{Y}$, we denote by $T_{\#}\mu \in \mathcal{P}(\mathcal{Y})$ the push-forward of $\mu$ through $T$, defined by 
 \begin{equation*}
     T_{\#}\mu(B) \defeq \mu(T^{-1}(B)) \quad \forall B \in \mathcal{B}(\mathcal{Y}),
 \end{equation*}
 where $\mathcal{B}(\cdot)$ denotes Borel sets on the space. 
%polish space: complete, separable metric spaces%

For two probability measures $\mu, \nu \in \mathcal{P}_p(\RR^d)$,  $\WW_p(\mu, \nu)$ is the $p$-Wasserstein distance defined by 
\begin{equation*}
    \WW_p(\mu, \nu) \defeq \min_{\gamma \in \Gamma} \left(  \int |x-y|^p \gamma(dx, dy )\right)^{\frac{1}{p}},
\end{equation*}
with 
 $\Gamma = \{ \gamma \in \mathcal{P}(\RR^d \times \RR^d) \,| \,\pi_{0\#}\gamma =\mu, \pi_{1\#}\gamma = \nu\}$ and $\mu, \nu \in \mathcal{P}_p(\RR^d)$. Here, $\pi_0(x, y) = x$ and $\pi_1(x, y) = y$ are the canonical projections onto the first and second coordinates. 
 For more detailed definitions and properties, we refer the reader to \cite{santambrogioOptimalTransportApplied2015,villaniOptimalTransport2009}.


\subsection{Assumptions and main results}

As mentioned in the introduction, we consider a modified version of the particle update \eqref{eq:psojump} accounting for projection in a closed convex search domain $\DD\subseteq \RR^d$, and non-degenerate Gaussian diffusion. The projection map $\Pi_{\DD}:\RR^d \to \DD$ is given by
\[
\Pi_{\DD}(y):= \underset{x\in\DD}{\textup{argmin}}\, | x - y|\,,
\]
and it is well defined thanks to the convexity of $\DD$. As before, consider $N$ particles $(X^i_k, V^i_k), i = 1,\dots,N$, where $k = 0,1,2,\dots$ denotes the algorithmic step, and the corresponding empirical measures $f_k^N = (1/N) = \sum_i \delta_{(X^i_k,V^i_K)}$ and $\rho^N_{k} = (1/N)\sum_i \delta_{X_k^i}$. For a given step size $\Delta t>0$ and a probability measure $p^\xi\in \mathcal{P}(\RR^d)$ for the noise, at every algorithmic step define i.i.d. random variables
\[
T^i_k \sim \textup{Bern}(e^{-\nu\Delta t }), \quad \xi^i_n \sim \mathcal{N}(0,I_d)\qquad i = 1,\dots,N
\]
and for $\lambda, \sigma> 0, \sigma_0 \geq 0$ we define $W_k^i$ component-wise for $\ell = 1,\dots,d$ as
\begin{equation} \label{eq:Wi}
(W_k^i)_\ell = \lambda(X^\alpha[\rho_k^N] - X_k^i)_\ell + \sigma\left(\sigma_0 + |(X^\alpha[\rho_k^N] - X_k^i)_\ell|\right) \xi_{k,\ell}^i
\qquad i = 1,\dots,N
\,. 
\end{equation}
The particle update is then given by
\be
\begin{cases}
    X_{k+1}^i &= \Pi_{\DD} \left(X_k^i + \Delta t V_{k+1}^i\right) \\
    V_{k+1}^i &= T_k^i V_k ^i + (1-T_k^i) W_k^i 
\end{cases} \qquad i = 1,\dots,N\,.
\label{eq:particle-sys-alg}
\ee
We note that for $\DD = \RR^d$ and $\sigma_0  = 0$, the update is equivalent to \eqref{eq:psojump}. For $\sigma_0>0$, the contribution of the noise $\xi_k^i$ never vanishes in the dynamics. As similar CBO dynamics with non-degenerate diffusion was studied in \cite{huangFaithfulGlobalConvergence2025}.

Following the formal arguments of Section \ref{sec:2}, one obtains that the corresponding nonlinear particle system of is given by
\be
\begin{cases}
    \overline{X}_{k+1} &= \Pi_{\DD} \left(\overline{X}_k + \Delta t \overline{V}_{k+1} \right) \\
    \overline{V}_{k+1} &= \overline{T}_k \overline{V}_k + (1-\overline{T}_k)\overline{W}_k
\end{cases}
\label{eq:nonlinear-update}
\ee
where, similarly as before, $ \overline{T}_k \sim \text{Bern} \ (e^{-\nu\Delta t})$, $\overline{\xi}_k \sim \mathcal{N}(0,I_d)$, and, as before, for $\ell = 1,\dots,D$ we have
\begin{equation} \label{eq:Wbar}
    (\overline{W}_k)_\ell = \lambda(X^\alpha[\rho_k] - X_k)_\ell + \sigma\left(\sigma_0 + |(X^\alpha[\rho_k] - \overline{X}_k)_\ell|\right) \overline{\xi}_{k,\ell}\,.
\end{equation}

The system is of McKean type, as the consensus point $X^\alpha[\rho_k]$ depends on $\rho_k = \textup{Law}(\overline{X}_k)$.
% Assumptions on objective function
Throughout the analysis, we assume the following conditions for the objective function $\mathcal{F}$. 
\begin{assumption}\label{assume:propagation}The objective function $\mathcal{F}: \RR^d \to \RR$ satisfies the following:
\begin{itemize}
    \item [A1] $\mathcal{F}$ is bounded below with $\underline{\mathcal{F}}\defeq \inf \mathcal{F} > -\infty$. 
    \item [A2] (growth conditions) there exists $L_{\mathcal{F}}, c_u, c_l, R_l>0$ such that \\  
    \be
    \begin{cases}
            |\mathcal{F}(x)-\mathcal{F}(y)| \leq L_\mathcal{F}(1+|x|+|y|)|x-y| &\forall x,y \in \RR^d,  \\
            \mathcal{F}(x)-\mathcal{F}(x^\ast) \leq c_u(1+|x|^2) &\forall x \in \RR^d, \\
            \mathcal{F}(x)-\mathcal{F}(x^\ast) \geq c_l|x|^2  &\forall x \text{ s.t. } |x| > R_l
        \end{cases}
    \ee
\end{itemize}
\end{assumption}

\begin{theorem} \label{thm:propagation-of-chaos}
Let $\mathcal{D}\subset \RR^d$ be a compact and convex search space, and let $\{ (X^i_k, V^i_k)\}_{i=1}^N$ be a particle system defined by \eqref{eq:particle-sys-alg} with i.i.d. initial data $(X^i_0, V^i_0)\sim f_0$ for some $f_0\in \mathcal{P}_1(\DD\times \RR^d)$.

Consider $N$ independent copies $\{(\overline{X}^i_k,\overline{V}^i_k)\}_{i=1}^N$ be $N$ of  the mono-particle process \eqref{eq:nonlinear-update} 
with $\overline{T}^i_k = T_k^i \sim \textup{Bern}(e^{-\nu \dt})$, $\overline{\xi}_k^i = \xi_k^i\sim \mathcal{N}(0,I_d)$ for all $i =1,\dots,N$, and same initial data.  Let the parameters be such that $\Delta t \in (0,1]$, $\lambda, \sigma>0$, $\sigma\geq 0$ and let $T > 0$ be a fixed time horizon.

If the objective function $\EE$ satisfies Assumption \ref{assume:propagation}, then there exists a constant $C= C(\alpha,\DD,\lambda, \sigma, \mathcal{F},d)$ independent of $N$, $T$ such that
\begin{equation}\label{eq:propagation-of-chaos}
  \sup_{k\Delta t \in [0,T]}\BE \left[ \frac{1}{N} \sum_{i=1}^N |X^i_k-\overline{X}^i_k| + |V^i_k-\overline{V}^i_k| \right] \leq Ce^{CT}\frac{1}{\sqrt{N}}. 
\end{equation}
\end{theorem}

Since the auxiliary nonlinear particles $\{(\overline{X}^i_k,\overline{V}^i_k)\}_{i=1}^N$ are independent and identically distributed, the above result can be extended to estimate the distance between the empirical measure $f_k^N$ and the kinetic model $f_k$.


\begin{corollary} \label{cor:propagation-of-chaos} 
Under the same settings of Theorem \ref{thm:propagation-of-chaos},  further assume that $f_0 \in \mathcal{P}_q(\mathcal{D}\times\RR^d )$ with $q>2d/(2d-1)$.
Then, there exists a positive constant $C=C(\mathcal{D},d,q,f_0,\alpha,\lambda, \sigma,\sigma_0 ,\mathcal{F})$ independent on $T$ and $N$ such that 
\begin{equation*}
 \sup_{k\Delta t\in [0,T]}\BE [\WW_1(f^N_k, f_k)] \leq C\left( e^{CT}\frac1{\sqrt{N}} +   \e(N)\right)
\end{equation*}
where 
\be \label{eq:eps1}
\e(N):=
 \begin{cases}
N^{-1/2}\log(1+N)  & \textup{if} \;\;d = 1 \\
N^{-1/(2d)} & \textup{if} \;\;d>1.
\end{cases}
\ee
\end{corollary}




\subsection{Proof of Theorem~\ref{thm:propagation-of-chaos}}

The proof is based on a coupling between the two particle systems, where the track the distance between the $i$-th particles $(X_k^i, V_k^i)$ and $(\overline{X}^i_k, \overline{V}_k^i)$ at each time step $k$. To do so, we first collect some stability results for the consensus point $X^\alpha[\cdot]$. 

\begin{lemma} \label{lem:measure-measure}
    Let $\mathcal{F}$ satisfy Assumption \ref{assume:propagation} and $\mu, \hat{\mu} \in \mathcal{P} (\RR^d)$ with $$ \int |x|^4 \mu(dx), \quad \int |x|^4 \hat{\mu}(dx) \leq K.$$ Then we have the following estimates
    $$|X^\alpha[\mu]-X^\alpha[\hat{\mu}]| \leq C_0 \WW_1(\mu, \hat{\mu}), $$
    where $C_0$ is a positive constant depending only on $\alpha, L_\EE, K$.
\end{lemma}
\begin{proof}
We note that the estimate is equivalent to the one derived in  \cite[Lemma 3.2]{carrilloAnalyticalFrameworkConsensusbased2018} with $\WW_1$ instead of $\WW_2$. The proof can be carried out with the exact same argument, but without applying Jensen's inequality in the last step.
\end{proof}

\begin{lemma}[\cite{fornasierConsensusbasedOptimizationHypersurfaces2021}, Lemma 3.1] \label{lem:measure-law}
    Let $\EE$ satisfy Assumption \ref{assume:propagation} and $\DD\subseteq \RR^d $ be closed compact domain. Let $\{ \overline{X}^i_k\}_{i=1}^N$ for $k=0, 1, \dots $ be i.i.d. with common distribution $\rho_k \in \mathcal{P}(\DD)$ and denote with $\overline{\rho}^N_k$ be the corresponding empirical measure. 

   Then, there exists a constant $C_1$ depending only on $\textup{diam}(\mathcal{D)}$ and $C_{\alpha, \EE} \defeq \exp(\alpha (\sup_{x\in \DD}\EE(x) - \inf_{x\in \DD}\EE(x)))$
    such that 
    $$ \sup_{k \in \mathbb{N}} \BE \left[ |X^\alpha [\overline{\rho}^N_k]-X^\alpha [\rho_k]|\right] \leq C_1 N^{-1 / 2}.$$
\end{lemma}
\begin{proof} The proof can be carried out exactly as in \cite[Lemma 3.1]{fornasierConsensusbasedOptimizationHypersurfaces2021} where it is shown that $\sup_{k \in \mathbb{N}} \BE \left[ |X^\alpha [\overline{\rho}^N_k]-X^\alpha [\rho_k]|^2\right] \leq \tilde{C}_1 N^{-1}$. Also in this case, our claim simply follows from Jensen's inequality $\mathbb{E}[|X|]\leq \sqrt{\mathbb{E}[|X|^2]}$ for any random variable $X$.
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proof}[Proof of Theorem \ref{thm:propagation-of-chaos}]

First, we note that the projection map is non-expansive 
\[
|\Pi_\DD(x) = \Pi(y)| \leq |x- y| \quad\textup{for any}\quad x,y \in \RR^d\,,
\]
as a consequence of the convexity of the domain $\DD$. Therefore, at any algorithmic step $k$, and for each $i=1, \dots ,N$ we have
\be\label{eq:position}
\begin{split}
\mathbb{E}\left[|X^i_{k+1}-\overline{X}^i_{k+1}|\right ] &= \mathbb{E}\left[\left|\Pi_\mathcal{D} \left( X^i_k + \Delta t V^i_{k+1} \right)-\Pi_\mathcal{D} \big( \overline{X}^i_k + \Delta t \overline{V}^i_{k+1} \big)\right|\right] \\
&\leq \mathbb{E}\left[|X^i_k-\overline{X}^i_k|+\Delta t |V^i_{k+1}-\overline{V}^i_{k+1}|\right].
\end{split}
\ee

For the velocities, thanks to the choice $\overline{T}_k^i = T^i_k$ and $T^i_k\sim \textup{Bern}(e^{-\nu \Delta t})$, we observe that
\be
\begin{split}
    \BE \left[ |V^i_{k+1}-\overline{V}^i_{k+1}| \right] &= \BE \left[ |T^i_k\overline{V}^i_k + (1-T^i_k) \overline{W}^i_k-T^i_k\overline{V}^i_k - (1-T^i_k) \overline{W}^i_k| \right] \\
    &\leq \BE \left[ T^i_k |V^i_k-\overline{V}^i_k| \right]+\BE \left[ (1-T^i_k)|W^i_k-\overline{W}^i_k|\right] \\
    &= e^{-\nu\Delta t}\BE \left [|V^i_k-\overline{V}^i_k| \right]+(1-e^{-\nu\Delta t})\BE \left[ |W^i_k-\overline{W}^i_k| \right].
\end{split}
\ee
where in the last step we used that $\mathbb{E}[T^i_k] = e^{-\nu \Delta t}$. By using the explicit definitions of $W_k^i, \overline{W}_k^i$, we can estimate their difference as 
\begin{equation*}
\begin{split}
    \BE \left[ |W^i_k-\overline{W}^i_k| \right] &= \BE \left[ |\lambda (X^\alpha [\rho^N_k]-X^\alpha [\rho_k] -X^i_k- \overline{X}^i_k)| \right]\\
    &\qquad + \BE \left[ \sqrt{\sum_{\ell=1}^s \sigma^2 ( \xi^i_{k})_\ell^2 \left(\sigma_0 +(|(X^\alpha [\rho^N_k] - X_k^i)_\ell|-\sigma_0 -|(X^\alpha [\rho_k] - \overline{X}^i_k)_\ell|\right)^2 }\right]\\
    &\leq  \lambda\BE \left[ |(X^\alpha [\rho^N_k]-X^\alpha [\rho_k] -(X^i_k- \overline{X}^i_k))|\right] \\ &\qquad +\sigma\sum_{\ell=1}^d \BE \left[ |(\xi^i_k)_\ell|\right]\BE\left[|(X^\alpha [\rho^N_k]-X^\alpha [\rho_k] -X^i_k- \overline{X}^i_k)_\ell|\right]  \\
    &\leq (\lambda+\sigma \sqrt{d})\BE \left[ |X^\alpha [\rho^N_k]-X^\alpha [\rho_k] -X^i_k- \overline{X}^i_k|\right] \\
    &\leq (\lambda+\sigma  \sqrt{d}) \Big( \underbrace{\BE \left[|X^\alpha [\rho^N_k]-X^\alpha [\rho_k]|\right]}_{\eqqcolon I} + \BE \left[|X^i_k- \overline{X}^i_k|\right]\Big),
\end{split}
\end{equation*}
where we used the norm inequalities 
\begin{equation}\label{eq:norms}
    |x|=\sqrt{\sum_{l=1}^d |x_l|^2} \leq \sum_{l=1}^d|x_l|=\lVert x \rVert_1 \leq \sqrt{d}|x|,
\end{equation}
and that $\BE[|(\xi^i_k)_l|]=1$ with the assumption $\xi^i_k=\overline{\xi}_k$ for all $i=1, \dots ,N$.  We note that the estimate is completely independent on the additional diffusion term $\tempconst \geq 0$.

To estimate the term $I$ above, consider now the empirical measures $\overline{\rho}_k^N = (1/N)\sum_{i=1}^N \delta_{\overline{X}_k^i}$ associated with the particles' positions $\{\overline{X}_k^i\}_{i=1}^N$. The triangle inequality gives us 
$$\BE \left[ |X^\alpha [\rho^N_k]-X^\alpha[\rho_k]| \right] \leq \BE \left[ |X^\alpha [\rho^N_k]-X^\alpha[\overline{\rho}^N_k]| \right] + \BE \left[|X^\alpha [\overline{\rho}^N_k]-X^\alpha[\rho_k]| \right]$$
Then, thanks to the boundedness of $\DD$, we can apply Lemma \ref{lem:measure-measure} to obtain
$$\BE \left[ |X^\alpha [\rho^N_k]-X^\alpha[\overline{\rho}^N_k]| \right] \leq C_0 \BE \left[ \WW_1(\rho^N_k, \overline{\rho}^N_k) \right] \leq C_0 \BE \left[\frac{1}{N}\sum_{j=1}^N|X^j_k-\overline{X}^j_k|\right].$$
Note that the second inequality follows from the fact that $(X_k^i,\overline{X}^i_k)$ is only one of the possible couplings between the two particle system, and it is not necessarily the optimal one realizing the Wasserstein distance.
Meanwhile, Lemma \ref{lem:measure-law} yields
$$\BE \left[ |X^\alpha[\overline{\rho}^N_k]-X^\alpha [\rho_k]| \right] \leq C_1N^{-1/2}, $$ since $\{\overline{X}^i_k \}_{i=1}^N$ are i.i.d. with a common distribution $\rho_k.$ So far, the constants $C_0, C_1$ depend only on the size of the domain $\mathcal{D}, \alpha$, and the objective function $\mathcal{F}$. 

By collecting the above estimates, we can bound the expected difference in the velocities as 
\be \label{eq:velocity}
\begin{split}
    \BE \left[ |V^i_{k+1}-\overline{V}^i_{k+1}| \right]
    &\leq e^{-\nu\Delta t}\BE \left[|V^i_k-\overline{V}^i_k|\right] \\
    &+(1-e^{-\nu\Delta t})(\lambda+\sigma \sqrt{d}) \left( C_0 \BE \left[\frac{1}{N}\sum_{j=1}^N|X^j_k-\overline{X}^j_k|\right] + C_1N^{-1/2}  \right).
\end{split}
\ee
Combining the upper bounds \eqref{eq:position} and \eqref{eq:velocity} we obtain
{
\begin{equation*}
\begin{split}
    & \BE\left[ |X^i_{k+1}-\overline{X}^i_{k+1}|\right] + \BE \left[|V^i_{k+1}-\overline{V}^i_{k+1}|\right] \\
    &\leq \BE\left[ |X^i_k-\overline{X}^i_k| \right] + (1+\dt)\BE \left[|V^i_{k+1}-\overline{V}^i_{k+1}|\right]\\
    &\leq \BE\left[ |X^i_k-\overline{X}^i_k| \right] (1+\Delta t) e^{-\nu\Delta t} \BE \left[|V^i_k-\overline{V}^i_k|\right]  \\
    & \qquad+ (1-e^{-\nu\Delta t})(\lambda+\sigma \sqrt{d}) \left( C_0 \BE \left[\frac{1}{N}\sum_{j=1}^N|X^j_k-\overline{X}^j_k|\right] + C_1N^{-1/2}  \right) \\
    &= \BE \left[ |X^i_k-\overline{X}^i_k| \right]+C_0(1+\Delta t)(1-e^{-\Delta t}) (\lambda +\sigma\sqrt{d} )\BE\left[\frac{1}{N}\sum_{j=1}^N|X^j_k-\overline{X}^j_k|\right]  \\ 
    &\qquad + (1+\Delta t)e^{-\nu\Delta t}\BE\left[ |V^i_k-\overline{V}^i_k| \right] +C_1(1+\Delta t)(1-e^{-\nu\Delta t}) (\lambda +\sigma  \sqrt{d} )N^{-1/2}\,,
\end{split}
\end{equation*}}
where in the last step we simply rearranged the terms. To later apply a (discrete) Gr{\"o}nwall-type argument, it is crucial to obtain estimates of order $(1 + C_2\Delta t)$,  or $C_3\Delta t$ for some constants $C_2,C_3$. As a consequence of $1-e^{-\nu \Delta t}\leq \nu \Delta t $, $e^{-\nu \Delta t} \leq 1$, and the assumption $\Delta t \in (0,1]$, we have the following further estimates:
\begin{align*}
(1 + \Delta t ) (1 - e^{-\nu \Delta t}) &\leq (1 + \Delta t) \nu \Delta t \leq 2 \Delta t \\
e^{-\nu\Delta t} (1 + \Delta t) &\leq (1 + \Delta t)\,.
\end{align*}
With the above, and summing over all particles $i=1, \dots, N$, we get 
\begin{align*}
    \BE& \left[ \frac{1}{N} \sum_{i=1}^N |X^i_{k+1}-\overline{X}^i_{k+1}| + |V^i_{k+1}-\overline{V}^i_{k+1}| \right] \\
    &\leq (1+\Delta tC_2) \BE\left[ \frac{1}{N} \sum_{i=1}^N |X^i_k-\overline{X}^i_k| + |V^i_k-\overline{V}^i_k| \right] + \Delta t C_3 N^{-1/2}, 
\end{align*}
where $C_2$  and $C_3$ are constants depending on $d, \lambda, \sigma, \alpha, \text{diam}(\mathcal{D}), \mathcal{F}$ (from $C_0, C_1$). 
Iterating the above inequality for $h=1,\dots,k$, one obtains 
\begin{align*}
    \BE& \left[ \frac{1}{N} \sum_{i=1}^N |X^i_k-\overline{X}^i_k| + |V^i_k-\overline{V}^i_k| \right] \\ 
    &\leq (1+\Delta t C_2)^k \BE  \left[ \frac{1}{N} \sum_{i=1}^N |X^i_0-\overline{X}^i_0| + |V^i_0-\overline{V}^i_0| \right] + \Delta tC_3 N^{-1/2}\sum_{h=1}^k(1+\Delta t C_2)^h.
\end{align*}
Since $X^i_0 = \overline{X}^i_0, V^i_0 = \overline{V}^i_0$ for all $i=1, \dots, N$, the first term disappears. 
By using the formula $\sum_{h=1}^k(1+\Delta t C_2)^h = ((1+\Delta t C_2)^{k}-(1+\Delta tC_2))/(\Delta t C_2)\,$,
the second term can instead be simplified as
\begin{align*}
    \BE \left[ \frac{1}{N} \sum_{i=1}^N |X^i_k-\overline{X}^i_k| + |V^i_k-\overline{V}^i_k| \right]
    & \leq \Delta tC_3 \frac{1}{\sqrt{N}}\sum_{h=1}^k(1+\Delta t C_2)^h \\
    & = \frac{C_3}{C_2} \left ( (1 +\Delta t C_2)^k - (1 +\Delta t C_2) \right) \leq  \frac{C_3}{C_2} e^{-k\Delta t C_2} 
\end{align*}
where we used $(1 +\Delta t C_2)^k \leq e^{k\Delta t C_2}$. Finally, taking supremum over $k\dt \in[0,T]$, we obtain \eqref{eq:propagation-of-chaos}.

\end{proof}

\subsection{Proof of Corollary~\ref{cor:propagation-of-chaos}}

With Theorem \ref{thm:propagation-of-chaos}, we quantified the distance between the particle system \eqref{eq:particle-sys-alg} and $N$ copies of independent, $f_k$-distributed, mono-particles processes \eqref{eq:nonlinear-update}. The derived estimate can be translated into an estimate on the 
Wasserstein distance between the corresponding empirical measure $f_k^N$ and $\overline{f}_k^N$, since
\begin{equation} \label{eq:coupling}
\WW_1(f_k^N, \overline{f}^N_k) \leq \frac{1}{N} \sum_{i=1}^N \left(|X_k^i-\overline{X}^i_k| +  |V_k^i-\overline{V}^i_k| \right).
\end{equation}
Note that we have used the fact that  $|(x,v) - (\overline{x},\overline{v})|\leq |x - \overline{x}| + |v - \overline{v}|$ for any $x,\overline{x},v,\overline{v}\in \RR^d$.

To quantify the distance between $\overline{f}^N_k$ and $f_k$, we recall the following quantitative result. Below, $\mu^N$ is the empirical measure of a system of independent $\mu$-distributed particles.
\begin{theorem}[{\cite[Theorem 1]{fournierRateConvergenceWasserstein2013}}] \label{lem:moments}
Let $\mu \in \mathcal{P}(\RR^{\tilde d})$ and let $p>0$. Assume that $M_q(\mu)<\infty$ for some $q>p$.  There exists a constant $C$ depending only on $p,{\tilde d},q$ such that for all $N \geq 1$:
$
\mathbb{E}\left[  \WW_p(\mu,\mu^N)\right] \leq C M_q^{p/q}(\mu) \e_{p}(N)
$
with 
\begin{equation*}
\e_{p}(N):=
\begin{cases}
N^{-1/2} + N^{-(q-p)/q} & \textup{if} \;\;p>{\tilde d}/2 \;\;\;\textup{and} \;\; q \neq 2p, \\
N^{-1/2}\log(1+N) + N^{-(q-p)/q} & \textup{if} \;\;p={\tilde d}/2 \;\;\;\textup{and} \;\; q \neq 2p, \\
N^{-p/{\tilde d}} + N^{-(q-p)/q} & \textup{if} \;\;p\in(0,{\tilde d}/2) \;\;\;\textup{and} \;\; q \neq {\tilde d}/({\tilde d}-p).
\end{cases}
\end{equation*}

\end{theorem}

Note that the order of convergence given in Corollary \ref{cor:propagation-of-chaos} is a consequence of the above theorem with $\tilde{d} = 2d$ (since we are considering the position-velocity space $\RR^d\times \RR^d$) and $p=1$.
Also, it tells us that the error introduced by any Monte Carlo strategy is related to the moments of the kinetic density. Therefore, we collect an estimate on the moments of $f_k = \textup{Law}(\overline{X}_k, \overline{V}_k)$, for which the assumption of boundedness of $\DD$ is crucial.

\begin{lemma}
\label{l:qmoments}
Let $f_0 \in \mathcal{P}_q(\DD\times\RR^d)$ for some $q>1$, and $f_k = \textup{Law}(\overline{X}_k, \overline{V}_k)$ with $(\overline{X}_k, \overline{V}_k)$ iteratively defined by \eqref{eq:nonlinear-update}.
There exists a positive constant $C = C(q,\mathcal{D},\lambda, \sigma,\sigma_0)$ such that
\[
M_q(f_k) \leq \max \left\{ M_q(f_0), C \right\} \qquad \textup{for all steps $k$.} 
\]
\end{lemma}
\begin{proof}
First, we note that if the particles' positions are projected towards the bounded domain $\mathcal{D}$ at every iteration, then the consensus point also belongs to $\DD$. Moreover, we have $\textup{ess} \sup|\overline{X}_k| \leq R$ for $R$ large enough such that $\DD \subset B(0,R)$. It follows $\BE[|\overline{X}_k|^q] \leq R^q$.
For the velocity, it holds 
\begin{align*}
\mathbb{E}[|\overline{V}_{k+1}|^q] &\leq e^{-\nu\Delta t} \mathbb{E}[|\overline{V}_{k}|^q] + (1 - e^{-\nu\Delta t })\mathbb{E}[|\overline{W}_{k}|^q] \\
& \leq \max\{\mathbb{E}[|\overline{V}_{k}|^q], \mathbb{E}[|\overline{W}_{k}|^q]\}\,.
\end{align*}
To estimate $\BE[|\overline{W}_{k}|^q]$, we again use that $|X^\alpha[\rho_k] - \overline{X}_k|\leq \textup{diam}(\DD)$ everywhere:
\begin{align*}
\BE[|\overline{W}_k|^q] &= \iint |\lambda(X^\alpha[\rho_k]) - x) + \sigma(\sigma_0 + X^\alpha[\rho_k] - x) |^q \rho_{k}(dx) p^\xi(d\xi) \\
& \leq c_q \int (\lambda \textup{diam}(\DD))^q + \sigma^q(\sigma_0 + \textup{diam}(\DD))^q |\xi|^q p^\xi(d\xi)\\
& \leq C_1
\end{align*}
where $c_q>0$ is a constant depending on $q$, while $C_1$ depends on $q,\mathcal{D},\lambda, \sigma,\sigma_0$ and the $q$-th moment of the standard Gaussian distribution. Therefore, since $\mathbb{E}[|\overline{X}|^q] \leq R^q$ and $\BE[|\overline{V}_k|^q] \leq \max\{\BE[|\overline{V}_0|],C_1^q\}$ we also have that the $q$-th moment $M_q(f_k)$ can be upper bounded with either $M_q(f_0)$ or a constant which depends on $C_1$.
\end{proof}

\begin{proof}[Proof of Corollary \ref{cor:propagation-of-chaos}.]
First, thanks to Lemma \ref{lem:moments} and Lemma \ref{l:qmoments}, we have that for all $k$
\[
 \BE \left[ \WW_1 (\overline{f}^N_k, f_k) \right] \leq CM_q(f_k)\e(N) \leq C_1 \e(N)
\]
with $C_1 = C_1(\mathcal{D},q,f_0, \lambda, \sigma, \sigma_0, p^\xi)>0$. Next, we note that by Theorem \ref{thm:propagation-of-chaos},
\[
\sup_{k\Delta t\in [0,T]} \mathbb{E} \left[\WW_1(f_k^N,\overline{f}_k^N) \right] \leq C_2e^{C_2T}\frac1{\sqrt{N}}
\]
where $C_2 = C_2(\alpha, \mathcal{D},\lambda, \sigma, \sigma_0 ,\mathcal{F})>0$. By triangular inequality, we can conclude that
\begin{align*}
\sup_{k\Delta t\in [0,T]} \BE \left[\WW_1(f^N_k, f_k)\right]&\leq
\sup_{k\Delta t\in [0,T]} \BE \left[\WW_1(f^N_k, \overline{f}^N_k)\right] + \sup_{k\Delta t\in [0,T]} \BE \left[ \WW_1(\overline{f}^N_k, f_k) \right]\\
&\leq C\left( e^{CT}\frac1{\sqrt{N}} +   \e(N)\right) \,.
\end{align*}
\end{proof}
