% To protect the secret states from unauthorized access, the third condition is proposed to require that, for each sequence reaching secret states, the edit function should generate an edited sequence such that the secret states cannot be revealed from the intruder’s estimates.
% In the end, the fourth condition is proposed to maintain the accuracy and consistency of the edited behavior, i.e., each subsequent edited sequence holds the conditions 1)--3).

\begin{definition}($i$-availability)
    Consider a system $G$ with respect to the projection $P$. An edit function $f_e$ is $i$-available if for all $\sigma\in P[L(G)], f_e(\sigma)$ is defined.
\end{definition}

\begin{definition}($c$-availability)
    Consider a system $G$ with respect to the projections $P$ and $P_D$. An edit function $f_e$ is $c$-available if for all $\sigma,\sigma'\in P[L(G)]$, $ P_D(\sigma)=P_D(\sigma')$ implies that $f_e(\sigma)$ and $f_e(\sigma')$ are defined such that $P_D(f_e(\sigma))=P_D(f_e(\sigma'))$.
\end{definition}

Availability ensures that an edit function is accessible and usable when needed. 
Specifically, $i$-availability requires that an edit function should react to each observable event generated by the system (recall that, by construction, no modification is allowed if (i) the event is not observed by the edit function or (ii) the event is observed by the edit function but it is substituted with itself). 
Moreover, under the incomparable observation setting, an edit function should also ensure that its output can be recognized by the intruder.
Thus, $c$-availability is proposed to require that an edit function should implement the same edit actions to all sequences that have the same defender projection (the edit function cannot react differently since its observations are identical).
For the sake of simplicity, we say that an edit function is available if it is $i$-available and $c$-available.

\begin{definition}(Confidentiality)\label{defconfidential}
    Consider a system $G$ with respect to the projections $P$ and $P_I$. An edit function $f_e$ is confidential if for all $\sigma\in P(L_S)$, $P_I^{-1}[P_I(f_e(\sigma))]\cap L_{NS}\neq~\emptyset$.
\end{definition}

Confidentiality involves protecting the secret states from unauthorized access by requiring that, for each sequence reaching secret states, an edit function should generate an edited sequence such that the secret states cannot be revealed from the intruder’s estimates.

\begin{remark}
In prior works such as \cite{2014Wu, 2018Wu, 2018Ji, 2019Ji, 2023Duan}, enforcing opacity means that either the insertion function or the edit function must consistently output a sequence that reaches non-secret states, ensuring the intruder cannot deduce the current state of the system as a secret state.
To enhance the flexibility of the edit function, we require that the edit function should only confuse the intruder when necessary.
By taking advantages of the notion of confidentiality formulated in Definition \ref{defconfidential}, the edit function is also able to output a sequence that reaches secret states as long as the system is in non-secret states in reality; that is, the secret states are not reached in reality but we let the intruder believe that they are reached.  
$\hfill\diamond$
\end{remark}

\begin{definition}(Integrity)
    Consider a system $G$ with respect to the projection $P$. An edit function $f_e$ is integral if for all $\sigma \beta\in P[L(G)]$, $f_e(\sigma \beta)=f_e(\sigma)f_e(\beta)$ is available and confidential.
\end{definition}

Integrity refers to the ability of maintaining the accuracy and consistency of the edit actions. 
That is, an edit function should ensure that each subsequent edited sequence maintains availability and confidentiality.

\begin{definition}
    An edit function is $ic$-enforcing if it is available, confidential, and integral.
\end{definition}

\subsection{Problem formulation}

Consider a system modeled by a DFA $G=(X,E,f,x_0)$, where the set of secret states is $X_S\subseteq X$.
Assume that the intruder and an edit function have incomparable observation capabilities of the system.
Our goal is to design an edit mechanism such that any edit function synthesized from it is able to protect the secret states from being revealed by the intruder when the secret states are reached in reality.
The problem is formally presented as follows.
%In the remainder of the paper, we aim to develop two synthesis algorithms for $iu$-enforcing and $ik$-enforcing edit functions. 

\begin{problem}
    Consider a system modeled as DFA $G=(X,E,f,x_0)$ with a set of secret states $X_S\subseteq X$, the set of events observed by the intruder $E_I$, and the set of events observed by an edit function $E_D$, where $E_I$ and $E_D$ are incomparable. We aim to construct an edit mechanism for all edit functions to be $ic$-enforcing.
\end{problem}



