\begin{lstlisting}[language=,caption={Maude encoding of the SDN in~(\ref{eq:run-ex})},label={lst:maude}]
fmod MODEL is
    [...]

    ops Init : -> DNA .
    ops SW, SWP, C : -> Recursive .
    ops Help, Up : -> Channel .

    eq getRecPol(SW) =
         "(flag = regular) . (pt = 1) . (pt <- 2)" ; SW o+
         "(flag = blocking) . (pt = 1) . 1" ;( (Help ! "one") ; SW ) o+
         (Up ? "one") ; SWP .
    eq SWP = zero ; bot .
    eq getRecPol(C) = (Help ? "one") ; ( (Up ! "one") ; C ) .

    eq Init = C || SW .
endfm
\end{lstlisting}

