\subsection{PASS Channel Model}

In the MIMO scenario, high-frequency bands, i.e., millimeter-wave (mmWave) and terahertz (THz) \cite{marco2020thz,Elayan2020thz}, are utilized by the NOMA assisted PASS framework. In this paper, we make a practical assumption that the LoS paths between each UE and BS are considered and non-LoS paths are ignored since the non-LoS paths are much weaker than LoS paths \cite{xu2025pass}. Thus, the LoS-dominant model and the geometric free-space spherical model are utilized to formulate the channel vector between PA $l$ along waveguide $n$ and UE $k$ in the cluster $q$,
\begin{equation}
    \label{channelvector}
    h^{H}_{q,k,n,l}=h_{q,k}^{H}(x_{n,l})=\frac{\eta e^{-i{\kappa}\left|{\bm{\psi}}_{q,k}^{\text{U}}-{\bm{\psi}}_{n,l}^{\text{PA}}\right|}}{\left|{\bm{\psi}}_{q,k}^{\text{U}}-{\bm{\psi}}_{n,l}^{\text{PA}}\right|},
\end{equation}
where $\kappa=\frac{2\pi}{\lambda}$ represents the wave-domain number, and $\lambda$ is the wavelength. The constant $\eta=\frac{c}{4\pi f_c}$ depends on the speed of light $c$ and carrier frequency $f_c$. $\frac{\eta}{\left|{\bm{\psi}}_{q,k}^{\text{U}}-{\bm{\psi}}_{n,l}^{\text{PA}}\right|}$ represents the channel gain coefficient. Suppose that UEs in each cluster has the same location along $y$-axis, because the difference in position variation on the $y$-axis is much smaller than that of the $x$-axis. And ${\mathbf{h}}^H_{q,k}(\mathbf{x}_n) \in \mathbb{C}^{1 \times L}$ represents the channel vector from all PAs along waveguide $n$ to UE $k$. Let ${\mathbf{h}}^H_{q,k}(\mathbf{X})=[{{\mathbf{h}}^H_{q,k}\left(\mathbf{x}_{1}\right)},{{\mathbf{h}}^H_{q,k}\left(\mathbf{x}_{2}\right)},\dots,{{\mathbf{h}}^H_{q,k}\left(\mathbf{x}_{N}\right)}] \in \mathbb{C}^{1 \times M}, M=L\times N$ denote the stacked channel vectors from all PAs to UE $k$ in cluster $q$. The element of response vector from the feed point of waveguide $n$ to the corresponding PAs $\mathcal{L}$ can be expressed as
\begin{equation}
    \label{ele_responsevector}
    g_{n,l}(x_{n,l})= \frac{1}{\sqrt{L}}e^{-i\frac{2\pi}{{\lambda}_g}\left|{\bm{\psi}}_{n,0}^{\text{PA}}-{\bm{\psi}}_{n,l}^{\text{PA}}\right|}=\frac{1}{\sqrt{L}}e^{-i\frac{2\pi}{{\lambda}_g}x_{n,l}},
\end{equation}
where $\lambda_g=\frac{\lambda}{n_{\text{eff}}}$ is the guided wavelength, $n_{{\text{eff}}}$ is the effective refractive index of the dielectric waveguide, and $1/{\sqrt{L}}$ represents the power allocation coefficient for all PAs along each waveguide. The above response vector can be expressed as $\mathbf{g}_n(\mathbf{x}_n) \in \mathbb{C}^{L \times 1}$. Then, we can derive the block-diagonal in-wavegudie channel matrix $\mathbf{G}(\mathbf{X}) \in \mathbb{C}^{M \times N}$, which stacks response vectores from all feed points to the corresponding PAs,
\begin{equation}
    \label{blkdiag}
    \begin{aligned}
        \mathbf{G}(\mathbf{X})& =\mathrm{blkdiag}\left(\mathbf{g}_1(\mathbf{x}_1),\mathbf{g}_2(\mathbf{x}_2),\dots,\mathbf{g}_N(\mathbf{x}_N)\right) \\
        & \left.=\left[
        \begin{array}{cccc}
            \mathbf{g}_1\left(\mathbf{x}_1\right) & \mathbf{0} & \ldots & \mathbf{0} \\
            \mathbf{0} & \mathbf{g}_2\left(\mathbf{x}_2\right) & \ldots & \mathbf{0} \\
                \vdots & \vdots & \ddots & \vdots \\
            \mathbf{0} & \mathbf{0} & \ldots & \mathbf{g}_N\left(\mathbf{x}_N\right)
        \end{array}
        \right.\right].
    \end{aligned}
\end{equation}

\subsection{Signal Model}
Since each waveguide is fed by the same signal, which is multiplexed at the baseband by performing transmit beamforming, subsequently converted by the RF chain, and finally fed into the waveguide for radiation. Denote $s_q$ as the transmit signal radiated from the PASS system to all UEs in cluster $q$, which is given by
\begin{equation}
    \label{transmitsignal}
    s_q=\sum_{k=1}^{K}\sqrt{\alpha_{q,k}}s_{q,k},
\end{equation}
where $\alpha_{q,k}$ is the power allocation coefficient for UE $k$ in cluster $q$. Suppose that $s_q \in \mathbb{C}$ is the zero-mean unit-variance stationary process satisfying $\mathbb{E}\left[s_q^H{s_q}\right]=1$. Let the received signal at UE $k$ in cluster $q$ through channels manipulated by PASS system, expressed as
\begin{equation}
    \label{receivedsignal}
    \begin{aligned}
        y_{q,k} = & \underbrace{{\mathbf{h}_{q,k}^H\mathbf{G}}\mathbf{w}_q\sqrt{\alpha_{q,k}}s_{q,k}}_{\text{desired signal}}+\underbrace{\mathbf{h}_{q,k}^H\mathbf{G}\mathbf{w}_q\sum_{i=1,i\neq k}^{K}\sqrt{\alpha_{q,i}}s_{q,i}}_{\text{intra-cluster interference}}\\
        & +\underbrace{\sum_{j=1,j\neq q}^Q\mathbf{h}_{q,k}^H\mathbf{G}\mathbf{w}_j\sum_{i=1}^{K}\sqrt{\alpha_{j,i}}s_{j,i}}_{\text{inter-cluster interference}}+z_k,
    \end{aligned}
\end{equation}
where $z_k \in \mathcal{CN}(0,\sigma^2)$ is the CSCG with zero mean, $\sigma^2$ is the noise power. Moreover, $\mathbf{w}_q \in \mathbb{C}^{N \times 1}$ denotes the transmit beamforming vector for UEs in cluster $q$ and ${\mathbf{h}_{q,k}^H\mathbf{G}}$ represents the corresponding pinching beamforming. The signal-to-interference-and-noise ratio (SINR) of UE $k$ can be formulated as
\begin{equation}
    \label{SINR}
    \begin{aligned}
        & \mathrm{SINR}_{q,{k\to k^{\prime}}} = \\
        & \frac{\left|\mathbf{h}_{q,k^{\prime}}^{H}\mathbf{G}{\mathbf{w}_q}\right|^{2}\alpha_{q,k}}{\left|\mathbf{h}_{q,k^{\prime}}^{H}\mathbf{G}{\mathbf{w}_q}\right|^{2}\!\sum\limits_{i=k+1}^{K}\!\alpha_{q,i}+\!\sum\limits_{j=1,j\neq q}^{Q}\!\left|\mathbf{h}_{q,k^{\prime}}^{H}\mathbf{G}\mathbf{w}_{j}\right|^{2}+\sigma^{2}},\\
        & \forall k,k^{\prime} \in \mathcal{K}, k^{\prime} \ge k,
    \end{aligned}
\end{equation}
% \begin{equation}
%     \label{SINR}
%     \begin{aligned}
%         {\underset{q,{k\to k^{\prime}}}{\mathrm{SINR}}}=\frac{\left|\mathbf{h}_{q,k^{\prime}}^{H}\mathbf{G}{\mathbf{w}_q}\right|^{2}\alpha_{q,k}}{\left|\mathbf{h}_{q,k^{\prime}}^{H}\mathbf{G}{\mathbf{w}_q}\right|^{2}\sum\limits_{i=k+1}^{K}\alpha_{q,i}+\sum\limits_{j=1,j\neq q}^{Q}\left|\mathbf{h}_{q,k^{\prime}}^{H}\mathbf{G}\mathbf{w}_{j}\right|^{2}+\sigma^{2}},
%     \end{aligned}
% \end{equation}
where $k^{\prime}=k,k+1,\dots,K$. Then, the corresponding achievable rate is
\begin{equation}
    \label{rate_qk}
    R_{q,k}=\log_2\left(1+\min_{k^{\prime}=k,k+1,\cdots,K}\left\{{\mathrm{SINR}_{q,{k\to k^{\prime}}}}\right\}\right).
\end{equation}

Since the number of UEs in each cluster is no less than 2, each UE needs to eliminate intra-interference by utilizing SIC technology \cite{yuanwei2017NOMA,2022SICli}. To guarantee the SIC performed successfully, the requirements $R_{j,k} \ge R_{q,k}$ with $j \ge k$ should be met according to the principle of NOMA.

\subsection{User Grouping}

\begin{algorithm}[htbp]
    \caption{NOMA Assisted PASS User Grouping Algorithm}
    \label{alg:user_grouping}
    \begin{algorithmic}[1]
    \REQUIRE 
    User set $\mathcal{K} = \{1,2,\dots,K\}$; Number of clusters $Q$; Channel vectors $\{\mathbf{h}_k\}$; Users' positions $\{{\bm{\psi}}_{k}^{\text{U}}\}$; Weighting factor $\varpi$; Parameter $\sigma$.
    \ENSURE 
    User grouping result $\{\mathcal{Q}_1,\mathcal{Q}_2, \dots, \mathcal{Q}_Q\}$.
    \STATE Initialize: Randomly select $M$ users as initial representatives $\{\Xi_q^{(0)}\}$.
    \STATE Set iteration index $t \leftarrow 0$.
    \REPEAT
        \FOR{each user $k =1,2,\dots,K$}
            \FOR{each cluster $q = 1,2,\dots,Q$}
                \STATE Compute similarity 
                $C_{k,\Omega_m^{(t)}}$ by (\ref{jointcorrelation})
            \ENDFOR
            \STATE Assign user $k$ to cluster $q_k^*$ where (\ref{clusterdistribution})
        \ENDFOR
        \FOR{each cluster $q = 1,2,\dots,Q$}
            \STATE Update head user $\Xi_q^{(t+1)}$ as
            $\Xi_q^{(t+1)}$ by (\ref{updatedhead})
        \ENDFOR
        \STATE $t \leftarrow t+1$
    \UNTIL{Convergence by $\{\Xi_q^{(t)}\} = \{\Xi_q^{(t-1)}\}$}
    \RETURN $\{\mathcal{Q}_1,\mathcal{Q}_2, \dots, \mathcal{Q}_Q\}$.
    \end{algorithmic}
    \end{algorithm}

Since the number of users is larger than the number of PAs along each waveguide, it is significant to perform user grouping in NOMA assisted PASS. Based on the equivalent channel correlation between the remaining users, highly channel correlated users are suppose to be assigned into the same cluster, while uncorrelated channel users should be assigned into different clusters to reduce the interference. Moreover, there is not only channel correlation between users, but also location correlation between PAs. Thus, we denote the joint channel and location correlation metric between user $k$ and user $i$ as
\begin{equation}
    \label{jointcorrelation}
    C_{k,i}(\hat{x}_{k,i})=\varpi \frac{{\mathbf{h}^H_k(\hat{x}_{k,i})}{\mathbf{h}_i(\hat{x}_{k,i})}}{\left\|\mathbf{h}_i(\hat{x}_{k,i})\right\|\left\|\mathbf{h}_k(\hat{x}_{k,i})\right\|} + (1-\varpi)e^{-\frac{\left|{\bm{\psi}}_{k}^{\text{U}}-{\bm{\psi}}_{i}^{\text{U}}\right|}{\sigma^2}},
\end{equation}
where $\varpi \in [0,1]$ is the weight that balances channel and space information. Notably, $\mathbf{h}_k$ depends on the estimated location of user $k$, referred as $\hat{x}_{k,i}$. To enable initial user grouping before the joint optimization process, the estimated user location can be employed to compute the approximate channel vectors $\mathbf{h}^H_k(\hat{x}_{k,i})$. These surrogate channel vectors are utilized to calculate the preliminary group matric $C_{k,i}(\hat{x}_{k,i})$. Then, the K-means cluster algorithm \cite{zhu2019usergroup} is utilized to schedule user grouping. Specifically, we select $Q$ users as the head of $Q$ clusters, denoted by $\left\{\Xi_1,\Xi_2,\dots,\Xi_Q\right\}$. According to the joint channel and location correlation (\ref{jointcorrelation}), the remaining users can be distributed to the cluster $q$, measured by
\begin{equation}
    \label{clusterdistribution}
    q^*_k=\underset{k}{\arg} \max_{1 \le q \le Q} C_{k,\Xi_q},
\end{equation}
Then, the head of cluster $q$ is supposed to be updated, which satisfies that its joint channel and location correlation is the lowest with the other clusters. Moreover, the joint channel and location correlation between user $k$ to other users of the other clusters, measured by
\begin{equation}
    \label{correlationcluster}
    \tilde{C}_k = \sum_{1\le j \le K}^{j \notin \mathcal{Q}(k)}C_{k,j},
\end{equation}
where $\mathcal{Q}(k)$ represents the cluster including user $k$. The updated head of cluster $q$ can be expressed as
\begin{equation}
    \label{updatedhead}
    \Xi_q=\underset{j \notin \mathcal{Q}(k)}{\arg} \min \tilde{C}_k.
\end{equation}

Finally, we can obtain the optimal user grouping $\mathcal{Q}=\left\{k|q^*_k=q\right\}, \forall q\in \left\{1,2,\dots,Q\right\}, k \in \left\{1,2,\dots,K\right\}$. The joint channel and location correlation based user grouping algorithm is shown as Algorithm \ref{alg:user_grouping}.




\subsection{Problem Formulation}
In NOMA assisted PASS framework, we aim to minimize the transmit power by jointly optimizing the transmit beamforming $\mathbf{W}=[\mathbf{w}_{1}, \mathbf{w}_{2},\dots,\mathbf{w}_{Q}]$, pinching beamforming $\mathbf{X}=[\mathbf{x}_{1},\mathbf{x}_{2},...,\mathbf{x}_{N}]$, and NOMA power allocation $\bm{\alpha}=[\bm{\alpha}_{1}, \bm{\alpha}_{2},\dots,\bm{\alpha}_{Q}]$. The transmit power minimization problem is formulated as
\begin{subequations}
    \label{min_transmitpower0}
    \begin{align}
            \mathbf{P}_0: \quad & \min_{\mathbf{W}, \mathbf{X}, \bm{\alpha}}\sum_{q=1}^{Q}\left\|\mathbf{w}_{q}\right\|_{2}^{2},
            \label{minw_q}\\
            \mathrm{s.t.~} \quad & R_{q,k} \ge R_{q,k}^{\mathrm{min}},k\in\mathcal{K},q\in\mathcal{Q},
            \label{rateconstraints}\\
            & \sum_{k=1}^{K}\alpha_{q,k}=1,q\in\mathcal{Q}, 
            \label{sumpower}\\
            & 0<\alpha_{q,k}<1,k\in\mathcal{K},q\in\mathcal{Q},
            \label{powerconstraints}\\
            & x_{n,l}-x_{n,l-1} \ge \Delta, l\in\mathcal{L}, n\in\mathcal{N},
            \label{PA_minx}\\
            & x_{n,l}\in[0,x_{n,L}], l\in\mathcal{L}, n\in\mathcal{N},
            \label{PA_x}
    \end{align}
\end{subequations}
