\section{Gradient-Based Solution of Transmit Power Minimization For NOMA Assisted PASS}
The transmit power minimization problem is a nonconvex problem, we convert it into the tractable form based on alternating optimization (AO) and augmented Lagrangian (AL) methods \cite{Hong2016aoal} to successively optimize transmit beamforming, pinching beamforming and power allocation, which is tranformed to
\begin{subequations}
    \label{min_transmitpower1}
    \begin{align}
        \mathbf{P}_1: \text{ } &\min_{\substack{\mathbf{W},\mathbf{X},\\ \bm{\alpha},\bm{\beta}}}\sum_{q=1}^{Q}\left\|\mathbf{w}_{q}\right\|_{2}^{2}\! +\!\frac{1}{\mu}\sum_{q=1}^{Q}\sum_{j=1}^{Q}\sum_{k=1}^{K}\left|\mathbf{h}_{q,k}^{H}\mathbf{G}\mathbf{w}_{j}\!-\!\beta_{q,k,j}\right|^{2}\!,
        \label{AOALM}\\
        \mathrm{s.t.~} \text{ }& \frac{\left|\beta_{q,k^{\prime},j}\right|^{2}\alpha_{q,k}}{\left|\beta_{q,k^{\prime},j}\right|^{2}\!\sum\limits_{i=k+1}^{K}\!\alpha_{q,i}\!+\!\sum\limits_{\substack{j=1,\\j\neq q}}^{Q}\!\left|\beta_{q,k^{\prime},j}\right|^{2}\!+\!\sigma^{2}}\ge {\mathrm{SINR}}_{q,k}^{\min},
        \label{SINRconstraint1}\\
        % & \frac{\left|\beta_{q,K,j}\right|^{2}\alpha_{q,K}}{\sum_{j=1,j\neq q}^{Q}\left|\beta_{q,K,j}\right|^{2}+\sigma^{2}}\ge {\mathrm{SINR}}_{q,k}^{\min},
        % \label{SINRconstraint2}\\
        & \text{(\ref{rateconstraints})-(\ref{PA_x})},
        \end{align}
\end{subequations}
where $\beta_{q,k,j}={\mathbf{h}_{q,k}^H\mathbf{G}}\mathbf{w}_j$ is introduced to relax the $\mathbf{P}_1$, ${\mathrm{SINR}}_{q,k}^{\min}$ and ${\mathrm{SINR}}_{q,k}^{\min}$ are the minimum SINR threshold required for data flow of UE $k$ and UE $K$, respectively. Constraint (\ref{SINRconstraint1}) guarantees that the non-last UE can be processed by SIC in cluster $q$, which proves NOMA assisted PASS can decode strong signals. In addition, constraint (\ref{SINRconstraint1}) ensures that the last UE can be processed by SIC in cluster $q$, which means this system can decode its own signal. Meanwhile, these two constraints ensure the successful decoding and user fairness of NOMA assisted PASS.


Due to the strong coupling between the variables, $\mathbf{P}_1$ is a constrained nonconvex optimization problem and belong to nonconvex second-order cone programming (SOCP). To solve this nonconvex problem, we decompose it into three decoupled problems. The transmit beamforming $\mathbf{w}_q$ is is first separated from $\mathbf{P}_1$ to formulate the transmit beamforming optimization problem. The location of PA ${\bm{\psi}}^{\text{PA}}_{n,l}$ and pinching beamforming $\mathbf{h}_{q,k}^H\mathbf{G}$ are further optimized by solving the pinching beamforming optimization problem. Furthermore, The power allocation optimization problem is formulated to optimize the power allocation for UEs $\alpha_{q,k}$. To solve the above subproblems, we adopt the AO and block coordinate descent (BCD) methods and develop a MM-PDD algorithm. Specifically, the MM-PDD algorithm is proposed to refactor the coupling constraints into AL functions, and then successively update these variables during the block updating process, where nonconvex component would be relaxed by majorization minimization \cite{shi2020PDD}.

%Then, the convex approximation techniques are utilized to search for stationary solutions. Specifically, the majorization-minimization and penalty dual decomposition (MM-PDD) algorithm is proposed to sequentially optimize the transmit beamforming ${\mathbf{w}_q}$, location of PA ${\bm{\psi}}^{\text{PA}}_{n,l}$, pinching beamforming ${\mathbf{h}_{q,k}^H\mathbf{G}}$, and power allocation for UEs $\alpha_{q,k}$. 
\subsection{Transmit Beamforming Optimization Problem}
To minimize the transmit power, the transmit beamforming optimization problem can be formulated as
\begin{subequations}
    \label{powerbudget_min}
    \begin{align}
        \mathbf{P}_2: \quad & \min_{\mathbf{w}_{q}}\sum_{q=1}^{Q}\left\|\mathbf{w}_{q}\right\|_{2}^{2} +\frac{1}{\mu}\sum_{q=1}^{Q}\sum_{j=1}^{Q}\sum_{k=1}^{K}\left|\mathbf{h}_{q,k}^{H}\mathbf{G}\mathbf{w}_{j}-\beta_{q,k,j}\right|^{2}
        \label{AL}\\
        \mathrm{s.t.~} \quad & \text{(\ref{rateconstraints})-(\ref{powerconstraints})}.
    \end{align}
\end{subequations}

We introduce two auxiliary variables that the distance and signal phase between PA $l$ and UE $k$ in cluster $q$, denoted as $d^{\text{PU}}_{n,l,q,k}=\sqrt{\left(x_{n,l}-x_{q,k}^{\text{U}}\right)^{2}+\left(y_n-y^{\text{U}}_{q,k}\right)^{2}+{d^{\text{z}}_0}^2}$, $\theta_{n,l,q,k}=\kappa \left(d^{\text{PU}}_{n,l,q,k}+n_{\text{eff}}x_{n,l}\right)$, respectively. The above problem involving nonconvex term is transformed into the following equationally constraint
\begin{equation}
    \label{distanceconstraint}
    b^{\text{U}}_{n,l,q,k} \triangleq d^{\text{PU}}_{n,l,q,k}-\sqrt{\left(x_{n,l}-x_{q,k}^{\text{U}}\right)^{2}+\left(y_n-y^{\text{U}}_{q,k}\right)^{2}+{d^{\text{z}}_0}^2}.
\end{equation}
% The above problem involving nonconvex terms is transformed into the following equationally constraints
% \begin{equation}
%     \label{auxiliaryconstraints}
%     \begin{aligned}
%         \begin{cases}
%             {b^{\text{U}}_{n,l,q,k} \triangleq d^{\text{PU}}_{n,l,q,k}-\sqrt{\left(x_{n,l}-x_{q,k}^{\text{U}}\right)^{2}+\left(y_n-y^{\text{U}}_{q,k}\right)^{2}+{d^{\text{z}}_0}^2}}.\\
%             {b^{\theta}_{n,l,q,k} \triangleq \theta_{n,l,q,k} - \kappa \left(d^{\text{PU}}_{n,l,q,k}-n_{\text{eff}}x_{n,l}\right)}.
%         \end{cases}
%     \end{aligned}
% \end{equation}

Define the AL function of $\mathbf{P}_2$ as follows
\begin{equation}
    \label{AL_I2}
    \begin{aligned}
        \mathcal{L}_{w}&\left(\mathbf{w}_{q},\alpha_{q,k},\bm{\psi}_{n,l}^{\mathrm{PA}},\beta_{q,k,j},\lambda^{\text{U}}_{n,l,q,k}\right) = \sum_{q}\left\|\mathbf{w}_{q}\right\|_{2}^{2} \\
        & +\frac{1}{2\rho}\sum_{n,l,q,k}\left|\mathbf{h}_{q,k}^{H}\mathbf{G}\mathbf{w}_{j}-\beta_{q,k,j}+\rho \lambda^{\text{U}}_{n,l,q,k}\right|^{2},
    \end{aligned}
\end{equation}
where $\lambda^{\text{U}}_{n,l,q,k}$ is the dual variable corresponding to (\ref{distanceconstraint}), $\rho$ is the penalty parameter including the $\mu$ of $\mathbf{P}_2$. Let $f_w(\mathbf{w}_q)= \mathcal{L}_{w}\left(\mathbf{w}_{q},\alpha_{q,k},\bm{\psi}_{n,l}^{\mathrm{PA}},\beta_{q,k,j},\lambda^{\text{U}}_{n,l,q,k}\right)$. To distinguish $\mathbf{w}_q$, we introduce a dummy variable $q^{\prime}$ and then derive the derivative of the above AL function 
\begin{equation}
    \label{firstorderL_wq}
    \begin{aligned}
        & \nabla_{\mathbf{w}_{q}}\mathcal{L}_{w}= \nabla f_w(\mathbf{w}_{q})\\
        &= 2\mathbf{w}_{q} + \frac{1}{\rho}\sum_{q^{\prime},k}\mathbf{G}^H\mathbf{h}^*_{q^{\prime},k}\left(\mathbf{h}_{q^{\prime},k}^{H}\mathbf{G}\mathbf{w}_{q}-\beta_{q^{\prime},q,k}+\rho \lambda^{\text{U}}_{q^{\prime},q,k}\right).
    \end{aligned}
\end{equation}

The $\mathcal{L}_{w}\left(\mathbf{w}_{q},\alpha_{q,k},\bm{\psi}_{n,l}^{\mathrm{PA}},\beta_{q,k,j},\lambda^{\text{U}}_{n,l,q,k}\right)$ is a quadratic convex function with respect to $\mathbf{w}_q$ during the BCD updating process. It can be be directly derived to zero and can be quickly analyzed and solved.

\begin{definition}
    The strict analytical solution of AL function (\ref{AL_I2}) can be directly obtained by  derivation to zero of the quadratic convex function on $\mathbf{w}_q$.
    \begin{proof}
        The Lipschitz gradient surrogate (LGS) method \cite{wu2024LGS}, essentially a MM method for approximating strictly convex functions of nonconvex (or convex but complex) functions, is utilized to solve (\ref{AL_I2}). For the above objective function $f_w(\mathbf{w}_q)$, the second derivative (Hessian) matrix is
        \begin{equation}
            \label{secondorderL_wq}
            \nabla^2_{\mathbf{w}_{q}}(\mathbf{w}_q)= \nabla^2 f_w(\mathbf{w}_{q})= 2I + \frac{1}{\rho}\sum_{q^{\prime},k}\mathbf{G}^H\mathbf{h}^*_{q^{\prime},k}\mathbf{h}_{q^{\prime},k}^{H}\mathbf{G}.
        \end{equation}

        Since $\nabla^2_{\mathbf{w}_{q}}(\mathbf{w}_q)$ is the constant matrix, the gradient of (\ref{AL_I2}) is Lipschitz-continuous, and hence, the Lipschitz constant can be taken as the spectral norm, i.e., the largest eigenvalue of this second derivative matrix, which can be written as
        \begin{equation}
            \label{eigenvalue_second}
            \varrho^w_{n,l,q,k}=\left\|2I + \frac{1}{\rho}\sum_{q^{\prime},k}\mathbf{G}^H\mathbf{h}^*_{q^{\prime},k}\mathbf{h}_{q^{\prime},k}^{H}\mathbf{G}\right\|_2,
        \end{equation}
        satisfies $\left\|\nabla f_w(\mathbf{w}^{(1)}_q) - \nabla f_w(\mathbf{w}^{(2)}_q)\right\| \le \varrho^w_{n,l,q,k}\left\|\mathbf{w}^{(1)}_q - \mathbf{w}^{(2)}_q\right\|, \forall \mathbf{w}^{(1)}_q,\mathbf{w}^{(2)}_q$. Taking the current iteration point as $\mathbf{w}^{t-1}_q$, the LGS function of $f_w(\mathbf{w}_q)$ is denoted as
        \begin{equation}
            \label{LGS_w}
            \begin{aligned}
                \mathrm{LGS}_{w} = & f_w(\mathbf{w}^{(t-1)}_q) + \text{Re}\left\{\nabla f_w(\mathbf{w}^{(t-1)}_q)^H(\mathbf{w}_q-\mathbf{w}^{(t-1)}_q)\right\} \\ 
                & + \frac{\varrho^w_{n,l,q,k}}{2}\left\|\mathbf{w}_q-\mathbf{w}^{(t-1)}_q\right\|^2,
            \end{aligned}
        \end{equation}
        where $t$ is the number of iterations. The explicit expression of the current gradient is
        \begin{equation}
            \label{gradientf_t1}
            \begin{aligned}
            & \nabla f_w(\mathbf{w}^{(t-1)}_q)= 2\mathbf{w}^{(t-1)}_q + \\
            & \frac{1}{\rho}\sum_{q^{\prime},k}\mathbf{G}^H\mathbf{h}^*_{q^{\prime},k}\left(\mathbf{h}_{q^{\prime},k}^{H}\mathbf{G}{\mathbf{w}_q^{(t-1)}} - \beta_{q^{\prime},q,k} + \rho \lambda^{\text{U}}_{q^{\prime},q,k}\right).
            \end{aligned}
        \end{equation}
        Then, we can get the explicit expression of LGS function (\ref{explicit_LGS_w}).
