                    & \mathrm{Re}\left\{\left[2\mathbf{w}^{(t-1)}_q + \frac{1}{\rho}\sum_{q^{\prime},k}\mathbf{G}^H\mathbf{h}^*_{q^{\prime},k}\left(\mathbf{h}_{q^{\prime},k}^{H}\mathbf{G}{\mathbf{w}_q^{(t-1)}} - \beta_{q^{\prime},q,k} + \rho \lambda^{\text{U}}_{q^{\prime},q,k}\right)(\mathbf{w}_q-\mathbf{w}^{(t-1)}_q)\right]^H\right\}.
