\subsection{Pinching Antenna Beamforming Problem}
\subsubsection{Pinching Antenna Position Optimization}
The key idea of AO and BCD is to alternatively fix one subset of variables, either the transmit beamforming or the positions of PAs, and optimize the objective function with respect to the other. With the transmit beamforming $\mathbf{w}_q$, we aim to optimize the position of PAs. The pinching antenna position optimization problen can be formulated as
\begin{subequations}
    \label{min_PAposition}
    \begin{align}
        \mathbf{P}_3: \quad & \min_{\mathbf{X}}\sum_{q=1}^{Q}\sum_{j=1}^{Q}\sum_{k=1}^{K}\left|\mathbf{h}_{q,k}^{H}\mathbf{G}\mathbf{w}_{j}-\beta_{q,k,j}\right|^{2},
        \label{PAposition}\\
        \mathrm{s.t.~} \quad & \text{(\ref{PA_minx})-(\ref{PA_x})}.
        \end{align}
\end{subequations}

Due to the strong coupling of $e^{-i{\kappa}\left|{\bm{\psi}}_{q,k}^{\text{U}}-{\bm{\psi}}_{n,l}^{\text{PA}}\right|}$ and $\frac{\eta}{\left|{\bm{\psi}}_{q,k}^{\text{U}}-{\bm{\psi}}_{n,l}^{\text{PA}}\right|}$, $\mathbf{h}^H_{q,k}$ is highly nonconvex, we utilize the auxiliary variables $d^{\text{PU}}_{n,l,q,k}$, $\theta_{n,l,q,k}$ and corresponding equationally constraints (\ref{distanceconstraint}) and
\begin{equation}
    \label{phaseconstraint}
    b^{\theta}_{n,l,q,k} \triangleq \theta_{n,l,q,k} - \kappa \left(d^{\text{PU}}_{n,l,q,k}+n_{\text{eff}}x_{n,l}\right).
\end{equation}

The AL function of $\mathbf{P}_3$ is denoted as
\begin{equation}
    \label{AL_I3}
    \begin{aligned}
        & \mathcal{L}_{\psi}\left(x_{n,l}\right) = \sum_{q,k,j}\left|\mathbf{h}_{q,k}^{H}\mathbf{G}\mathbf{w}_{j}-\beta_{q,k,j}\right|^{2} + \\
        & \frac{1}{2\rho}\sum_{n,l,q,k}\left(\left|b^{\text{U}}_{n,l,q,k}+\rho \lambda^{\text{U}}_{n,l,q,k}\right|^{2} + \left|b^{\theta}_{n,l,q,k}+\rho \lambda^{\theta}_{n,l,q,k}\right|^2\right),
    \end{aligned}
\end{equation}
where $\lambda^{\theta}_{n,l,q,k}$ is the dual variable corresponding to this constraint and $\rho$ is updated based on $\mathbf{P}_2$. Let $f_c(x_{n,l})=\sum_{q,k,j}\left|\mathbf{h}_{q,k}^{H}\mathbf{G}\mathbf{w}_{j}-\beta_{q,k,j}\right|^{2}$ represent the channel error term, which depends on $d^{\text{PU}}_{n,l,q,k}$. We can simplify the $d^{\text{PU}}_{n,l,q,k}=\sqrt{\left(x_{n,l}-x_{q,k}^{\text{U}}\right)^{2}+C_{q}}$ with the constant $C_q=\left(y_n-y^{\text{U}}_{q,k}\right)^{2}+{d^{\text{z}}_0}^2$ in each cluster. And the critical non-convex term has been replaced by
\begin{equation}
    \label{distanceconst_rep}
    \begin{aligned}
        & b^{\text{U}}_{n,l,q,k} \approx  d^{\text{PU}}_{n,l,q,k} - \\
        & \left[{d^{\text{PU}}_{n,l,q,k}}^{(t-1)} + \frac{\left(x^{(t-1)}_{n,l}-x_{q,k}^{\text{U}}\right)\left(x_{n,l}-x_{n,l}^{(t-1)}\right)}{{d^{\text{PU}}_{n,l,q,k}}^{(t-1)}}\right].
    \end{aligned}
\end{equation}

We can obtain the second derivative matrix of $f_c$ at iteration point $\mathbf{x}_n^{(t-1)}$ by Taylor expansion, that is $\nabla^2_{\psi}f_c = \sum_{q,k,j}2\text{Re}\left\{\nabla_{\mathbf{x}_n} \tilde{\beta}_{q,k,j}(\mathbf{x}_n^{(t-1)})\left[\nabla_{\mathbf{x}_n} \tilde{\beta}_{q,k,j}(\mathbf{x}_n^{(t-1)})\right]^H \right\}$. From (\ref{distanceconstraint}) and (\ref{phaseconstraint}), the derivatives of two corresponding non-convex terms are derived as $\nabla _{\psi}{b^{\text{U}}_{n,l,q,k}} = -\frac{(x_{n,l}-x^{\text{U}}_{q,k})}{d^{\text{PU}}_{n,l,q,k}(\mathbf{x}_n)}e_{n,l}$ and $\nabla _{\psi}{b^{\text{U}}_{n,l,q,k}} = -\kappa \frac{(x_{n,l}-x^{\text{U}}_{q,k})}{d^{\text{PU}}_{n,l,q,k}(\mathbf{x}_n)}e_{n,l}$, where $e_{n,l}$ is $NL$-dimensional unit vector.
And the second derivative matrices of them are expressed as $\nabla^2_{\psi}b^{\text{U}}_{n,l,q,k}=-\frac{C_q}{\left[d^{\text{PU}}_{n,l,q,k}(\mathbf{x}_n)\right]^3}e_{n,l}e_{n,l}^T$ and $\nabla^2_{\psi}b^{\theta}_{n,l,q,k}=-\kappa \frac{C_q}{\left[d^{\text{PU}}_{n,l,q,k}(\mathbf{x}_n)\right]^3}e_{n,l}e_{n,l}^T$, respectively.
Then, the second derivative of distance constraint in (\ref{AL_I3}) can be derived as 
% $\frac{1}{\rho}\sum_{n,l,q,k}\nabla_{\psi}b^{\text{U}}_{n,l,q,k}\nabla_{\psi}({b^{\text{U}}_{n,l,q,k}})^T+\frac{1}{\rho}\sum_{n,l,q,k}(b^{\text{U}}_{n,l,q,k}+\rho \lambda^{\text{U}}_{n,l,q,k})\nabla^2_{\psi}b^{\text{U}}_{n,l,q,k}$.
\begin{equation}
    \label{secondderivative_I3}
    \begin{aligned}
        \nabla^2_{\psi}{\mathcal{L}_{\psi}} = & \frac{1}{\rho}\sum_{n,l,q,k}\nabla_{\psi}b^{\text{U}}_{n,l,q,k}\nabla_{\psi}({b^{\text{U}}_{n,l,q,k}})^T \\
        & +\frac{1}{\rho}\sum_{n,l,q,k}(b^{\text{U}}_{n,l,q,k}+\rho \lambda^{\text{U}}_{n,l,q,k})\nabla^2_{\psi}b^{\text{U}}_{n,l,q,k},
    \end{aligned}
\end{equation}
and the second derivative of phase constraint in (\ref{AL_I3}) can be formulated as
% $\frac{1}{\rho}\sum_{n,l,q,k}\nabla_{\psi}b^{\theta}_{n,l,q,k}\nabla_{\psi}({b^{\theta}_{n,l,q,k}})^T+\frac{1}{\rho}\sum_{n,l,q,k}(b^{\theta}_{n,l,q,k}+\rho \lambda^{\theta}_{n,l,q,k})\nabla^2_{\psi}b^{\theta}_{n,l,q,k}$
\begin{equation}
    \label{secondderivative_theta}
    \begin{aligned}
        \nabla^2_{\psi}b^{\theta}_{n,l,q,k} =& \frac{1}{\rho}\sum_{n,l,q,k}\nabla_{\psi}b^{\theta}_{n,l,q,k}\nabla_{\psi}({b^{\theta}_{n,l,q,k}})^T\\
        & + \frac{1}{\rho}\sum_{n,l,q,k}(b^{\theta}_{n,l,q,k}+\rho \lambda^{\theta}_{n,l,q,k})\nabla^2_{\psi}b^{\theta}_{n,l,q,k}.
    \end{aligned}
\end{equation}

Thus, the entire second derivative matrix can be formulated as (\ref{secondorderLpsi}).
\begin{figure*}[ht]
