            & \frac{1}{\rho}\sum_{n,l,q,k}\left[\nabla_{\psi}b^{\text{U}}_{n,l,q,k}\nabla_{\psi}({b^{\text{U}}_{n,l,q,k}})^T+(b^{\text{U}}_{n,l,q,k}+\rho \lambda^{\text{U}}_{n,l,q,k})\nabla^2_{\psi}b^{\text{U}}_{n,l,q,k}\right] + \\
            & \frac{1}{\rho}\sum_{n,l,q,k}\left[\nabla_{\psi}b^{\theta}_{n,l,q,k}\nabla_{\psi}({b^{\theta}_{n,l,q,k}})^T+(b^{\theta}_{n,l,q,k}+\rho \lambda^{\theta}_{n,l,q,k})\nabla^2_{\psi}b^{\theta}_{n,l,q,k}\right].
