\subsubsection{Pinching Beamforming Optimization}
With the optimal PA location, the pinching beamforming vector can be optimizad by the same minimization problem $\mathbf{P}_3$. We introduce the auxiliary variable $\mathbf{u}_{q,k}=\mathbf{h}_{q,k}^H\mathbf{G} \in \mathbb{C}^{1\times N}$ to represent the pinching beamforming vector, where $\mathbf{u}_{q,k}=[\mathbf{u}_{1,q,k},\mathbf{u}_{2,q,k},\dots,\mathbf{u}_{N,q,k}] \in \mathbb{C}^{1\times N}$, $\mathbf{u}_{n,q,k}=[u_{n,1,q,k},u_{n,2,q,k},\dots,u_{n,L,q,k}]$, $u_{n,l,q,k}=\frac{\eta e^{-i\theta_{n,l,q,k}}}{\sqrt{L}d^{\text{PU}}_{n,l,q,k}}$ denotes the beamforming coefficient of UE $k$ in cluster $q$ radiated by the PA $l$. We stack the directional vectors of all UE $\left\{\mathbf{u}_{q,k}\right\}$ to form a matrix $\mathbf{U}\in \mathbb{C}^{K\times M}$. And $\beta_{q,k,j}=\mathbf{u}^H_{q,k}\mathbf{w}_j$ can be obtained. From $\mathbf{P}_3$ (\ref{PAposition}), the objective function can be transformed into 
\begin{equation}
    \label{min_u}
    \min_{\mathbf{u}_{q,k}}\left|\mathbf{u}_{q,k}\mathbf{W}-\bm{\beta}_{q,k}\right|^2,
\end{equation}
where $\mathbf{W}=[\mathbf{w}_1,\mathbf{w}_2,\dots,\mathbf{w}_Q] \in \mathbb{C}^{N \times Q}$ and $\bm{\beta}_{q,k}=[\beta_{q,k,1},\beta_{q,k,2},\dots,\beta_{q,k,Q}]^T \in \mathbb{C}^{Q \times 1}$. This (\ref{min_u}) is a complex least squares problem, it can be solved by the classical complex least squares method \cite{mark2007square}, the closed-form solution can be derived as
\begin{equation}
    \label{optimal_u}
    \mathbf{u}^*_{q,k}=(\mathbf{W}\mathbf{W}^H)^{-1}\mathbf{W}\bm{\beta}_{q,k},
\end{equation}
\begin{equation}
    \label{optimal_beta}
    \beta^*_{q,k,j}=\left[(\mathbf{W}\mathbf{W}^H)^{-1}\mathbf{W}\bm{\beta}_{q,k}\right]^H\mathbf{w}^*_q.
\end{equation}

\subsection{Power Allocation Optimization Problem}
In the NOMA assisted PASS framework, UEs within the same cluster decode each other through SIC, and there is the mutual interference between different clusters. This would result in less efficient power allocation. To ensure the minimum required rate of each UE, the power allocation optimization problem can be formulated as
%high-quality solution
\begin{subequations}
    \label{min_powerallocation}
    \begin{align}
        \mathbf{P}_4: \quad & \min_{\alpha_{q,k}, \beta_{q,k,j}}\sum_{q=1}^{Q}\sum_{j=1}^{Q}\sum_{k=1}^{K}\left|\mathbf{h}_{q,k}^{H}\mathbf{G}\mathbf{w}_{j}-\beta_{q,k,j}\right|^{2},
        \label{alpha}\\
        \mathrm{s.t.~} \quad & \text{(\ref{sumpower})-(\ref{PA_x}),(\ref{SINRconstraint1})},
        \end{align}
\end{subequations}
where (\ref{SINRconstraint1}) is nonlinear, recursive inequality constraint that expresses the minimum power allocation requirements. And these constraints can be transformed into
\begin{equation}
    \label{uniform_powercons}
    \begin{aligned}
        & \left|\beta_{q,k^{\prime},q}\right|^2\!\left(\!\alpha_{q,k}\!-\!{\mathrm{SINR}}_{q,k}^{\min}\!\sum_{i=k+1}^{K}\!\alpha_{m,i}\!\right)\! \ge \! \\
        & {\mathrm{SINR}}_{q,k}^{\min}\!\left(\sum_{j=1,j\neq q}^Q\!\left|\beta_{q,k^{\prime},j}\right|^2\!+\!\sigma^2\!\right),
    \end{aligned}
\end{equation}
where $\left|\beta_{q,k^{\prime},q}\right|^2$ and $\left|\beta_{q,k^{\prime},j}\right|^2$ represent channel projection in the cluster $q$ and inter-cluster interference, respectively. It can be obtained 
\begin{equation}
    \label{alpha_lowbound}
    \begin{aligned}
        \alpha_{q,k} \ge & \frac{{\mathrm{SINR}}_{q,k}^{\min}\left(\sum_{j=1,j\neq q}^Q\left|\beta_{q,k^{\prime},j}\right|^2+\sigma^2\right)}{\left|\beta_{q,k^{\prime},q}\right|^2} \\
        & + {\mathrm{SINR}}_{q,k}^{\min}\sum_{i=k+1}^{K}\alpha_{m,i}.
    \end{aligned}
\end{equation}

Let $a_k \triangleq \frac{{\mathrm{SINR}}_{q,k}^{\min}\left(\sum_{j=1,j\neq q}^Q\left|\beta_{q,k^{\prime},j}\right|^2+\sigma^2\right)}{\left|\beta_{q,k^{\prime},q}\right|^2}$. Then, the recursive constraint becomes $\alpha_{q,k} \ge a_{q,k} + {\mathrm{SINR}}_{q,k}^{\min}\sum_{i=k+1}^{K}\alpha_{m,i}$. We derive the closed-form solution utilizing a backward iterative approach of dynamic programming
\begin{equation}
    \label{non-normalizedform}
    \tilde{\alpha}_{q,k} = \sum_{i=k}^{K}(\prod_{p=k}^{i-1}c_p)a_{q,i},
\end{equation}
where $\prod_{p=k}^{i-1}c_p=1$. The normalized closed-form power allocation can be derived as
\begin{equation}
    \label{normalizedform_alpha}
    \alpha^*_{q,k}=\frac{\sum_{i=k}^{K}(\prod_{p=k}^{i-1}c_p)a_{q,i}}{\sum_{v=1}^{K}\sum_{i=v}^{K}(\prod_{p=v}^{i-1}c_p)a_{q,i}}.
\end{equation}

\begin{algorithm}[!ht]
    \caption{Iterative MM-PDD Algorithm for Joint Transmit And Pinching Beamforming And Power Allocation Optimization}
    \label{MMPDD}
    \begin{algorithmic}[1]
        \REQUIRE $(x^{\text{U}}_{n,l},y^{\text{U}}_{n,l})$, $\kappa$, ${\mathrm{SINR}}_{q,k}^{\min}$. 
    \STATE \textbf{Initialize:} $\mathbf{w}_q^{(0)}$, $\theta_{n,l,q,k}^{(0)}$, $\beta_{q,k,j}^{(0)}$, $\alpha_{q,k}^{(0)}$, $\mathbf{u}_{q,k}^{(0)}$, $\rho > 0$, $t \gets 0$
    \WHILE {$t < T$}
      \STATE \hspace{-2mm} {\textbf{STEP A: Transmit Beamforming Optimization}}

      \FOR{each cluster $q = 1$ to $Q$}
        \STATE Solve 
          $\displaystyle \mathbf{P}_2$ (\ref{AL})
        \STATE Update
          $\mathbf{w}_q^{(t+1)}$ as Closed-Form Solution by LGS
      \ENDFOR

      \STATE \hspace{-2mm} {\textbf{STEP B: Pinching Beamforming Optimization}}

      \FOR{each PA with $x_{n,l}$ and UE $k$ in cluster $q$}
      \STATE Solve: $\displaystyle \mathbf{P}_3$ (\Ref{PAposition})
        \STATE Update phase and distance
          $\theta_{n,l,q,k}^{(t+1)}, d_{n,l,q,k}^{\text{PU}(t+1)}$ via Constructing Local Quadratic Upper Bounds by LGS
        \STATE Update position
          $\mathbf{x}_n, x_{n,l}^{(t+1)} $ by Interior Point Method
      \STATE Solve
          $\displaystyle$ (\ref{min_u})
        \STATE Update
          $\mathbf{u}_{q,k}^{(t+1)}, \beta^{(t+1)}_{q,k,j}$ as Closed-Form Solution by Complex Least Squares Method
      \ENDFOR

      \STATE \hspace{-2mm} {\textbf{STEP C: Power Allocation Optimization}}

      \FOR{each UE $k$}
        \FOR{each cluster $j$}
          \STATE Update
            $\beta_{q,k,j}^{(t+1)}$ by $\mathbf{h}_{q,k}^H G \mathbf{w}_j^{(t+1)}$
        \ENDFOR

        \STATE Solve
          $\displaystyle \mathbf{P}_4$ (\ref{alpha}) subject to (\ref{uniform_powercons})
          \STATE Update
            $\alpha_{q,k}^{(t+1)}$ as Closed-Form Solution by Backward Iterative Approach
      \ENDFOR

      \STATE $t \gets t+1$
    \ENDWHILE
    \ENSURE $\mathbf{w}_q$, $\mathbf{x}_n$, $d^{\text{PU}}_{n,l,q,k}$, $\theta_{n,l,q,k}$, $\mathbf{u}_{q,k}$, $\beta_{q,k,j}$, $\alpha_{q,k}$
    \end{algorithmic}
\end{algorithm}


Based on the above methods, the joint transmit and pinching beamforming and power allocation optimization algorithm in the NOMA assisted PASS is shown in Algorithm \ref{MMPDD}.

