In this work, we propose a linearly implicit structure-preserving method for semilinear Hamiltonian systems with polynomial nonlinearities, by combining Kahan’s method \cite{celledoni2012geometric} with exponential integrators. Kahan’s method is employed  due to several favorable properties: i) it is \emph{linearly implicit}, requiring only the solution of a single linear system per time step, which improves computational efficiency compared to fully implicit methods; ii) it is \emph{symmetric}, a key property for ensuring stable long-term integration; and iii) it preserves a  \emph{modified energy and measure}, geometric characteristics that are also satisfied  by the exact flow of the original system. The proposed method inherits all advantageous properties of Kahan's method except for the exact conservation of a modified energy and measure. However, we show that the energy error remains bounded and exhibits oscillatory behavior over time. Moreover, we derive an explicit analytical expression for the energy error, offering insights into the method’s long-term energy behavior. Through numerical experiments, we demonstrate that the proposed method achieves superior computational efficiency compared to both the fully implicit exponential AVF method and the linearly implicit method based on the polarized discrete gradient. Additionally, we provide a rigorous proof that the proposed method achieves second-order convergence.



The remainder of this paper is organized as follows. In Section \ref{Method}, we introduce the proposed linearly implicit  structure-preserving exponential integrator and discuss its key properties, including symmetry, energy preservation and convergence. In Section \ref{Experiment}, we present numerical experiments to demonstrate the stability, computational efficiency, and long-term behavior of the proposed method using different types of differential equations. Finally, conclusions and potential directions for future research are discussed in the last section.











\section{The new linearly implicit  structure-preserving symmetric method}\label{Method}

Before proposing the new exponential integrator, we will introduce Kahan's method. For a  Hamiltonian system with a  cubic Hamiltonian, Kahan's method has the form 
\begin{equation*}
	x_{n+1}= Q(-\frac{1}{2}\nabla H(x_{n})+2\nabla H(\frac{x_{n}+x_{n+1}}{2})-\frac{1}{2}\nabla H(x_{n+1})),
\end{equation*}
and it is shown to preserve a modified energy as well as a measure in \cite{celledoni2012geometric}. In particular, if the energy function is homogeneous, the modified energy can be written as $\bar{H}=C(x_n,x_n,x_{n+1})$, where $C$ is a symmetric trilinear form defined by the Hessian of the energy function $H$
\begin{equation*}
	C(x,y,z) = \frac{1}{6}x^\mathsf{T} H^{\prime\prime}(y)z.
\end{equation*}
When $H$ is nonhomogeneous, we can always add an extra auxiliary variable to transfer the problem to a homogeneous setting.
In addition, Kahan's method is linearly implicit. These properties guarantee the superior numerical behavior  of Kahan's method during long-time integration \cite{eidnes2019linearly}.

For a semilinear system \eqref{semilinear ODE}, we consider the following variation of constants formula on interval $[t_{0},t_{0}+h]$  
\begin{equation}\label{vcformula}
	x(t_{0}+h)=e^{hA} x(t_{0})+h\int_{0}^{1} e^{(1-\tau)hA}f(x(t_{0}+\tau h))\mathrm{d} \tau.
\end{equation}
The key idea of constructing exponential integrator is to integrate the linear part of equation \eqref{vcformula} exactly meanwhile finding an approximation to the integration on the right-hand side. For example, the exponential Euler method is obtained by approximating the nonlinear term by $f(x(t_0))$ \cite{MR2652783}, thereby having the form
\begin{equation*}\label{Eeuler}
	x_{n+1}=e^{hA} x_{n} +h \phi(hA)f(x_{n}),
\end{equation*}
where $\phi(z):= \frac{e^{z}-1}{z}$;  the exponential averaged vector field method is obtained by approximating the nonlinear term by the discrete gradient \cite{Wuxinyuan2016}, possessing the form
\begin{equation*}\label{EAVF}
	x_{n+1}=e^{hA} x_{n} +h \phi(hA)\int_0^1f(\xi x_{n}+(1-\xi)x_{n+1})d\xi.
\end{equation*}


In this work, we approximate the nonlinear term using Kahan’s method, leading to the new linearly implicit exponential integrator suitable for solving semilinear systems \eqref{semilinear ODE}:
\begin{equation}\label{EKahan scheme}
	x_{n+1}=e^{hA} x_{n} +h \phi(hA)(-\frac{1}{2}f(x_{n})+2f(\frac{x_{n}+x_{n+1}}{2})-\frac{1}{2}f(x_{n+1})).
\end{equation}
We denote this newly derived scheme as the EKahan scheme,  and its properties are described in detail below.

\begin{lemma}\label{EKahan symmetric Lemma}
	The EKahan scheme \eqref{EKahan scheme} is symmetric.
\end{lemma}
\begin{proof}
	By exchanging $x_{n} \leftrightarrow x_{n+1}$ and replacing $h$ with $-h$ in \eqref{EKahan scheme}, we obtain
	\begin{equation}\label{symmeiric_EKahan scheme1}
		x_{n}=e^{-Ah} x_{n+1} -h \phi(-Ah)(-\frac{1}{2}f(x_{n+1})+2f(\frac{x_{n+1}+x_{n}}{2})-\frac{1}{2}f(x_{n})).
	\end{equation}
	Multiplying  both sides of \eqref{symmeiric_EKahan scheme1} by $e^{hA}$, we get
	\begin{equation}\label{symmeiric_EKahan scheme2}
		e^{hA}x_{n}=x_{n+1}-he^{hA} \phi(-Ah)(-\frac{1}{2}f(x_{n+1})+2f(\frac{x_{n+1}+x_{n}}{2})-\frac{1}{2}f(x_{n})).
	\end{equation}
	Using the identiy $\phi(-V)=e^{-V}\phi(V)$ for any matrix $V$, we can rewrite the above equation \eqref{symmeiric_EKahan scheme2} as 
	\begin{equation*}
		e^{hA}x_{n}=x_{n+1}-h\phi(hA)(-\frac{1}{2}f(x_{n+1})+2f(\frac{x_{n+1}+x_{n}}{2})-\frac{1}{2}f(x_{n})).
	\end{equation*}
	This equation is equivalent to \eqref{EKahan scheme}, confirming  that the EKahan scheme \eqref{EKahan scheme} is symmetric.
\end{proof}

\begin{lemma}\label{EKahan order Lemma}
	The EKahan scheme \eqref{EKahan scheme} is second-order. 
\end{lemma}
\begin{proof}
	By applying Taylor expansion to $f(\frac{x_{n}+x_{n+1}}{2})$ and $f(x_{n+1})$ at the point $x_n$ and using the fact that $f$ is quadratic, we can obtain 
	\begin{equation*}
		%       \begin{split}
			-\frac{1}{2}f(x_{n})+2f(\frac{x_{n}+x_{n+1}}{2})-\frac{1}{2}f(x_{n+1})=f(x_{n})+\frac{1}{2}f^\prime(x_{n})(x_{n+1}-x_{n}).
			% \end{split}
	\end{equation*}
	Therefore, EKahan scheme \eqref{EKahan scheme} can be rewritten as
	\begin{align}\label{scehme:reEKahan}
		x_{n+1}&=e^{hA}x_{n}+h\phi(hA)[f(x_{n})+\frac{1}{2}f^\prime(x_{n})(x_{n+1}-x_{n})].
	\end{align}
	Since the matrix exponential satisfies $e^{hA}=I+h\phi(hA)A$, we rewrite equation \eqref{scehme:reEKahan}  as
	\begin{align}\label{scehme:reEKahan2}
		x_{n+1}&=(I+h\phi(hA)A)x_{n}+h\phi(hA)[f(x_{n})+\frac{1}{2}f^\prime(x_{n})(x_{n+1}-x_{n})]\nonumber\\  &=x_{n}+h\phi(hA)g(x_{n})+\frac{h}{2}\phi(hA)f^{\prime}(x_{n})(x_{n+1}-x_{n}),
	\end{align}
	where the function $g(x)$ is the right-hand side of the semilinear equation \eqref{semilinear ODE}, i.e., $g(x):=Ax+f(x)$.
	Supposing the matrix $I-\frac{h}{2}\phi(hA)f^{\prime}(x_{n})$ is invertible, solving for $x_{n+1}-x_n$ from equation \eqref{scehme:reEKahan2} gives 
	\begin{equation*}\label{lim1}
		x_{n+1}-x_{n}=h(I-\frac{h}{2}\phi(hA)f^{\prime}(x_{n}))^{-1}\phi(hA)g(x_{n}).
	\end{equation*}
	By $L'H\hat{o}pital's \; rule$,  we have $\lim\limits_{z \rightarrow 0} \frac{e^{z}-1}{z}=1$, so $\lim\limits_{h \rightarrow 0}\phi(hA)=I$ and 
	\begin{equation*}\label{lim1}
		\lim\limits_{h \rightarrow 0}(I-\frac{h}{2}\phi(hA)f^{\prime}(x_{n}))^{-1}\phi(hA)g(x_{n})=g(x_{n}).
	\end{equation*}
	Therefore, we have the following truncation for the EKahan scheme \eqref{scehme:reEKahan} 
	\begin{align}\label{EKahan-taylor}
		x_{n+1}&=x_{n}+hg(x_{n})+O(h^2).
	\end{align}
	By Taylor expansion, the exact solution of the semilinear Hamiltonian system \eqref{semilinear ODE} satisfies
	\begin{align}\label{Exsol-semilinHam}
		x(t_{n+1})= x(t_{n})+hg(x(t_{n}))+\frac{h^2}{2}(A+f^{\prime}(x(t_{n})))g(x(t_{n}))+O(h^3).
	\end{align}
	Supposing $x_n$ is exactly solved and  subtracting equation  \eqref{Exsol-semilinHam} from equation \eqref{EKahan-taylor}, we get
	\begin{equation*}
		x_{n+1} - x(t_{n+1})= O(h^2).
	\end{equation*}
	%The last equation follows from the fact that $\lim\limits_{h \rightarrow 0}(\phi(hA)-I)=0$.
	Moreover, EKahan scheme \eqref{EKahan scheme} is symmetric from Lemma \ref{EKahan symmetric Lemma}, confirming that this method is  at least second-order. 
	%   combining \eqref{scehme:reEKahan} and \eqref{lim1}, we can indicate that $$x_{n+1}-x_{n}=(I-\frac{h}{2}\phi(hA)f^{\prime}(x_{n}))^{-1}\phi(hA)g(x_{n})h \leq Mh$$ for some $M \in \mathbb{R}$.
	%    Since EKahan scheme \eqref{EKahan scheme} is symmetric from Lemma \ref{EKahan symmetric Lemma}, it is  at least a second-order scheme.
\end{proof}


\begin{theorem}
	Let $X$ be a Banach space with norm $\Vert \cdot \Vert $. We assume that  $A$ is a linear unbounded differential operator on $X$; its eigenvalues have large negative real parts or are purely imaginary with substantial magnitude, and it is the infinitesimal generator of a strongly continuous semigroup $e^{tA}$ on $X$. We also assume that $f$ satisfies Lipschitz condition, i.e. there exists a constant number $L$ s.t.
	\begin{equation*}
		\Vert f(x_{2})-f(x_{1}) \Vert \leq L \Vert x_{2}-x_{1} \Vert.
	\end{equation*}
	Then, the error bound
	\begin{equation*}
		\Vert x(t_{n})-x_{n} \Vert \leq e^{k_{2}T} (k_{1}\Vert x(t_{0})-x_{0} \Vert+k_{3} h^{2})
	\end{equation*}
	holds in $0 \leq nh \leq T$ for constant $k_{1},\;k_{2},\;k_{3}$.
\end{theorem}


\begin{proof}
	The assumptions about the operator $A$ guarantee the boundness of $\Vert \phi(hA) \Vert$  and $\Vert e^{jhA} \Vert$, $j=1,2,\dots$, and we denote the bound by $M$; see Lemma 2.4 from \cite{MR2652783}. Since EKahan scheme \eqref{EKahan scheme} is  second-order, we get the following truncation when inserting the exact solutions $x(t_{n})$ and $x(t_{n+1})$ to the numerical scheme: 
	\begin{equation}\label{eq:exact scheme}
		\begin{split}
			x(t_{n+1})=&e^{hA}x(t_{n})+h \phi(hA) [-\frac{1}{2}f(x(t_{n}))-\frac{1}{2}f(x(t_{n+1}))\\
			&+2f(\frac{x(t_{n})+x(t_{n+1})}{2})]+O(h^{3}).
		\end{split}
	\end{equation}
	Denote the numerical error terms by $\varepsilon_{n}=x(t_{n})-x_{n}$ and 
	\begin{align*}
		\delta_{n+1,n}=&-\frac{1}{2}f(x(t_{n}))+2f(\frac{x(t_{n})+x(t_{n+1})}{2})-\frac{1}{2}f(x(t_{n+1}))\\
		&-\big(-\frac{1}{2}f(x_{n})+2f(\frac{x_{n}+x_{n+1}}{2})-\frac{1}{2}f(x_{n+1})\big).
	\end{align*}
	Subtracting equation \eqref{EKahan scheme} from equation\eqref{eq:exact scheme}, we get the following error recursion equation
	\begin{equation*}\label{error recursion}
		\varepsilon_{n+1}=e^{hA}\varepsilon_{n}+h\phi(hA)\delta_{n+1,n}+O(h^{3}).
	\end{equation*}
	This recursion equation gives
	\begin{equation}\label{eq4}
		\varepsilon_{n}=e^{nAh}\varepsilon_{0}+\sum\limits_{j=0}^{n-1} e^{jAh}h\phi(hA)\delta_{n-j,n-j-1}+\sum\limits_{j=0}^{n-1} e^{jAh} O(h^{3}).
	\end{equation}
	Since $f$ satisfies $Lipschitz \; condition$, we have
	\begin{equation*}
		\Vert \delta_{n-j,n-j-1} \Vert \leq \frac{3}{2}L \Vert \varepsilon_{n-j} \Vert +\frac{3}{2} L \Vert \varepsilon_{n-j-1} \Vert.
	\end{equation*}
	Then we have 
	\begin{equation}\label{eq5}
		\Vert \sum\limits_{j=0}^{n-1} e^{jAh}h\phi(hA)\delta_{n-j,n-j-1} \Vert \leq \frac{3}{2}hLM \Vert \varepsilon_{n} \Vert +3hLM^2  \sum\limits_{j=0}^{n-1} \Vert \varepsilon_{j} \Vert. 
	\end{equation}
	Combing \eqref{eq4} and \eqref{eq5}, we obtain
	\begin{equation}\label{eq14}
		\Vert \varepsilon_{n} \Vert \leq \Vert e^{TA} \Vert \Vert \varepsilon_{0} \Vert + \frac{3}{2}hLM\Vert \varepsilon_{n} \Vert +3hLM^2  \sum\limits_{j=0}^{n-1} \Vert \varepsilon_{j} \Vert+n M O(h^{3}).
	\end{equation}
	For small $h$ such that $1-\frac{3}{2}hLM$ is positive, suppose there exists a positive real number $k_{3}$ satisfying $\frac{nMO(h^{3})}{1-\frac{3}{2}hLM}\leq k_{3} h^{2}$. Denote by $k_{1}=\frac{\Vert e^{TA} \Vert \Vert \varepsilon_{0} \Vert}{1-\frac{3}{2}hLM}$ and $k_{2}= \frac{3LM^2}{1-\frac{3}{2}hLM}$. Then we can obtain the following estimation for the numerical error  $\varepsilon_{n}$ from the above relation \eqref{eq14}:
	\begin{align*}
		\Vert  \varepsilon_{n} \Vert &\leq k_{1} \Vert \varepsilon_{0} \Vert + k_{2}h \sum\limits_{j=0}^{n-1} \Vert \varepsilon_{j} \Vert+ k_{3} h^{2}\\
		&\leq e^{nk_{2}h}(k_{1}\Vert \varepsilon_{0} \Vert+k_{3} h^{2})\\
		&= e^{k_{2}T} (k_{1}\Vert \varepsilon_{0} \Vert+k_{3} h^{2}).
	\end{align*}
	The last inequality follows from the Gronwall's inequality.
\end{proof}
%From this theorem, we claim that if the initial value has no error, i,e, $x_0=x(t_0)$ and $\varepsilon_{0}=0$, Ekahan method is convergent with order $O(h^2)$. 

Before presenting the second main theorem about the energy behaviour of EKahan method, we give the following lemma showing a property shared by a general exponential integrator based on the variational constant formula applied to the semilinear system \eqref{semilinear HODE}. The proof of this lemma is inspired by Theorem 1 in \cite{Wuxinyuan2016}.
\begin{lemma}\label{lemma-energy}
	For the semilinear system \eqref{semilinear HODE}, any exponential integrator with the form 
	\begin{align*}
		x_{n+1}=e^{hA} x_{n} +h \phi(hA)Q\hat{\nabla}U(x_{n},x_{n+1}),
	\end{align*}
	satisfies the following  equation
	\begin{align*}
		\frac{1}{2}x_{n+1}^\mathsf{T} Mx_{n+1}-\frac{1}{2}x_{n}^\mathsf{T} Mx_{n}+(x_{n+1}-x_{n})^T\hat{\nabla}U(x_{n+1},x_{n})=0,
	\end{align*}
	where $A=QM$, and $\hat{\nabla}U(x_{n},x_{n+1})$ is a discretization of the true gradient $\nabla U(x_{n})$.
\end{lemma}
\begin{proof}
	Assuming that the matrix $M$ is not singular and denoting by $V=hA=hQM$ and $\hat{\nabla}U=M\breve{\nabla}U$, we get the following equation after replacing $x_{n+1}$ by $e^{hA} x_{n} +h \phi(hA)Q\hat{\nabla}U(x_{n},x_{n+1})$:

	\begin{equation*}
		\begin{split}
			&\frac{1}{2} x_{n+1}^\mathsf{T} M x_{n+1} -\frac{1}{2} {x_{n}}^{\mathsf{T}} M x_{n}+(x_{n+1} - x_n)^\mathsf{T} \hat{\nabla}U(x_n, x_{n+1})\\
			%&= \frac{1}{2} \left({x_{n}}^{T} \exp(V)^T + h \bar{\nabla} U^T Q^T \varphi(V)^T \right) M \left(\exp(V) x_{n} + h \varphi(V) Q \bar{\nabla} U\right)\\
			&=\frac{1}{2} {x_{n}}^{\mathsf{T}}({e^{V}}^{\mathsf{T}} M e^{V}-M)x_{n} + h {x_{n}}^{\mathsf{T}} {e^{V}}^{\mathsf{T}} M \phi(V) Q \hat{\nabla} U\\
			&+\frac{1}{2}h^2 \hat{\nabla}U^\mathsf{T} Q^\mathsf{T} \phi(V)^\mathsf{T} M \phi(V) Q\hat{\nabla}U\\
			&+{x_{n}}^\mathsf{T} ({e^{V}}^{\mathsf{T}}- I) \hat{\nabla}U + {\hat{\nabla}U}^\mathsf{T} Q^\mathsf{T} \phi(V)^\mathsf{T}  \hat{\nabla}U\\
			&= \frac{1}{2} {x_{n}}^{\mathsf{T}} ({e^{V}}^{\mathsf{T}} M e^{V}-M)x_{n} 
			+ {x_{n}}^{\mathsf{T}}{e^{V}}^{\mathsf{T}} M (e^{V} - I) \breve{\nabla}U\\
			&+\frac{1}{2}\breve{\nabla}U^\mathsf{T} (e^{V} - I)^\mathsf{T} M (e^{V} - I) \breve{\nabla}U\\
			&+{x_{n}}^\mathsf{T} ({e^{V}}^{\mathsf{T}} M - M)\breve{\nabla}U + {\breve{\nabla}U}^\mathsf{T} ({e^{V}}^{\mathsf{T}} M - M) \breve{\nabla}U\\
			%&= \frac{1}{2} {x_{n}}^{\mathsf{T}} (\exp(V)^\mathsf{T} M \exp(V)-M)x_{n} + {x_{n}}^{\mathsf{T}} \exp(V)^\mathsf{T} M (\exp(V) - I) \breve{\nabla}U\\
			%&+\frac{1}{2}(\breve{\nabla}U)^\mathsf{T} (\exp(V) - I)^\mathsf{T} M (\exp(V) - I) \breve{\nabla}U\\
			%&+{x_{n}}^\mathsf{T} (\exp(V)^\mathsf{T} M - M)\breve{\nabla}U + {\breve{\nabla}U}^\mathsf{T} (\exp(V)^\mathsf{T} M - M) \breve{\nabla}U\\
			&=\frac{1}{2}(x_{n}+\breve{\nabla}U)^\mathsf{T}({e^{V}}^{\mathsf{T}} M e^{V}-M)(x_{n}+\breve{\nabla}U)+\frac{1}{2}\breve{\nabla}U^\mathsf{T}({e^{V}}^{\mathsf{T}} M - Me^{V})\breve{\nabla}U\\
			&=0.
		\end{split}
	\end{equation*}

	The last equation follows from the fact that ${e^{V}}^{\mathsf{T}} M e^{V}-M$ and ${e^{V}}^{\mathsf{T}} M - M e^{V}$ are skew symmetric.

	If $M$ is singular, we follow the idea in \cite{Wuxinyuan2016}, introducing a series of symmetric and nonsingular matrices $M_\delta$ which converges to $M$ when $\delta$ approaches zero to complete the proof.
\end{proof}
The discretized gradient $\hat{\nabla}U(x_{n},x_{n+1})$ can include the discrete gradient obtained by AVF, the discretization given by Kahan's method as well as a more general discretization by Runge-Kutta method.  We denote the discretized gradient obtained via Kahan's method by $\nabla U_{\text{K}}$, which can be written as 
\begin{align*}
	\nabla U_{\text{K}}=-\frac{1}{2}\nabla U(x_n)+2\nabla U(\frac{x_n+x_{n+1}}{2})-\frac{1}{2}\nabla U(x_{n+1}).\\
\end{align*}

\begin{theorem}\label{theorem-energy}
	For a Hamiltonian system \eqref{semilinear HODE} with a homogeneous cubic function $U(x)$, EKahan scheme \eqref{EKahan scheme} nearly preserves the exact energy and  has the following error estimation
	\begin{align*}
		H_{n+1}-H_{n}&=U(x_{n+1}-x_{n}),\\
	\end{align*}
	where $H_{n}=\frac{1}{2}x_{n}^\mathsf{T} Mx_{n}+U(x_{n})$ is the discrete energy at $t=t_n$.
\end{theorem}
\begin{proof}
	Based on Lemma \ref{lemma-energy}, we have
	\begin{equation}\label{er-EH-Kahan}
		\begin{split}
			H_{n+1}-H_{n}&=\frac{1}{2}x_{n+1}^{\mathsf{T}}Mx_{n+1}-\frac{1}{2}x_{n}^{\mathsf{T}}Mx_{n}+U(x_{n+1})-U(x_{n})\\
			&=U(x_{n+1})-U(x_{n})-(x_{n+1}-x_{n})^{\mathsf{T}}\nabla_{\text{K}}U(x_{n},x_{n+1}).
		\end{split}
	\end{equation}
	For a homogeneous cubic function $U(x)$, we have  $U(x)=\frac{1}{6}x^TU^{\prime\prime}(x)x$ and $\nabla U_{\text{K}}=\frac{U^{\prime\prime}(x_{n+1})x_{n}}{2}$.

	Then, the above energy error \eqref{er-EH-Kahan} can be reformulated as 
	\begin{align*}
		&H_{n+1}-H_{n}\\
		&=\frac{1}{6}{x_{n+1}}^\mathsf{T}U^{\prime\prime}(x_{n+1})x_{n+1}-\frac{1}{6}{x_{n}}^\mathsf{T}U^{\prime\prime}(x_{n})x_{n}\\
		&-\frac{1}{2}{x_{n+1}}^\mathsf{T}U^{\prime\prime}(x_{n+1})x_{n}+\frac{1}{2}{x_{n}}^\mathsf{T}U^{\prime\prime}(x_{n+1})x_{n}\\
		&=\frac{1}{6}{x_{n+1}}^\mathsf{T}U^{\prime\prime}(x_{n+1})x_{n+1}-\frac{1}{6}{x_{n+1}}^\mathsf{T}U^{\prime\prime}(x_{n+1})x_{n}\\
		&+\frac{1}{6}{x_{n}}^\mathsf{T}U^{\prime\prime}(x_{n+1})x_{n}-\frac{1}{6}{x_{n}}^\mathsf{T}U^{\prime\prime}(x_{n})x_{n}\\
		&-\frac{1}{3}{x_{n+1}}^\mathsf{T}U^{\prime\prime}(x_{n+1})x_{n}+\frac{1}{3}{x_{n}}^\mathsf{T}U^{\prime\prime}(x_{n+1})x_{n}\\
		&=\frac{1}{6}(x_{n+1}-x_{n})^\mathsf{T}(U^{\prime\prime}(x_{n+1})x_{n+1}+U^{\prime\prime}(x_{n})x_{n}-2U^{\prime\prime}(x_{n+1})x_{n})\\
		&=\frac{1}{6}(x_{n+1}-x_{n})^\mathsf{T} U^{\prime\prime}(x_{n+1}-x_{n})(x_{n+1}-x_{n})\\
		&=U(x_{n+1}-x_{n}).
	\end{align*} 
\end{proof}

