In this section, we apply the proposed EKahan scheme to  three systems including an ODE and two PDEs with high dimension and high-order nonlinear functions. We compare EKahan scheme  with the state-of-the-art symmetric structure-preserving methods including the following three schemes:
\begin{itemize}
\item Kahan: the Kahan method  presented in \cite{celledoni2012geometric};
\item EAVF: the exponential Averaged Vector Field method presented in \cite{Wuxinyuan2016};
\item LIEEP: the linearly implicit energy-preserving exponential scheme illustrated in \cite{li2022new}.
\end{itemize}
We define the global error by
\begin{equation*}
\mathcal{E}_G = \max\limits_{n \geq 0}\Vert y_{n}-y(t_{n})\Vert,
\end{equation*}
and  the energy error at time $t_n=t_0+nh$ by 
\begin{equation*}
\mathcal{E}_H(n) = \lvert H_{n}-H(y(t_n))\rvert,
\end{equation*}
where  $y(t_{n})$ is the reference exact solution and $H_{n}$ is the discrete energy defined in Theorem \ref{theorem-energy}. The reference exact solution is obtained using the 6-order continuous Runge-Kutta (CRK) method \cite{hairer2010energy} with the form
\begin{equation*}
\left\{\begin{array}{l}
y_{n+1 / 3}=y_n+h Q \int_0^1\left(\frac{37}{27}-\frac{32}{9} \sigma+\frac{20}{9} \sigma^2\right) \nabla H\left(Y_\sigma\right) \mathrm{d} \sigma \\
y_{n+2 / 3}=y_n+h Q \int_0^1\left(\frac{26}{27}+\frac{8}{9} \sigma-\frac{20}{9} \sigma^2\right) \nabla H\left(Y_\sigma\right) \mathrm{d} \sigma \\
y_{n+1}=y_n+h Q \int_0^1 \nabla H\left(Y_\sigma\right) \mathrm{d} \sigma
\end{array}\right.,
\end{equation*}
where
\begin{align*}
Y_\sigma= & -\frac{(3 \sigma - 1)(3 \sigma-2)(\sigma-1)}{2} y_n+\frac{3 \sigma(3 \sigma-2)(3 \sigma-3)}{2} y_{n+1 / 3} \\
& -\frac{3 \sigma(3 \sigma-1)(3 \sigma-3)}{2} y_{n+2 / 3}+\frac{\sigma(3 \sigma-1)(3 \sigma-2)}{2} y_{n+1},
\end{align*}
and the integrals are evaluated exactly by the 5-point GL quadrature.   For both LIEEP method and EKahan scheme \eqref{EKahan scheme-high-order}, multiple initial starting points are required. These starting values are obtained using the aforementioned reference exact solution. All numerical experiments were conducted using MATLAB (R2022b) on a 2020 MacBook Air equipped with an Apple M1 processor and 16 GB of unified memory.

\paragraph{\textbf{Henon-Heiles system}}
The Henon-Heiles model \cite{MR1128990} has been used to describe stellar motion in a long time course of gravitational potential energy tracking of galaxies with columnar symmetry. It has the following form

\begin{align*}\label{HHH}
\left\{\begin{array}{ll}
{\ddot q_1 =-q_1 -2 Dq_1 q_2},  \\ 
{\ddot q_{2}=- q_2 -D q_1^{2}+C q_2^{2}},  \\ 
\end{array}\right.
\end{align*}
%where Hamiltonian
%$H=\frac{1}{2}(\dot q_1^{2}+\dot q_2^2+q_1^2 +q_2^2)+Dq_1^2q_2 -\frac{C}{3}q_2^{3}.$
where the independent variable $t \in [0,T]$. We consider $C=1$ and $D=1$. By introducing the momentum variables $\dot{q}_1 =p_1 ,\; \dot{q}_2 =p_2$, the system can be rewritten in the Hamiltonian form 
\begin{equation}\label{hh1}
%\begin{split}
\dot{y}=Q \nabla H, \quad
H(y) = \frac{1}{2} y^{\mathsf{T}} M y + U(y),
%\end{split}
\end{equation}
where \( y = (q_1, q_2, p_1, p_2)^{\mathsf{T}} \), \( Q \) is the canonical skew-symmetric matrix, \( M = I_4 \) denotes the \( 4 \times 4 \) identity matrix, and the potential function is defined as \( U(y) = q_1^2 q_2 - \frac{1}{3} q_2^3 \). 


%where $y=(q_1,q_2,p_1,p_2)^{\mathsf{T}}$, $J$ denotes the canonical skew-symmetric matrix, and the Hamiltonian function is given by
%$H =\frac{1}{2}y^{\mathsf{T}}My+U(y)$ is a semilinear function  where $M=I_{4}, \quad U(y)=q_{1}^{2}q_{2}-\frac{1}{3}q_{2}^{3}$.



Applying the EKahan scheme to equation \eqref{hh1} gives

\begin{align*}
y_{n+1}=e^{hQM}y_n-h\phi(hQM)Q[\frac{1}{2}\nabla{U}(y_n)-2\nabla U(\frac{y_{n+1}+y_n}{2})+\frac{1}{2}\nabla U(y_{n+1})],
\end{align*}
and we can get the accurate form of the exponential function
\begin{equation*}
e^{hQM}= \begin{pmatrix}
\cos(h)I_{2} & \sin(h)I_{2}\\
-\sin(h)I_{2} & \cos(h)I_{2} 
\end{pmatrix}.
\end{equation*}


