\paragraph{\textbf{FPU system with a cubic Hamiltonian}}
%\note{Shall we compare Kahan's method with the state-of-the-art \href{https://www.semanticscholar.org/paper/The-exponential-scalar-auxiliary-variable-(E-SAV)-Liu-Li/f88d305fd0f412358a26673de53e93c5258e9ffc}{ESAV method} and \href{https://epubs.siam.org/doi/10.1137/21M1446496}{SAV-E method}. If we can: check efficiency? stability (change $\Delta t$ and $\Delta x$)? } 
The $\alpha$-Fermi-Pasta-Ulam (FPU) system, originating from the study by Fermi, Pasta, Ulam, and Tsingou, has evolved into a paradigmatic model in nonlinear wave theory \cite{4376203}. We study a continuum generalization of the FPU system
\begin{equation*}\label{fpu1}
\frac{\partial^2 u}{\partial t^2}=\beta \frac{\partial^3 u}{\partial t \partial^2 x} + \frac{\partial^2 u}{\partial x^2}[1+\epsilon (\frac{\partial u}{\partial x})^p] -\gamma \frac{\partial u}{\partial t} -m^2 u,
\end{equation*}
where the independent variables $(x,t) \in [0,L] \times [0,T]$, the parameter $\epsilon > 0$, the internal damping coefficient $\beta \geq0$, and the external damping coefficient $\gamma \geq0$. By introducing $\frac{\partial u}{\partial t}=v$, we can reformulate the second-order partial differential equation into the following first-order differential equations
\begin{align*}\label{fpu2}
\left\{\begin{array}{ll}
{\partial_t u =v,}  \\ 
{\partial_t v =\beta \frac{\partial^2 v}{\partial x^2}+\frac{\partial^2 u}{\partial x^2}(1+\epsilon(\frac{\partial u}{\partial x})^p)-\gamma v-m^2 u}.  \\ 
\end{array}\right.
\end{align*}
Setting $y=[u^\mathsf{T},v^\mathsf{T}]^{\mathsf{T}}$, we can rewrite the above equation  into the following Hamiltonian form 
\begin{equation*}
\frac{\partial y}{\partial t} = \mathcal{Q}\frac{\delta \mathcal{H}}{\delta y},
\end{equation*}
where
\begin{equation*}
\mathcal{Q}=
\left[
\begin{array}{cc}
0 & 1 \\
-1 & \beta\partial^2_x -\gamma \\
\end{array}
\right],
\quad
\mathcal{H}=\int_{0}^{L} H(t,u,v,u_x) \mathrm{d}x,
\end{equation*}
and the local energy density $H(t,u,v,u_x)$  is given by
\begin{equation*}
H(t,u,v,u_x)=\frac{1}{2}u_x^{2}+\frac{m^2}{2}u^2+\frac{1}{2}v^2+\epsilon\frac{u_x^{p+2}}{(p+1)(p+2)}.
\end{equation*}
We consider $p=1$ and  homogeneous Dirichlet boundary conditions $u(0,t) = u(L,t) = 0$. Employing the second-order central difference to discretize the second derivative $\partial_x^2$ and the forward difference to discretize $\partial_x$, we derive the semi-discrete system 
\begin{equation*}
\dot{y}=Q(My+\nabla U(y)),
\end{equation*}
where
\begin{equation*}
Q=\left[
\begin{array}{cc}
0 & I \\
-I & \beta D-\gamma I \\
\end{array}
\right],
M=\left[
\begin{array}{cc}
m^2I-D & 0 \\
0 & I  \\ 
\end{array}
\right],
U(y)=\sum_{j=0}^{N-1} \frac{\epsilon}{6}(\frac{u_{j+1}-u_j}{\Delta x})^3.
\end{equation*}

We set  $m=0$, $\epsilon=\frac{3}{4}$, $L=128$, $T=100$, the spatial discretization to be $\Delta x=1$ and the time step size to be $h_{i}=1/2^{i}$, $i=1,2,\ldots,4$.  
The initial conditions are given by
\begin{equation*}
u_j(0) = q_j(0), \quad v_j(0) = \dot{q}_j(0),
\end{equation*}
where the function $q_j(t)$ takes the form
\begin{equation*}
q_j(t) = 5\sum_{k\in\{32,96\}} \ln \frac{1+e^{2(\alpha(j-k)+t\sinh\alpha)}}{1+e^{2(\alpha(j-k-1)+t\sinh\alpha)}}
\end{equation*}
with $\alpha=0.1$.

% In Figure \ref{fig:FPU energy_error}, we can see that the EKahan method not only can preserve the energy well when there is no damping ($\gamma=\beta=0$), but also preserve the dissipation property when the internal damping coefficient $\beta$ or the external damping coefficient $\gamma$ is greater than zero, consistent with what is observed in \cite{MR2502318}. And Figure \ref{fig:FPU energy_efficiency} numerically validates Theorem \ref{theorem-energy} by demonstrating the energy deviation per time step when using the EKahan method. 
We consider three different settings of damping coefficients: i) a conservative system with $\gamma = 0$ and $\beta = 0$, ii) a dissipative system with $\gamma = 0.1$ and $\beta = 0$, and iii) a dissipative system with $\gamma = 0$ and $\beta = 2$. Figure \ref{fig:FPU energy_error} shows that EKahan method preserves the energy structure of the equation in both conservative and dissipative settings: 
\begin{enumerate}
\item[i)] the  energy error of all methods stays bounded and oscillated  in the undamped case in Figure \ref{fig:FPU energy_error_gamma=0_beta=0},
\item[ii)] the per-step energy deviation under EKahan discretization shown in  Theorem \ref{theorem-energy} is validated in Figure  \ref{fig:FPU est} ,
