\paragraph{\textbf{Zakharov–Kuznetsov equation}}

The Zakharov--Kuznetsov (ZK) equation is a two-dimensional generalization of the classical Korteweg--de Vries (KdV) equation~\cite{ZK1974}, modeling the propagation of nonlinear waves in magnetized plasmas and stratified fluids. In this study, we consider the specific form
\begin{equation*}
u_t + u^p u_x + u_{xxx} + u_{xyy} = 0,
\end{equation*}
for $(x, y) \in [0, L] \times [0, L]$ and $t \in [0, T]$. Among its conserved quantities, we consider the following energy functional
\begin{equation*}
\mathcal{H}(t) = \frac{1}{2} \int_{\mathbb{R}^2} (u_x^2 + u_y^2) \, \mathrm{d}x \, \mathrm{d}y - \frac{1}{(p+1)(p+2)} \int_{\mathbb{R}^2} u^{p+2} \, \mathrm{d}x \, \mathrm{d}y.
\end{equation*}
For $p = 1$, the equation admits the following Hamiltonian structure:
\begin{equation*}
u_t = -\partial_x \frac{\delta \mathcal{H}}{\delta u},\quad \frac{\delta \mathcal{H}}{\delta u} = \frac{1}{2} u^2 + u_{xx} + u_{yy}.
\end{equation*}

To discretize the problem, we use the following discrete energy 
\begin{equation*}
H(u) = \sum_{j=0}^{N_y} \sum_{i=0}^{N_x} \left( \frac{(\delta_x^+ u_{i,j})^2 + (\delta_x^- u_{i,j})^2}{4} + \frac{(\delta_y^+ u_{i,j})^2 + (\delta_y^- u_{i,j})^2}{4}  + \frac{u_{i,j}^3}{6} \right) \Delta x \Delta y.
\end{equation*}
Here, $\delta_x^+$ and $\delta_x^-$, similarly $\delta_y^+$ and $\delta_y^-$, denote the forward and backward finite difference operators in the $x$- and $y$-directions, respectively. First-order and second-order central difference operators are employed to approximate the first and second spatial derivatives, respectively. The corresponding discrete differential operators are denoted by $D_x^{(1)}, D_x^{(2)}, D_y^{(1)},$ and $D_y^{(2)}$. Using these notations, the semi-discrete system can be compactly written as
\begin{equation*}
\dot{U} = -D_x^{(1)} \left( \frac{1}{2} U.^2 + D_x^{(2)} U + D_y^{(2)} U \right),
\end{equation*}
where the vector $U \in \mathbb{R}^{(N_x-1)\times(N_y-1)}$  is flattened from  $u_{i,j}$ by stacking columns successively, giving priority to the $y$-direction, and $U^2$ denotes the element-wise square of $U$. Here, $N_x$ and $N_y$ are the grid numbers in each spatial direction.


%The EKahan scheme applied to \eqref{eq:ZK-semi-discretise} gives us
%\begin{align*}
%    U^{n+1}
%%%%&=e^{hQM}U^{n}+h\phi(hQM)Q(-\frac{1}{4}(U^{n}+U^{n+1})^{2}_{\cdot}+\frac{1}{4}(U^{n})_{\cdot}^{2}+\frac{1}{4}(U^{n+1})_{\cdot}^{2})\\
%=e^{hQM}U^{n}+\frac{1}{2}h\phi(hQM)Q(U^{n}.*U^{n+1}),
%\end{align*}
%where $M = D_x^{(2)} + D_y^{(2)}$ and $Q = -D_x^{(1)}$. 
Numerical simulations are carried out on the spatial domain $[0, L] \times [0, L]$ with $L = 6$ and the temporal domain $[0, T]$ with $T = 8$, subject to periodic boundary conditions. The spatial discretization employs a uniform grid with $N = 33$ points in each spatial direction, resulting in a mesh size of $\Delta x = \Delta y = L / (N-1)$.  For time integration, different time steps $h_i = 0.01/2^{i+1}, \; i = 1, 2, 3, 4$ are adopted.
We consider the initial condition
\begin{equation*}
u(0,x,y)=\sqrt{2}[\sin(\frac{2\pi x}{L})+\frac{1}{\sqrt{2}} \cos (\frac{4\pi x}{L}+\frac{\pi}{4})]\times[\cos(\frac{2\pi y}{L})+\frac{1}{\sqrt{2}} \cos (\frac{4\pi y}{L}+\frac{\pi}{3})].
\end{equation*}


