\section{Python Code for Overlap Pairs and Group Generation}

\subsection{Function to Generate Overlap Pairs}
\begin{lstlisting}[language=Python]
def generate_overlap_pairs(transaction_address_map):
    """
    Generate overlap pairs between transactions based on address overlaps.
    """
    overlap_pairs = {}  # Initialize an empty dictionary to store overlapping pairs
    transaction_nums = list(transaction_address_map.keys())  # Get a list of all transaction IDs

    # Compare each pair of transactions for overlaps
    for i in range(len(transaction_nums)):
        for j in range(i + 1, len(transaction_nums)):
            transaction_a, transaction_b = transaction_nums[i], transaction_nums[j]

            # Check if the two transactions have overlapping addresses
            if transaction_address_map[transaction_a] & transaction_address_map[transaction_b]:
                # Store the overlapping pair and their intersecting addresses
                overlap_pairs[(transaction_a, transaction_b)] = (
                    transaction_address_map[transaction_a] & transaction_address_map[transaction_b]
                )

    return overlap_pairs  # Return the dictionary of overlapping pairs
\end{lstlisting}

\subsection{Function to Generate Optimized Groups}
\begin{lstlisting}[language=Python]
def generate_groups(transaction_address_map, overlap_pairs):
    """
    Generate optimized groups of transactions where each group contains parallelizable transactions.
    """
    # Initialize degrees for each transaction (number of overlaps)
    transaction_degrees = {transaction: 0 for transaction in transaction_address_map}

    # Calculate degrees based on overlap pairs
    for transaction_a, transaction_b in overlap_pairs.keys():
        transaction_degrees[transaction_a] += 1
        transaction_degrees[transaction_b] += 1

    # Sort transactions by degree in descending order (higher overlap transactions first)
    sorted_transactions = sorted(transaction_degrees.keys(), key=lambda x: transaction_degrees[x], reverse=True)

    # Initialize the list of optimized groups
    optimized_groups = []

    # Assign each transaction to a group
    for transaction_num in sorted_transactions:
        added = False
        # Try to add the transaction to an existing group
        for group in optimized_groups:
            # Check if the transaction overlaps with any transaction in the current group
            if not any(transaction_address_map[transaction_num] & transaction_address_map[other_transaction] for other_transaction in group):
                group.add(transaction_num)  # Add to group if no overlap
                added = True
                break
        # If no suitable group is found, create a new group for the transaction
        if not added:
            optimized_groups.append({transaction_num})

    return optimized_groups  # Return the list of optimized groups
\end{lstlisting}


