                                if ((trace[l].match(/SLOAD|SSTORE/g))[0] == 'SLOAD') {
                                    addrObj.addresses[k].read.push((trace[l].match(/[^:]*$/g))[0]);
                                } else if ((trace[l].match(/SLOAD|SSTORE/g))[0] == 'SSTORE') {
                                    addrObj.addresses[k].write.push((trace[l].match(/[^:]*$/g))[0]);
                                }
                            }
                        }
                    }

                    for (let k = 0; k < addrObj.addresses.length; k++) {
                        addrObj.addresses[k].read = [...new Set(addrObj.addresses[k].read)];
                        addrObj.addresses[k].write = [...new Set(addrObj.addresses[k].write)];
                    }

                    console.log(addrObj);

                    fs.appendFileSync('txDataFinal.json', JSON.stringify(addrObj));
                    globalList.push(addrObj);
                } catch (txErr) {
                    console.log(`Error processing transaction ${txHash}:`, txErr);
                    noOfErrors++;
                }
            }
        } catch (blockErr) {
            console.log(`Error processing block ${i}:`, blockErr);
            await new Promise(r => setTimeout(r, 2000));
        }
    }

    console.log('no of errors: ', noOfErrors);
    console.log('Global addr: ', globalList);
    fs.appendFileSync('txDataFinal.json', JSON.stringify(globalList));
}

main();
