\section{Proofs for Section~\ref{sec: SDPI and MEM general}} \label{app: additional proofs}

\subsection{Proof of Proposition~\ref{prop: approximate sdpi}} \label{sec: proofs framework}

Note that the statement for $\delta=0$ is simply the definition of an SDPI, so without loss of generality we can assume that $\delta>0$.
Thus, we can further assume that $|\Mcal|<\infty$, since otherwise the statement trivially holds.
We start the proof by proving two information theoretic results,
which intuitively,
show that if two random variables are statistically close, then (1) they have roughly the same Shannon entropy, and (2) any fixed randomized algorithm/channel extracts roughly the same amount of information from either source.


\begin{lemma}\label{fact:tv-imply-entropy-bound} 
    Suppose $P,Q$ are two random variables
    with pmfs $p,q$ respectively, supported on a finite domain $\Mcal$
    such that $d_{\TV}(p,q)\le \delta$. Then, we have $|H(P)-H(Q)|\le 2\delta \log\left( \frac{|\Mcal|}{\delta} \right)$.
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{fact:tv-imply-entropy-bound}]
For brevity, write $p_y = \Pr[P = y]$ and $q_y = \Pr[Q = y]$. Since the function $x\mapsto x\log(1/x)$ is monotone in $(0, 1)$, we define sets $L = \{y : p_y > q_y\}$ and $R = \{y : q_y > p_y\}$ and deduce that
\begin{align}
|H(P) - H(Q)|
& \le \max\left\{ \sum_{y\in L} p_y \log(1/p_y) - q_y \log(1/q_y),  \sum_{y\in R} q_y \log(1/q_y) - p_y \log(1/p_y) \right\} \notag \\
&\le \max\left\{  \sum_{y\in L} (p_y - q_y) \log(1/p_y),  \sum_{y\in R} (q_y - p_y) \log(1/q_y) \right\}. \label{equ:entropy-diff-to-tv-intermediate}
\end{align}
We show how to upper bound the first term $\sum_{y\in L} (p_y - q_y) \log(1/p_y)$. The bound for the second term can be analogously established. Consider the set $S_P = \{y \in L : p_y < \frac{\delta}{|\Mcal|} \}$. We have
$$
\begin{aligned}
\sum_{y\in L} (p_y - q_y) \log(1/p_y)
&\le \sum_{y\in L\setminus S_P} (p_y - q_y) \log(1/p_y) + \sum_{y\in S_P} p_y \log(1/p_y) \\
&\le \sum_{y\in L\setminus S_P} (p_y - q_y) \log\left(\frac{\delta}{|\Mcal|} \right) + \sum_{y\in S_P} p_y\log(1/p_y) \\ 
&\le \delta \log\left( \frac{|\Mcal|}{\delta} \right) +  \sum_{y\in S_P} p_y\log(1/p_y).
\end{aligned}
$$
By the monotonicity of $x\mapsto x\log(1/x)$, the bound of $p_y<\frac{\delta}{|\Mcal|}$, and the cardinality bound of $|S_P|$, we obtain
$$
\sum_{y\in S_P} p_y\log(1/p_y)\le \sum_{y\in S_P} \frac{\delta}{|\Mcal|} \cdot \log\left( \frac{|\Mcal|}{\delta} \right) \le \delta \log\left( \frac{|\Mcal|}{\delta} \right).
$$
Overall, we conclude that $\sum_{y\in L} (p_y - q_y) \log(1/p_y) \le 2\delta \log\left( \frac{|\Mcal|}{\delta} \right)$. The bound for the second term of \eqref{equ:entropy-diff-to-tv-intermediate} can be similarly established, concluding the proof.
\end{proof}


\begin{lemma} \label{lem: tv I robust}
    Let $B_1,B_2$ be two random variables over some space $\Bcal$ such that $d_{\TV}(B_1,B_2)\leq\delta$, and suppose $\Acal\colon\Bcal\to\Mcal$ is some randomized algorithm. Then
    \[
    \left|I(\Acal(B_1);B_1)-I(\Acal(B_2);B_2)\right|\leq 4\delta\log(|\Mcal|/\delta).
    \]
\end{lemma}



\begin{proof}[Proof of Lemma~\ref{lem: tv I robust}]
It holds that
$$
\left| I(\Acal(B_1);B_1)-I(\Acal(B_2);B_2) \right| \le \left| H(\Acal(B_1)) - H(\Acal(B_2)) \right| +  \left| H(\Acal(B_1)\mid B_1) - H(\Acal(B_2)\mid B_2) \right|.
$$
By Lemma~\ref{fact:tv-imply-entropy-bound} and the observation $d_{\TV}(\Acal(B_1),\Acal(B_2))\le d_{\TV}(B_1,B_2)\le \delta$, we obtain
$$
\left| H(\Acal(B_1)) - H(\Acal(B_2)) \right| \le 2\delta \log\left( \frac{|\Mcal|}{\delta} \right).
$$
We also note that
$$
\left| H(\Acal(B_1)\mid B_1) - H(\Acal(B_2)\mid B_2) \right|
\le \sum_{z\in \mathcal{B}} \left| \Pr[B_1 = z] - \Pr[B_2=z] \right| \cdot H(\Acal(z)) \le 2\delta \log(|\Mcal|).
$$
Combining both inequalities completes the proof of Lemma~\ref{lem: tv I robust}.
\end{proof}

Given the lemmas above, we are ready to complete the proof of Proposition~\ref{prop: approximate sdpi}.
Let $\tilde{B}$ be the approximation of $B$ which is given by the SDPI assumption, and denote $M:=\Acal(B),~\tilde{M}:=\Acal(\tilde{B})$. Applying Lemma~\ref{lem: tv I robust} and the $\rho$-SDPI assumption that holds for $(A,\tilde{B})$, we see that
\[
I(M;B)
\geq I(\tilde{M};\tilde{B})-4\delta\log(|\Mcal|/\delta)
\geq \frac{1}{\rho}I(\tilde{M};A)-4\delta\log(|\Mcal|/\delta)~.
\]
Further note that $d_{\TV}(\tilde{M},M)\leq d_{\TV}(\tilde{B},B)\leq\delta$, which implies $|H(\tilde{M})-H(M)|\leq2\delta\log(|\Mcal|/\delta)$ by Lemma~\ref{fact:tv-imply-entropy-bound}. Furthermore, by assumption, the same is true even after we condition on $A$. Therefore, we may conclude that 
$$|I(\tilde{M};A)-I(M;A)| \leq |H(\tilde M) - H(M)| + |H(M\mid A) - H(\tilde M\mid A)| \leq 4\delta\log(|\Mcal|/\delta).$$
Plugged into the inequality above, we get that
\[
I(M;B)
\geq \frac{1}{\rho}\left(I(M;A)-4\delta\log(|\Mcal|/\delta)\right)-4\delta\log(|\Mcal|/\delta)~,
\]
or rearranged,
\[
I(M;A)\leq
\rho I(M;B)+4\delta(1+\rho)\log(|\Mcal|/\delta)
\leq\rho I(M;B)+8\delta\log(|\Mcal|/\delta)
~.
\]




\subsection{Completing the Proof of Theorem~\ref{thm: excess mem}}\label{sec: complete excess mem proof}

We will show that if $\err(\Acal, \bP) \le \alpha$, then
\begin{align*}
    I(\Acal(X_{1:n}) ; X) \ge 
    \kl{\mathrm{Ber}(1-\alpha)}{\mathrm{Ber}(\alpha)} = 
(1-2\alpha)\log\left(\frac{1-\alpha}{\alpha}\right)~.
\end{align*}



Consider a random variable $X' \sim \Pcal_0$ drawn independently of $X\sim\Pcal_\theta,\,X_{1:n}\sim\Pcal_\theta^n$ and $\Acal(X_{1:n})$. Since $\Pcal_0$ is the marginal of $\Pcal_\theta$ over $\theta$, the characterization of the mutual information as the KL-divergence between the joint and product distributions shows that

\begin{align*}
    I(\Acal(X_{1:n});X) 
    &= \kl{\Acal(X_{1:n}), X}{\Acal(X_{1:n}), X'}
    \\&\ge \kl{\Acal(X_{1:n})(X)}{\Acal(X_{1:n})(X')}
    \\&=\kl{\mathrm{Ber}(p)}{\mathrm{Ber}(q)}~,
\end{align*}
where the inequality follows because post-processing does not increase the KL divergence,
and $p,q$ denote the probability of the model classifying positive/negative points as $1$, respectively. Now, the error of $\Acal$ is equal to $\frac{1-p}{2} + \frac{q}{2}$ and therefore the condition $\err(\Acal, \bP) \le \alpha$ implies that $p-q \leq 1- 2\alpha$. Optimizing this expression (as in the proof of Fano's inequality, cf. \citealp{cover1999elements}) we get \begin{align*}
I(\Acal(X_{1:n});X)
\geq \kl{\mathrm{Ber}(1-\alpha)}{\mathrm{Ber}(\alpha)} = 
(1-2\alpha)\log\left(\frac{1-\alpha}{\alpha}\right)\ .
\end{align*}



\section{Proof of Gaussian Clustering Application}
\label{sec: gaussian proof}

In this section, we prove Theorem~\ref{thm: gaussian lb}. We will establish the three claims one by one.

\subsection{Gaussian sample complexity $(n=1)$}

Given a single sample $X_1\sim\Pcal_\theta$, we will show that the algorithm that returns the linear classifier
\[
h(X):=\one{\inner{X_1,X}\geq \sqrt{4\log(200)d}}
\]
has error at most $0.01$. This will follow from standard Gaussian concentration bounds, since with high probability:
\begin{align*}
X\sim\Pcal_\theta~\implies~&\inner{X,X_1}\gtrsim \lambda^2d\gtrsim \sqrt{d}~,
\\
X\sim\Pcal_0~\implies~& \E\inner{X,X_1}=0~,\text{~~and hence~~}\left|\inner{X,X_1}\right|\lesssim \sqrt{d}~.
\end{align*}


Formally, start by noting that in the null case, $X_1$ and $X\sim\Pcal_0$ are simply two independent isotropic Gaussians, and therefore a standard bound on their inner product ensures that
\[
\Pr_{X\sim\Pcal_0}[\inner{X_1,X}\geq \sqrt{4\log (200)d}]\leq e^{-4\log(200)/4}=\frac{1}{200}~.
\]
On the other hand, if $X\sim\Pcal_\theta$ then both $X$ and $X_1$ can be seen as distributed as $X=\lambda\theta+g_0,~X_1=\lambda\theta+g_1$ where $g_0,g_1\sim\Ncal(0_d,(1-\lambda^2)I_d)$ are independent of one another as well as of $\theta$. Hence,
\begin{align*}
\inner{X,X_1}&=\lambda^2\|\theta\|^2+\lambda\inner{\theta,g_0}+\lambda\inner{\theta,g_1}+\inner{g_0,g_1}
\\&=\frac{C^2}{d^{1/2}}\|\theta\|^2+\frac{C}{d^{1/4}}\inner{\theta,g_0}+\frac{C}{d^{1/4}}\inner{\theta,g_1}+\inner{g_0,g_1}
~.
\end{align*}
Since $1-\lambda^2<1$, applying the same argument as in the null case to the latter three summands and union bounding ensures that
\[
\Pr_{\theta,g_0,g_1}[\min\{\inner{\theta,g_0},\inner{\theta,g_1},\inner{g_0,g_1}\}<-\sqrt{4\log(1200)d}]
\leq 3e^{-\log(1200)}
=\frac{1}{400}~.
\]
Furthermore, a standard bound on the norm of a Gaussian vector (cf. \citealp[Theorem 3.1.1]{vershynin2018high}) ensures that $\Pr[\|\theta\|^2<\gamma d]<\frac{1}{400}$ for some absolute constant $\gamma>0$. Union bounding over this event as well, we overall see that with probability at least $1-\frac{1}{200}:$
\[
\inner{X,X_1}\geq C^2\cdot\gamma d^{1/2}-2C\sqrt{4\log(1200)}d^{1/4}-\sqrt{4\log(1200)d}~.
\]
For sufficiently large absolute constant $C$, the latter is larger than $\sqrt{4\log(200)d}$, 
and we see that the linear classifier $h$ achieves error at most $2\cdot\frac{1}{200}=\frac{1}{100}$, completing the proof.




\subsection{Gaussian memorization lower bound}


In order to prove the lower bound, our goal is to
establish that the conditions in Theorem~\ref{thm: excess mem} hold. To do so, we use the dominating variables approach and apply
Theorem~\ref{thm: Z SDPI}, without any need for approximation (i.e. $\delta_n=0)$. We
construct the dominating random variables $Z^{\train}_\theta,Z_\theta^\test$ as
\begin{align}
Z_\theta^{\train}&=\Ncal\left(\frac{\lambda\sqrt{n}}{\sqrt{1+(n-1)\lambda^2}}\cdot\theta,\frac{1-\lambda^2}{1+(n-1)\lambda^2}\cdot I_d\right),
\label{eq: Z^n Gaussian}
\\
Z_\theta^\test&=\Ncal(\lambda\theta,(1-\lambda^2)I_d).    \nonumber
\end{align}
To see that these variables satisfy the $\rho_n$-SDPI,
we will use Fact~\ref{fact: classic SDPI gauss}, and therefore need to show the variables are $\sqrt{\rho_n}$-correlated unit Gaussians, for suitable $\rho_n$.
To that end, recalling that $\theta\sim\Ncal(0_d,I_d)$ and therefore marginalized over $\theta$ it holds that
\begin{align*}
Z_\theta^{\train}
&=\frac{\lambda\sqrt{n}}{\sqrt{1+(n-1)\lambda^2}}\Ncal(0_d,I_d)
+\Ncal\left(0_d,\frac{1-\lambda^2}{1+(n-1)\lambda^2}\cdot I_d\right)
\\
&=\Ncal\left(0_d,\frac{\lambda^2 n}{1+(n-1)\lambda^2}\cdot I_d\right)+\Ncal\left(0_d,\frac{1-\lambda^2}{1+(n-1)\lambda^2}\cdot I_d\right)
\\
&=\Ncal(0_d,I_d)~,
\end{align*}
and similarly
\begin{align*}
Z_\theta^\test=
\lambda \cdot\Ncal(0_d,I_d)+\Ncal(0_d,(1-\lambda^2)I_d)
=\Ncal(0_d,I_d)~.
\end{align*}
We see that $Z^{\train}_\theta,Z^\test_\theta$ are both unit Gaussians, with each coordinate $i\in[d]$ satisfying
\begin{align*}
\E\left[(Z^{\train}_\theta)_i\cdot(Z^\test_\theta)_i\right]
=\frac{\lambda\sqrt{n}}{\sqrt{1+(n-1)\lambda^2}}\cdot\lambda=:\sqrt{\rho_n}
,
\end{align*}
thus establishing the $\rho_n$-SDPI, as claimed.

We turn to argue about the existence of the desired mappings $\Phi^{\train},\Phi^\test$.
First note that $Z_\theta^{\train}$ can be mapped to $\Ncal(\lambda\theta,\frac{1-\lambda^2}{n}I_d)$ simply by rescaling
by $\sqrt{\frac{n}{1+(n-1)\lambda^2}}$.
Furthermore, it is known
that $\Ncal(\lambda\theta,\frac{1-\lambda^2}{n}I_d)$ can be processed to produce $X_1,\dots,X_n\sim\Ncal(\lambda\theta,(1-\lambda^2)I_d)$ since the average $\frac{1}{n}\sum_{i=1}^{n}X_i \sim \Ncal(\lambda\theta,\frac{1-\lambda^2}{n}I_d)$ is a sufficient statistic of Gaussians with the same known variance (cf. \citealp[Section 2.9]{cover1999elements}). By composition, this provides $\Phi^{\train}$.
Moreover, $\Phi^\test$ is simply the identity since $Z^\test_\theta\sim\Pcal_\theta$.
We therefore establish the test/train condition in Theorem~\ref{thm: Z SDPI} with $\delta_n\equiv0$.

To establish the data generation SDPI with $\epsilon_n\equiv 0$ as well, we once again use our construction of the post-processing $Z^{\train}_\theta$
as in Eq. (\ref{eq: Z^n Gaussian}), and claim that $\theta$ and $Z^{\train}_\theta$ satisfy the $\tau_n$-SDPI for 
$\sqrt{\tau_n}=\frac{\lambda\sqrt{n}}{\sqrt{1+(n-1)\lambda^2}}$.
This follows as we know that they are both unit Gaussians, and by noting that they are $\sqrt{\tau_n}$-correlated coordinate-wise by construction of $Z^{\train}_\theta$.
Therefore, the dataset $X_{1:n}$ which we have shown to be a post-processing of $Z_{\theta}^{\train}$ also satisfies $\tau_n$-SDPI with respect to $\theta$, since for every $M$ such that $M\indep \theta\,|\,X_{1:n}$ we can use the SDPI and the (regular) DPI to see that
\[
I(M;\theta)\leq \tau_n I(M;Z^{\train}_\theta)\leq \tau_n I(M;X_{1:n}).
\]

Overall, by applying Theorem~\ref{thm: Z SDPI}, we see that the conditions of Theorem~\ref{thm: excess mem} are met, and we get that for any algorithm $\Acal$ with $\err(\Acal,\bP_\mathrm{G})\leq \alpha<\half$
\[
\mathrm{mem}_n(\Acal,\bP_{\mathrm{G}})
\geq \frac{1-\tau_n}{\rho_n} C_{\alpha}
=\frac{1-\frac{\lambda^2 n}{1+(n-1)\lambda^2}}{\frac{\lambda^4 n}{1+(n-1)\lambda^2}} \cdot (1-2\alpha)\log\left(\frac{1-\alpha}{\alpha}\right)
=\frac{1-\lambda^2}{\lambda^4 n} \cdot (1-2\alpha)\log\left(\frac{1-\alpha}{\alpha}\right)
~.
\]


\subsection{Gaussian memorization upper bound}


Given a sample $X_{1:n}\sim\Pcal_\theta^n$, we will show that there exists an algorithm that returns a good classifier with the claimed memorization upper bound.
For that, we argue that an algorithm can return a high accuracy classifier $h=\Acal(X_{1:n})$ which is describable using $O(d \log(\tfrac{d}{n})/n)$ bits, hence in particular
\begin{equation} \label{eq: gauss upper mem proof}
\mem_n(\Acal,\bP_{\mathrm{G}})
=I(h;X_{1:n}\mid \theta)
\overset{(\star)}{\leq} I(h;X_{1:n})
\leq H(h)=O\left(\frac{d \log(\tfrac{d}{n})}{n}\right)
~,
\end{equation}
where $(\star)$ is due to the fact that $h\indep \theta\,|\,X_{1:n}$.


To construct the predictor we introduce some notation. Given a vector $v\in\reals^d$, we denote by $v^{[1:\ell]}:=(v_1,\dots,v_\ell,0,\dots,0)\in\reals^d$ its projection onto the first $\ell$ coordinates embedded in $\reals^d$.
Let $\hat{X}:=\frac{1}{n}\sum_{i=1}^{n}X_i$ be the dataset's empirical average, and note that
\begin{equation} \label{eq: Xhat gaussian}
    \hat{X}\sim \Ncal\left(\lambda\theta,\frac{1-\lambda^2}{n}I_d\right)~.
\end{equation}
For $\hat{X}^{[1:\ell]}=(\hat{X}_1,\dots,\hat{X}_\ell,0,\dots,0)\in\reals^d$, let $q_k(\hat{X}^{[1:\ell]})\in\reals^d$ be a quantization of $\hat{X}^{[1:\ell]}$ that stores only $k$ bits of $\hat{X}^{[1:\ell]}$ in each coordinate's binary expansion, allowing up to magnitude of $O(\log (d/n))$. We consider the algorithm $\Acal$ that returns the
linear classifier
\[
h(X):=\one{\inner{X^{[1:\ell]},q_k(\hat{X}^{[1:\ell]})}\geq t}.
\]
We will argue that for suitable choices of 
\[
\ell=\Theta(d/n)~,
~~~k=\Theta\left(\log(\tfrac{d}{n})\right)~,
~~~t=\Theta(\sqrt{d/n})~,
\]
this classifier satisfies the desired properties.
We note that this classifier is described by $\ell k=O(d \log(\tfrac{d}{n})/n)$ bits, so indeed
\eqref{eq: gauss upper mem proof} holds, proving the memorization upper bound.

It remains to show that $h$ is a high accuracy classifier. To bound the classifier's error, 
recall \eqref{eq: Xhat gaussian} and note that on one hand for the null case $X\sim\Pcal_0=\Ncal(0_d,I_d):$
\begin{align*}
\inner{X^{[1:\ell]},\hat{X}^{[1:\ell]}}
&=\inner{X^{[1:\ell]},\lambda\theta^{[1:\ell]}}
+\left\langle X^{[1:\ell]},\Ncal\left(0_{\ell},\frac{1-\lambda^2}{n}I_\ell\right)\right\rangle
\\
&=\Ncal(0,\lambda^2\|\theta^{[1:\ell]}\|^2+\|g\|^2)
~,~~~g\sim\Ncal\left(0_{\ell},\frac{1-\lambda^2}{n}I_\ell\right)
\end{align*}
where equality is in the distributional sense.
Hence,
\[
\E\inner{X^{[1:\ell]},\hat{X}^{[1:\ell]}}
=0~,
\]
and applying the general Hoeffding's inequality \citep[Theorem 2.6.2]{vershynin2018high} ensures that for some absolute constants $c_1,c_2>0:$
\begin{align}
 \Pr\left[\inner{X^{[1:\ell]},\hat{X}^{[1:\ell]}}
\geq \frac{t}{2}\right]
&\leq \exp\left(-\frac{c_1t^2}{\lambda^2\|\theta^{[1:\ell]}\|^2+\|g\|^2}\right)
\nonumber\\&\overset{(1)}{\leq_{p}}
\exp\left(-\frac{c_2 t^2}{\ell/d^{1/2}+\ell/n}\right)
\nonumber\\&\overset{(2)}{\leq}0.001~,
\label{eq: gaussian proj null}
\end{align}
where $\overset{(1)}{\leq_{p}}$ holds with high probability (say, at least $0.999$) 
for suitable $c_2$
since $\|\theta^{[1:\ell]}\|^2\lesssim \ell$ and $\|g\|^2\lesssim \ell\cdot\frac{1-\lambda^2}{n}\leq \frac{\ell}{n}$, and $\overset{(2)}{\leq}$ holds for a suitable assignment of $t,\ell$ as above, under our assumption that $d\gtrsim n^2$.

It remains to further bound the error induced by quantization.
Note that a standard bound on the maximum of independent normal variables, each of the first $\ell$ coordinates of $\hat{X}^{[1:\ell]}$ is bounded by $\leq 1000\sqrt{2\log \ell}$ with probability at least $0.999$.
Since we are storing the bits allowing up to a magnitude of $O(\log(d/n))$, under this probable event the quantization error is only due to the bits erased at the right-end of the binary expansion.
It therefore holds that
\begin{align*}
\inner{X^{[1:\ell]},q_k(\hat{X}^{[1:\ell]})}
&=\inner{X^{[1:\ell]},\hat{X}^{[1:\ell]}}
+\inner{X^{[1:\ell]},q_k(\hat{X}^{[1:\ell]})-\hat{X}^{[1:\ell]}}
\\
&\leq\inner{X^{[1:\ell]},\hat{X}^{[1:\ell]}}+\|X^{[1:\ell]}\|\cdot\|q_k(\hat{X}^{[1:\ell]})-\hat{X}^{[1:\ell]}\|
\\
&\leq\inner{X^{[1:\ell]},\hat{X}^{[1:\ell]}}+\|X^{[1:\ell]}\|\cdot\sqrt{\ell}\underset{\text{coordinate-wise quantization error}}{\underbrace{\|q_k(\hat{X}^{[1:\ell]})-\hat{X}^{[1:\ell]}\|_{\infty}}}
\\
&\leq \inner{X^{[1:\ell]},\hat{X}^{[1:\ell]}}+\|X^{[1:\ell]}\|\cdot\sqrt{\ell}2^{\log_2 O(\sqrt{\log \ell})-k}
\\
&\leq \inner{X^{[1:\ell]},\hat{X}^{[1:\ell]}}+\|X^{[1:\ell]}\|\cdot\sqrt{\ell\log \ell}\cdot 2^{-k}
~,
\end{align*}
and further applying a Gaussian norm bound that ensures that $\Pr[\|X^{[1:\ell]}\|\geq \widetilde{C}\sqrt{\ell}]<0.0001$ for absolute constant $\widetilde{C}>0$,
we see that the additional term is negligible for our setting of $k$.
Union bounding with \eqref{eq: gaussian proj null} and
overall obtain
\begin{equation} \label{eq: null gaussian prediction}
\Pr_{X\sim\Pcal_0}\left[h(X)=0\right]
=\Pr_{X\sim\Pcal_0}[\inner{X,q_k(\hat{X}^{[1:\ell]})}< t]
> 0.995~.
\end{equation}




As to $X\sim\Pcal_\theta=\Ncal(\lambda\theta,(1-\lambda^2)I_d)$, note that
\[
\E\inner{X^{[1:\ell]},\hat{X}^{[1:\ell]}}
=\lambda^2\E\|\theta^{[1:\ell]}\|^2
=\lambda^2 \ell
=C^2 \cdot \Theta\left(t\right)~.
\]
Thus, similar concentration and quantization arguments as in the null case yields for sufficiently large absolute constant $C>0$ (in the problem definition):
\begin{equation} \label{eq: true gaussian prediction}
\Pr_{X\sim\Pcal_\theta}\left[h(X)=1\right]
=\Pr_{X\sim\Pcal_\theta}[\inner{X^{[1:\ell]},q_k(\hat{X}^{[1:\ell]})}> t]
> 0.995~.
\end{equation}
By union bounding \eqref{eq: null gaussian prediction} and \eqref{eq: true gaussian prediction} we get overall that
\[
\err(\Acal,\bP_{\mathrm{G}})<0.01~,
\]
which completes the proof.







\section{Proof of Boolean Clustering Application}\label{sec: boolean proof}

In this section, we prove Theorem~\ref{thm: boolean lb}.


\subsection{Boolean sample complexity $(n=1)$}\label{sec: boolean sample complexity}



Consider the algorithm that given $X_1\sim\Pcal_\theta$ returns the predictor
\[
h(X):=\one{\inner{X_1,X}\geq \sqrt{2\log(200)d}}~.
\]
To see why this predictor suffers from error at most $0.01$, first note that for $X\sim \Pcal_{0}:~\E\inner{X_1,X}=0$, and by Hoeffding's inequality:
\begin{equation}\label{eq: boolean null}
\Pr[\inner{X_1,X}\geq\sqrt{2\log(200)d}]\leq \frac{1}{200}~. 
\end{equation}
On the other hand,
for $X\sim P_\theta:$
\[
\E\inner{X_1,X}
=\sum_{i=1}^{d}\E[(X_1)_i\cdot (X)_i ]
=d\cdot\E[(X_1)_1]\cdot \E[(X)_1]
~.
\]
Note that on one hand $\E[(X)_1]=\lambda \theta_1$,
or equivalently $\theta_1\E[(X)_1]=\lambda$. Plugging this into the equation above, we see that
\[
\E\inner{X_1,X}=d\theta_1^2\E[(X_1)_1]\cdot \E[(X)_1]=d\lambda^2=C^2\sqrt{d}
~.
\]
A similar calculation also shows that $\var\inner{X_1,X}=d\var((X_1)_1)\var((X)_1)\leq d$, following from Popoviciu's variance bound. Therefore, Chebyshev's inequality yields
\begin{equation} \label{eq: boolean true}
\Pr[\inner{X_1,X}\leq (C^2-\sqrt{200})\sqrt{d}]\leq\frac{1}{200}~.
\end{equation}
Assuming $C$ is sufficiently large so that $C^2-\sqrt{200}>\sqrt{2\log(200)}$ we see
by union bounding over \eqref{eq: boolean null} and \eqref{eq: boolean true}
that the defined predictor $h$ indeed classifies between samples from $\Pcal_\theta$ and $\Pcal_0$ with error at most $\frac{1}{200}+\frac{1}{200}=\frac{1}{100}$, as claimed.


\subsection{Boolean memorization lower bound}

Once again, we will follow the framework of Theorem~\ref{thm: excess mem} to prove Item 2 of Theorem~\ref{thm: boolean lb}.

\subsubsection*{Binomials and advanced composition}

To start, we state and prove the following lemma.

\begin{lemma}\label{lemma:composition-RR}
    Let $\lambda \in (0,1/10)$ and $n\in\NN$ be such that $n < \frac{1}{10\lambda^2}$. Let $X$ be a product distribution over $\{\pm 1\}^n$ where for each coordinate $i$ it holds that $\Pr[X_i = 1] = \frac{1+\lambda}{2}$. Similarly let $Y$ be a product distribution over $\{\pm 1\}^{n}$ where for each $i\in [n]$ it holds that $\Pr[Y_i = 1] = \frac{1-\lambda}{2}$. Then, for every $\delta \in (0, 1)$ and $\rho = \sqrt{8 n \log(1/\delta)}\lambda$, there exists a pair of distributions $\mathbf{A}, \mathbf{B}$ over $\{\pm 1\}^{n}$ such that
    $$
    \begin{aligned}
    & d_{\TV}(X, \frac{1+\rho}{2}\mathbf{A} + \frac{1-\rho}{2}\mathbf{B}) < \delta, \\
    & d_{\TV}(Y, \frac{1-\rho}{2}\mathbf{A} + \frac{1+\rho}{2} \mathbf{B}) <\delta.
    \end{aligned}
    $$
    Here, $p\mathbf{A} + (1-p)\mathbf{B}$ denotes the mixture of two distributions with weights $p$ and $(1-p)$.
\end{lemma}

Lemma~\ref{lemma:composition-RR} tells us how to post-process a Bernoulli random variable with bias $\frac{1}{2}\pm \rho$, to approximate a sequence of $n$ independent Bernoulli random variables, each of bias $\frac{1}{2}\pm \lambda$ where $\lambda \approx \frac{\rho}{\sqrt{n}}$. 
This lemma appears to be folklore in the differential privacy literature, yet for completeness, we include a brief proof below. First, we need the notion of ``indistinguishability'' between distributions.

\begin{definition}
Let $X, Y$ be a pair of random variables with the same support $\Omega$. We say that $X$ and $Y$ are $(\varepsilon, \delta)$-indistinguishable, if for every measurable $E\subseteq \Omega$, it holds that
$$
\begin{aligned}
& \Pr[X\in E] \le e^{\eps} \Pr[Y\in E] + \delta, \\
& \Pr[Y\in E] \le e^{\eps} \Pr[X\in E] + \delta.
\end{aligned}
$$
\end{definition}

We use the following ``decomposition'' lemma for indistinguishable distributions, the proof of which is usually attributed to \cite{KairouzOV15-Comp}.

\begin{proposition}[\cite{KairouzOV15-Comp}]\label{prop:privacy-decomp}
    Suppose $X,Y$ are $(\eps,\delta)$-indistinguishable. Then, there exists four distributions $X',Y',E_1,E_2$ such that
    $$
    \begin{aligned}
    X = (1-\delta)X' + \delta E_1, \\
    Y = (1-\delta)Y' + \delta E_2,
    \end{aligned}
    $$
    and $X',Y'$ are $(\eps,0)$-indistinguishable. Furthermore, there are two distributions $U,V$ such that
    $$
    \begin{aligned}
    X' = \frac{e^\eps}{1+e^\eps} U + \frac{1}{1+e^\eps} V, \\
    Y' =\frac{e^\eps}{1 + e^\eps} V + \frac{1}{1+e^\eps} U.
    \end{aligned}
    $$
\end{proposition}

In light of Proposition~\ref{prop:privacy-decomp}, to prove Lemma~\ref{lemma:composition-RR}, it suffices to show that the distributions $X,Y$ in the statement are $(\rho,\delta)$-indistinguishable.

In the language of differential privacy, $X$ and $Y$ can be understood as the $n$-wise composition of the randomized response mechanism,\footnote{Recall that the $(\varepsilon,0)$-DP randomized response (RR) mechanism receives an input $b\in \{\pm 1\}$, and outputs a random bit $\hat{b}$ such that $\Pr[\hat{b} = b] = \frac{e^\eps}{1 + e^\eps}$.} where each individual RR mechanism enjoys $(\lambda+o(1), 0)$-DP. The advanced composition theorem of differential privacy then says the following:

\begin{proposition}[\cite{DworkRV10-boosting,KairouzOV15-Comp}]\label{prop:advanced-composition}
    Suppose $\mathcal{A}_1,\dots, \mathcal{A}_n$ are $n$ $(\eps, 0)$-DP algorithms operating on $b\in \{\pm 1\}$ and $n < \frac{1}{5\eps^2}$. Then, their composition $(\mathcal{A}_1 \circ \dots \circ \mathcal{A}_n)$ satisfies $(\sqrt{4n\log(1/\delta)}\eps, \delta)$-DP for every $\delta \in (0, 1)$. In other words, $(\mathcal{A}_1\circ\dots \circ \mathcal{A}_n)(-1)$ and $(\mathcal{A}_1\circ\dots \circ \mathcal{A}_n)(+1)$ are $(\sqrt{4n\log(1/\delta)}\eps, \delta)$-indistinguishable.
\end{proposition}

Finally, combining Propositions~\ref{prop:advanced-composition} and~\ref{prop:privacy-decomp} concludes the proof of Lemma~\ref{lemma:composition-RR}.

\subsubsection*{The mutual information bound}

We are ready to establish the second item of Theorem~\ref{thm: boolean lb}.
Recall the setting of $\LB$: a random $\theta\sim \{\pm 1\}^{d}$ is drawn. The input distribution $\Pcal_\theta$ is the binary symmetric channel $\BSC_{\frac{1-\lambda}{2}}(\theta)$. Namely, to draw $y\sim \Pcal_\theta$, for each coordinate $i\in [d]$ set $y_i = \theta_i$ with probability $\frac{1+\lambda}{2}$, and set $y_i = -\theta_i$ otherwise. Next, we verify that the two conditions of Theorem~\ref{thm: excess mem} are met for $\LB$.

\medskip\noindent\textbf{Data generation SDPI.}
Conditioning on $\theta\in \{\pm 1\}^{d}$, for each $i\in [d]$, the $i$-th coordinates of $X_{1: n}$ are $n$ independent draws from a Bernoulli distribution of bias $\frac{1}{2} + \lambda \cdot \theta_i$. As such, we apply Lemma~\ref{lemma:composition-RR} with some $\delta > 0$ to be specified. Namely, we draw a single $Z_i$ from $\mathrm{Ber}(\frac{1}{2}+\xi \theta_i)$ with $\xi = \sqrt{8 n \log(1/\delta)} \cdot \lambda$, and post-process $Z_i$ as in Lemma~\ref{lemma:composition-RR}, to obtain a collection of $n$ Boolean variables $(\tilde{X}_{1,i},\dots, \tilde{X}_{n,i})$, such that (over the randomness of $Z_i$ and the post-processing) the TV distance between $(X_{1,i},\dots, X_{n,i})$ and $(\tilde{X}_{1,i},\dots, \tilde{X}_{n,i})$ is at most $\delta$. We run the same argument for each coordinate $i\in [d]$. Overall, we have shown how to post-process a random variable $Z\sim \BSC_{\frac{1-\xi}{2}}(\theta)$ to obtain a sequence of $n$ samples $\tilde{X}_{1:n}$ such that the TV distance between $\tilde{X}_{1:n}$ and $X_{1:n}$ is bounded by $\delta d$.
Using Item 1 of Theorem~\ref{thm: Z SDPI}, this implies that the pair $(\theta, X_{1:n})$ satisfies $(\xi^2, \delta d)$-SDPI 
where $\xi = \sqrt{ 8 n\log(d/\delta)} \cdot \lambda$ and $\delta \in (0, 1)$ can be arbitrarily chosen.

\medskip\noindent\textbf{Test/train SDPI.} We now verify the second condition. Consider the ``$Z$'' random variable we have introduced. We have shown a post-processing mapping $\Phi^{\train}$ such that $\Phi^{\train}(Z)$ is close to $X_{1:n}$ in TV distance. We can also draw $X\sim \Pcal_\theta$ and define $\Phi^{\test}$ as the identity mapping. It remains to show that $Z$ and $X$ satisfy $\rho_n$-SDPI for a small $\rho_n$. Indeed, note that $\theta$ is uniform over $\{\pm 1\}^{d}$. Conditioned on $\theta$, we have $Z\sim \BSC_{\frac{1-\xi}{2}}(\theta)$ and $X\sim \BSC_{\frac{1-\lambda}{2}}(\theta)$, and they are independent conditioning on $\theta$. Therefore, by the symmetry of the binary symmetric channel, it follows that $Z\sim \BSC_{\frac{1-\lambda\xi}{2}}(X)$, which implies that $Z$ and $X$ satisfy $\rho_n$-SDPI with $\sqrt{\rho_n} = \lambda\xi = \Otilde(\lambda^2 \sqrt{n}) = \Otilde(\sqrt{\frac{n}{d}})$. Consequently, by Item 2 of Theorem~\ref{thm: Z SDPI}, we conclude that the pair $(X, X_{1:n})$ satisfies $(\lambda^2 \xi^2, \delta d)$-SDPI,
where we recall that $\xi^2 \lambda^2 = \widetilde{O}(\lambda^4 n) = \widetilde{O}({\frac{n}{d}})$.

\medskip\noindent\textbf{Conclusion.} We have established both conditions of Theorem~\ref{thm: excess mem}. Using Theorem~\ref{thm: excess mem}, this yields that for any $\delta\in(0,1):$
\begin{align*}
\mathrm{mem}_n(\Acal,\bP_{\mathrm{B}})
=
\Omega\left(\frac{1-\lambda^2n\log(d/\delta)}{\lambda^4n\log(d/\delta)}\left(C_{\alpha}-\delta d\log(|\Mcal|/\delta)\right)\right)~,
\end{align*}
which by setting $\delta=\min\{(\frac{C_\alpha}{d\log(|\Mcal|)})^2,\,\half\}$ results in
\[
\mathrm{mem}_n(\Acal,\bP_{\mathrm{B}})
=\Omega\left(\frac{1-\lambda^2n\log(d\log|\Mcal|)}{\lambda^4n\log(d\log|\Mcal|)}C_{\alpha}\right)~.
\]
In particular, as long as $\lambda^2 n\leq\half$, or equivalently $n\leq \sqrt{d}/C^2$,
and if
$\log|\Mcal|\in\mathrm{poly}(d)$, or equivalently $|\Mcal|\leq \exp(d^{\tilde{C}})$ for some absolute constant $\tilde{C}>0$,
then
\[
\mathrm{mem}_n(\Acal,\bP_{\mathrm{B}})
=\widetilde{\Omega}\left(\frac{1-\lambda^2n}{\lambda^4n}C_{\alpha}\right)
=\widetilde{\Omega}\left(\frac{d}{n}\right)~.
\]



\subsection{Boolean memorization upper bounds}

Here, we describe algorithms to complement the lower bound and establish Item 3 of Theorem~\ref{thm: boolean lb}.
We split the proof into the two considered regimes $n\lesssim\sqrt{d}$ and $n\gtrsim\sqrt{d}\log d$.

\subsubsection*{Algorithm when $n\lesssim\sqrt{d}$}
We will show that when $1\le n\le \sqrt{d}$ examples are available, we can design an algorithm $\Acal$ which learns an accurate model $h$ such that $I(h; X_{1:n}) = O\left( \frac{d}{n} \right)$.

Let $C_{sub} > 0$ be a sufficiently large constant. On input $n$ i.i.d.~samples $X_{1:n}\sim \Pcal_\theta^n$, let $\hat{\theta}$ be the bit-wise majority vote of $X_{1:n}$. Our algorithm chooses $t = \min\left( d, \frac{Cd}{n} \right)$ and returns the hypothesis 
\begin{align}
    h(X) := \one{ \inner{{\hat{\theta}}^{[1,t]},{X^{[1,t]}}} \ge \sqrt{2 \log(200) t} }. \notag
\end{align}
Here, recall that for a vector $v\in \reals^d$, the notation $v^{[1,t]} = (v_1,\dots, v_t, 0, \dots, 0)$ denotes its projection onto the first $t$ coordinates embedded in $\reals^d$. 

We prove that $h$ is, with high probability, a good predictor. First, for $X\sim \Pcal_{0}$, the same argument as in Section~\ref{sec: boolean sample complexity} proves that $\Pr_{X\sim \Pcal_0}[h(X) = 1] \le \frac{1}{200}$.

It remains to show that $h$ classifies most $X\sim \Pcal_{\theta}$ correctly. Indeed, for every coordinate $j\in [d]$, we have
\begin{align}
    \Pr[\hat{\theta}_j = \theta_j] \ge \frac{1}{2} + C' \sqrt{n} \lambda \notag
\end{align}
for some constant $C'$. Also,
\begin{align}
    \Pr[X_j = \theta_j] = \frac{1}{2} + \lambda \notag
\end{align}
These two combined would imply that
\begin{align}
    \E\langle \hat{\theta}^{[1,t]}, X^{[1,t]} \rangle \ge C'\lambda^2 \sqrt{n} t = C'' \sqrt{t}. \notag
\end{align}
Similarly as in Section~\ref{sec: boolean sample complexity}, we have
\begin{align}
     \mathrm{Var}\left[\langle \hat{\theta}^{[1,t]}, X^{[1,t]} \rangle\right] \le t. \notag
\end{align}
Therefore, Chebyshev's inequality gives
\begin{align}
    \Pr[\langle \hat{\theta}^{[1,t]}, X^{[1,t]} \rangle \le ((C'')^2 - \sqrt{200})\sqrt{t} ] \le \frac{1}{200}. \notag
\end{align}
By setting $C_{sub}$ to be large enough, we can guarantee that $(C'')^2 - \sqrt{200} \ge \sqrt{2\log(200)}$, which would consequently yield that $\Pr_{X\sim \Pcal_{\theta}}[h(X) = 0]\le \frac{1}{200}$. This completes the accuracy analysis of $h$.

Regarding memorization, observe that $h$ can be described using $O(\frac{Cd}{n})$ bits. Hence, we have
\begin{align}
    \mem_{n}(\Acal, \LB) \le I(h; X_{1:n}) \le H(h) \le O\left( \frac{d}{n} \right), \notag
\end{align}
as desired.


\subsubsection*{Algorithm for $n\gtrsim\sqrt{d}\log d$}

We now provide an accurate algorithm for which $\mem_n(\Acal,\bP)=O(d^2\exp(-d/\sqrt{n}))$, and so if $n\geq \tilde{C}\sqrt{d}\log d$, then $\Acal$ learns an accurate model $h$ with nearly no excess memorization, particularly,
such that $I(h; X_{1:n}) = O( d^{-\tilde{C}/2} )$.

Similarly to the previously described algorithm, given $n$ i.i.d.~samples $X_{1:n}\sim \Pcal_\theta^n$, let $\hat{\theta}$ be the bit-wise majority vote of $X_{1:n}$. Our algorithm returns the hypothesis 
\begin{align*}
    h_{\hat{\theta}}(X) := \one{ \inner{{\hat{\theta}},{X}} \ge \sqrt{2 \log(200) d} }.
\end{align*}
Noting that this is the same predictor as before but with no projection, it is easy to verify that the accuracy analysis follows from the same calculation as in the previous case. We will therefore prove the memorization bound, which follows from different arguments.

By definition,
\begin{align*}
    \mem_n(\Acal,\LB)=\E_{\theta\sim\Ucal(\{\pm1\}^d)}\left[I(h_{\hat{\theta}}\mid\theta;S\mid\theta)\right]
    \leq \E_{\theta\sim\Ucal(\{\pm1\}^d)}[H(h_{\hat{\theta}}\mid\theta)]~.
\end{align*}
We will show that for any $\theta$, it holds that $H(h_{\hat{\theta}}\mid\theta)\lesssim d^{-\Omega(\tilde{C})}$,  thus implying the claimed bound. 
Fix $\theta$, and let $\gamma=\Pr_{X_{1:n}}[h_{\hat{\theta}}\neq h_{\theta}]$ which is the probability that the bit-wise majority vote did not reconstruct $\theta$. 
By Hoeffding's bound, for any coordinate $j\in[d]:\,\Pr_{X_{1:n}}[\hat{\theta}_j\neq \theta_j]\leq \exp(-n\lambda^2/2)$ so by union bounding we see that $\gamma\leq d\exp(-n\lambda^2/2)$.


Considering the Markov chain $\theta\to X_{1:n}\to h_{\hat{\theta}}$, Fano's inequality shows that
\begin{align*}
H(h_{\hat{\theta}}\mid \theta)
&\leq H_2(\gamma)+\gamma \log(|\{\pm1\}^d|-1)
\\&<H_2(\gamma)+\gamma d
\\&\leq 2\sqrt{\gamma}+\gamma d
\\&\leq 2\sqrt{d}\exp(-n\lambda^2/4)+d^{2}\exp(-n\lambda^2/2)
\\
&\leq 3d^{2}\exp(-n\lambda^2/2)
~,
\end{align*}
where we used the easily verifiable numerical bound $H_2(\gamma)\leq 2\sqrt{\gamma}$.
Overall we see that
\[
\mem_n(\Acal,\LB)= O(d^{2}\exp(-n\lambda^2/2))~,
\]
which under our parameter regime $\lambda=C/d^{1/4}$, yields the claimed bound.


\section{Proof of Sparse Boolean Hypercube Application}\label{sec: sparse bool proof}


In this section, we prove Theorem~\ref{thm: sparse boolean lb}.


\subsection{Sparse Boolean sample complexity $(n=1)$}


Recall that in $\LsB$, the learning problem is parameterized by $\theta = (S,y)$ where $S$ is a random subset including each $i\in [n]$ with probability $\nu \approx \frac{1}{d^{1/2}}$ and $y\sim \{ \pm 1\}^{d}$ is uniformly at random. The distribution $\Pcal_{\theta}$ is a product distribution $X$ on $\{\pm 1\}^{d}$ where $X_S=y_S$ with probability one and $X_{\overline{S}}$ is uniformly at random. 

We claim that learning with a single samples is possible so long as the set $S$ satisfies that $|S|\ge \sqrt{4\log(200)d}$. First, note that this event happens with probability at least $1-\exp(-\Omega(\sqrt{d}))$ if we choose $\nu = \frac{C}{d^{1/2}}$ for a large enough constant $C$. Now, suppose we have $|S|\ge \sqrt{4\log(200)d}$ and let $X_{1}$ be the training sample. Consider the hypothesis
\[
h(X) := \one{\langle X, X_1\rangle \ge \sqrt{2\log(200)d}}~.
\]

We verify that $h$ has a low generalization error. 
To see this, we first observe that for $X\sim \Pcal_{0}$, it holds $\E[\langle X_1,X\rangle] = 0$, and by Hoeffding's bound, we further have $\Pr[\langle X_1,X\rangle\ge \sqrt{2\log(200)d}] \le 0.005$. On the other hand, conditioned on $\theta$, for every $X\sim \Pcal_{\theta}$, we have that $X_S = (X_1)_S$ and $X_{j}\sim \{\pm 1\}$ for every $j\not\in S$. In this case, it is easy to see that $\langle X,X_1\rangle$ is a random variable with mean $|S| \ge \sqrt{2\log(200)d}$ and standard deviation $O(\sqrt{d-|S|})$.  Similarly to the proof for the case of $\LB$, we see that $\Pr_{X\sim \Pcal_{\theta}}[\langle X,X_1\rangle \le \sqrt{2 \log(200)d}]\le 0.005$. Overall, we see that the predictor $h$ has error at most $0.01$ as a classifier between $\Pcal_{\theta}$ and $\Pcal_{0}$, as desired.

\subsection{Sparse Boolean memorization lower bound}

In this section, we establish Item 2 of Theorem~\ref{thm: sparse boolean lb}. We will deviate slightly from the framework of Theorem~\ref{thm: excess mem}. In particular, we will establish a lower bound on $I(A(X_{1:n});X_{1:n})$ via the test/train SDPI as in Theorem~\ref{thm: excess mem}, however, we will \emph{not} prove a data generation SDPI. Instead, we directly upper bound $I(X_{1:n};\theta)$ by the Shannon entropy of $\theta$, which is at most $O(\sqrt{d}\log(d))$. Then, a lower bound on $I(A(X_{1:n});X_{1:n}\mid \theta)$ follows easily.

Suppose $\theta\sim \Psi$ and $( X,X_{1:n})\sim \Pcal_{\theta}^{n+1}$. We show that the pair $( X,X_{1:n})$ satisfy $\rho_n$-SDPI with $\rho_n = \Theta(\frac{2^n}{d^{1/2}})$. We begin with a basic observation: recall that the parameter $\theta$ consists of a pair $(S, x_S)$ where each element is included in $S$ with probability $\nu = \Theta(d^{1/2})$. Here, conditioning on $X$ would \emph{not} change the distribution of $S$: namely, it is still the case that each $i$ is in $S$ with probability $\nu$. Furthermore, if $i\in S$ then we know the $i$-th bits of the training samples (namely, $(X_{j,i})_{j=1}^n$) all agree with $X_{0,i}$. Otherwise, $(X_{j,i})_{j=1}^n$ is uniformly distributed in $\{\pm 1\}^{n}$. 

With this observation in mind, we introduce a random variable $Z\sim \BSC_{\frac{1}{2}+ \xi}(X)$ for some $\xi$ to be specified. Consider the following post-processing of $Z$ that produces sequence of samples $\tilde{X}_1,\dots, \tilde{X}_n$:
\begin{itemize}
    \item Independently for each coordinate $i\in [d]$, with probability $\nu + (1-\nu) 2^{-n+1}$, set all of $\tilde{X}_{1,i},\dots, \tilde{X}_{n,i}$ as $Z_i$. Otherwise choose $(\tilde{X}_{1,i},\dots, \tilde{X}_{n,i})\sim \Ucal(\{\pm 1\}^{n}\setminus \{(-1)^n,(+1)^n\})$ uniformly at random.
\end{itemize}

We argue that, for a proper choice of $\xi$, the joint distribution of $(X,\tilde{X}_{1:n})$ is identical to that of $(X,X_{1:n})$. Indeed, for each $i\in [d]$, the probability that all of $(X_{j,i})_{j=1}^n$ are the same is $\nu + (1-\nu) 2^{-n+1}$, which is also the case for $\tilde{X}_{1:n}$. Furthermore, conditioning on the event that $(X_{j,i})_{j=1}^n$ are not all-$0$ nor all-$1$, they are uniformly distributed in $\{\pm 1\}^{n} \setminus \{(-1)^n,(+1)^n\}$, which is, again, also the case for $\tilde{X}_{1:n}$.

We turn to the case that all of $(X_{j,i})_{j=1}^n$ are the same. It is easy to calculate that the probability of the event $(X_{j,i})_{j=1}^n = (X_{0,i})^n$
is $\nu + (1-\nu) 2^{-n}$, while the same probability term w.r.t.~$\tilde{X}$ evaluates to $(\frac{1}{2}+\xi)\cdot (\nu + (1-\nu)2^{-n+1})$. It remains to set $\xi$ properly so that the two probability quantities coincide. Indeed, this gives
$$
\xi = \frac{\nu + (1-\nu) 2^{-n}}{\nu + (1-\nu)2^{-n+1}} - \frac{1}{2} = \frac{\nu}{2\nu + (1-\nu)2^{-n+2}}.
$$
Recall that we set $\nu = \Theta(d^{-1/2})$. Therefore, for all $n\le o(\log d)$, the expression simplifies to $\xi = \Theta(\nu 2^{n})$.

We have shown that with the proper choice of $\xi$, we can define $Z\sim \BSC_{\frac{1}{2}+\xi}(X)$ and post-process $Z$ to obtain a sequence of samples $\tilde{X}_{1:n}$ identically distributed as $X_{1:n}$. This implies that the pair $(X,X_{1:n})$ enjoys at least the same SDPI as the pair $(X,Z)$. Quantitatively, the SDPI parameter we achieve is $\rho_n=\xi^2 = \Theta(\nu^2 2^{2n}) = \Theta(\frac{2^{2n}}{d})$. This consequently implies that
$$
I(\Acal(X_{1:n});X_{1:n})\ge \frac{1}{\rho_n} I(\Acal(X_{1:n}); X)
=\Omega\left( \frac{d}{2^{2n}}(1-2\alpha)\log\left(\frac{1-\alpha}{\alpha}\right) \right),
$$
as claimed. For all $n\le o(\log d)$, this lower bound is far above $\sqrt{d}\log d$. Hence,
$$
\mem_n(\Acal, \bP_{\mathrm{sB}})=I(\Acal(X_{1:n});X_{1:n}\mid \theta) \ge I(\Acal(X_{1:n});X_{1:n}) - H(\theta) = \Omega\left( \frac{d}{2^{2n}}\right).
$$



\subsection{Sparse Boolean memorization upper bound}




Similarly to the other memorization upper bound proofs, given a sample $X_{1:n}\sim\Pcal_\theta^n$, we will argue that an algorithm can return a high accuracy classifier $h=\Acal(X_{1:n})$ which is describable using $\widetilde{O}(d/2^{2n})$ bits, hence in particular
\begin{equation*}
\mem_n(\Acal,\bP_{\mathrm{sB}})
=I(h,X_{1:n}\mid \theta)
\overset{(h\indep \theta\,|\,X_{1:n})}{\leq} I(h,X_{1:n})
\leq H(h)=\widetilde{O}\left(\frac{d}{2^{2n}}\right)
~.
\end{equation*}
Let $\hat{S}\subset[d]$ be the subset that includes coordinates $j\in[d]$ in which the dataset is constant, namely for which $(X_i)_j=(X_{i'})_j$ is the same for all $i,i'\in[n]$. Furthermore, let $\hat{S}^\ell$ be the first $\ell$ coordinates in $\hat{S}$, and define
\[
h(X)
=\one{\inner{X_{\hat{S}^\ell},(X_1)_{\hat{S}^\ell}}\geq t}
=\one{\sum_{j\in \hat{S}^\ell}X_j\cdot (X_1)_j\geq t}~.
\]
We will argue that for suitable
\[
\ell=\Theta\left(\frac{d}{2^{2n}}\right),
~~~t=\sqrt{2\log(200)\ell}=\Theta(\sqrt{\ell}),
\]
this classifier satisfies the desired properties. We note that the memorization upper bound readily follows by the description length argument above, since all that needs to be stored are
the $\ell$ bits of $(X_1)_{\hat{S}^\ell}$ alongside their corresponding indices in $[d]$, which requires $O(\ell\log(d))$ memory.

It remains to show that $h$ is a high accuracy classifier. We first note that in the null case $\Pcal_0=\Ucal(\{\pm1\}^d)$, so it holds that
\[
\E_{X\sim \Pcal_0}\inner{X_{\hat{S}^\ell},(X_1)_{\hat{S}^\ell}}=0~,
\]
and by Hoeffding's bound
\begin{equation} \label{eq: sB null case}
\Pr\left[
\inner{X_{\hat{S}^\ell},(X_1)_{\hat{S}^\ell}} \geq t\right]
=\Pr\left[
\inner{X_{\hat{S}^\ell},(X_1)_{\hat{S}^\ell}} \geq \sqrt{2\log(200)\ell}
\right]
\leq 0.005~.
\end{equation}

We now turn to argue about the case $X\sim \Pcal_\theta$.
Note that for any coordinate $j\in\hat{S}^\ell$, if $j\in S$ then $X_j=(X_1)_j$ with probability $1$, yet if $j\notin S$ then $X_j\cdot (X_1)_j\sim\Ucal(\{\pm1\})$.
Hence, we see that
\begin{equation} \label{eq: E is cap of S}
    \E_{X\sim\Pcal_\theta}\inner{X_{\hat{S}^\ell},(X_1)_{\hat{S}^\ell}}
=|\hat{S}^\ell\cap S|
~.
\end{equation}
Therefore, we set out to estimate the size of $\hat{S}^\ell\cap S$. This set corresponds to coordinates in $\hat{S}^\ell$ which are ``truly'' constant, as opposed to uniformly random coordinates that happened to be constant on all seen examples, even thought they are not in $S$.
Accordingly, since $S\subset \hat{S}$, for any coordinate $j\in[d]:$
\[
\Pr[ j\in S \mid j\in \hat{S} ]
=\frac{\Pr[j\in \hat{S}\cap j\in S]}{\Pr[j\in \hat{S}]}
=\frac{\Pr[j\in S]}{\Pr[j\in \hat{S}]}
=  \frac{\nu}{\nu + (1-\nu)2^{-n+1}}
~.
\]
Moreover, by symmetry, choosing the first $\ell$ coordinates in $\hat{S}$ into $\hat{S}^\ell$ is equivalent to sub-sampling $\ell$ coordinates among the constant coordinates, and therefore
\[
\E |\hat{S}^\ell\cap S| = \ell\cdot \Pr[ j\in S \mid j\in \hat{S} ] 
= \ell \cdot \left( \frac{\nu}{\nu + (1-\nu)2^{-n+1}} \right) \gtrsim_{(1)} \ell \cdot \frac{2^n}{\sqrt{d}} \ge_{(2)} C'\cdot \sqrt{\ell}
~,
\]
where $(1)$ follows from the assumption that $n=O(\log d)$,
and $(2)$ follows for any constant $C'$ of our choice provided that $\ell = C''\frac{d}{2^{2n}}$ for a large enough $C''$.
For sufficiently large $C'$, Hoeffding's bound further ensures that
\[
\Pr[ |\hat{S}^\ell\cap S| >3t]>0.999~,
\]
and therefore under this probable event and applying yet another Hoeffding bound over $\inner{X_{\hat{S}^\ell},(X_1)_{\hat{S}^\ell}}$, \eqref{eq: E is cap of S} ensures that
\[
\Pr_{X\sim\Pcal_\theta}[\inner{X_{\hat{S}^\ell},(X_1)_{\hat{S}^\ell}} \geq t]>0.995~.
\]

Overall, combined with \eqref{eq: sB null case}, this ensures that the predictor $h$ has classification error of at most $0.01$, completing the proof.









\section{Proofs for Section \ref{sec: multiclass}} \label{sec: proof multi}

\subsection{Proof of Theorem~\ref{thm: multi cluster error local to global}}

The proof follows that of \cite[Theorem 2.3]{feldman2020does}.
We can write
\begin{align*}
\err(\Acal, \bPmult \mid S) 
&= \E_{\pi\sim \Pi_p^k,\theta_{1:k}\sim \Psi^k}\E_{S\sim \widetilde{\Pcal}_{\theta_{1:k},\pi},h\gets \Acal(S)}\left[\left. \frac{1}{2} \Pr_{X\sim \Pcal_{\theta_{1:k},\pi}}[h(X) = 0] + \frac{1}{2} \Pr_{X\sim \Pcal_{0}}[h(X) = 1] ~\right|~ S\right] \\
&= \frac{1}{2} \E_{\pi\sim \Pi_p^k,\theta_{1:k}\sim \Psi^k}\E_{S\sim \widetilde{\Pcal}_{\theta_{1:k},\pi},h\gets \Acal(S)}\left[\left. \sum_{j\sim \pi} \Pr_{X\sim \Pcal_{\theta_j}}[h(X) = 0] + \Pr_{X\sim \Pcal_{0}}[h(X) = 1] ~\right|~ S\right]
\end{align*}
Using $Z_{n\#\ell}$ to denote the collection of clusters $u$ that appear exactly $\ell$ times in $S$, we have
\begin{align*}
&~~~~ \frac{1}{2} \E_{\pi\sim \Pi,\theta_{1:k}\sim \Psi^k}\E_{S\sim \widetilde{\Pcal}_{\theta_{1:k},\pi},h\gets \Acal(S)}\left[\left. \Pr_{X\sim \Pcal_{\theta,\pi}}[h(X) = 0]  + \Pr_{X\sim \Pcal_0}[h(X) = 1] ~\right|~ S\right] \\
&= \sum_{0\le \ell \le n} \errn(\Acal,S,\ell) \cdot \frac{1}{|Z_{n\#\ell}|}\cdot \sum_{u\in Z_{n\#\ell}} \E[\pi_u \mid S] \\
&= \sum_{0\le \ell \le n} \tau_\ell \cdot \errn(\Acal, S, \ell).
\end{align*}
In words, the term $\tau_{\ell}$ reflects the change of (distribution of) $\pi_u$ after conditioning on $S$, while the term $\errn$ reflects the change of $\theta$. It turns out, by calculation, that after conditioning on $S$, the error of the algorithm can be succinctly described by the formula above.

To prove the theorem, it remains to argue that
\begin{align}
    \mathrm{opt}(\bPmult \mid S) \le \tau_0 \cdot \errn(\Acal, S,0) + O(1/k).\label{equ:opt ub conditioned on S}
\end{align}
We describe an algorithm $\Acal^*$ here: for every cluster $u$ that has been seen at least once in $S$, the algorithm trains a binary-classification model to distinguish $\Pcal_{\theta_u}$ from $\Pcal_{0}$ with error at most $\frac{1}{k^2}$ (this is possible thanks to Assumption~\ref{assump: multi learning}). Then, upon receiving a query $X$, the algorithm tests whether $X$ was likely from $\Pcal_{\theta_u}$ for every seen cluster $u$. $\Acal^*$ outputs $1$ if at least one of the tests outputs $1$. and $0$ otherwise. By simple union bound, for $X\sim \Pcal_0$, the algorithm makes an error on $X$ with probability at most $O(\frac{1}{k})$. For $X\sim \Pcal_{\theta_u}$ where $u$-th cluster is present in $S$, the probability that $\Acal^*$ misclassifies $X$ is at most $\frac{1}{k^2}$. For every $X\sim \Pcal_{\theta_u}$ where $u\in Z_{n\#0}$, $\Acal^*$ might fail miserably on $X$. However, by Lemma~\ref{lemma: ell coefficient}, the weight of all such clusters, after conditioning on $S$, is at most $\tau_0\cdot |Z_{n\# 0}|$. This shows that the error of $\Acal^*$ is upper bounded by the right-hand side of \eqref{equ:opt ub conditioned on S}, as claimed.

To establish the second item of the theorem, we simply take the average over $S$.




\subsection{Proof of Theorem~\ref{thm: accuracy to memorization}}

    Let $S = ((X_1,i_1),\dots, (X_n,i_n))$. We start by writing
    \begin{align*}
        I(\Acal(S) ; S \mid \theta_{1:k}, \pi)
        &= I(\Acal(S) ; S, (i_1,\dots, i_n) \mid \theta_{1:k}, \pi) \\
        &= I(\Acal(S); (i_1,\dots, i_n) \mid \theta_{1:k}, \pi) + I(\Acal(S); S \mid \theta_{1:k}, \pi, (i_1,\dots, i_n)) \\
        &\ge I(\Acal(S); S \mid \theta_{1:k}, \pi, (i_1,\dots, i_n)).
    \end{align*}
    We focus on the last line. By definition of conditional mutual information, we can first sample and condition on $\pi \sim \Pi_p^k$ and $i_1,\dots, i_n \sim \pi^n$, and consider the conditional mutual information $I(\Acal(S);S \mid \theta_{1:k})$ (where $i_1,\dots, i_n$, $\pi$ have been fixed). Note that the parameters $\theta_1,\dots, \theta_n$ and examples $X_1,\dots, X_n$ are independent of these choices and still have the same distribution. We denote by $S_\Xcal := (X_1,\ldots,X_n)$ the unconditioned part of $S$.

    Next, we want to show that the memorization of different clusters is essentially independent. Toward that goal, let $S_j$ be the set of pairs $(X,i)$ from $S$ such that $i = j$ (i.e.,~$S_j$ contains examples of $S$ that are from the $j$-th cluster). We have
    \begin{align*}
       I(\Acal(S) ; S \mid \theta_{1:k})
       &= H(S \mid \theta_{1:k}) - H(S \mid \theta_{1:k}, \Acal(S)) \\
       &\ge \sum_{j\in [k]} H(S_j \mid \theta_j) - H(S_j \mid \theta_{1:k}, \Acal(S)) &\text{(sub-additivity and additivity of entropy)} \\
       &\ge \sum_{j\in [k]} H(S_j \mid \theta_j) - H(S_j \mid \theta_{j},\Acal(S)) & \text{(monotonicity of conditional entropy)} \\
       &= \sum_{j\in [k]} I(\Acal(S) ; S_j \mid \theta_j).
    \end{align*}

    We now derive the claimed lower bound. As before, let $I_{n\# \ell}(S)$ be the collection of all $j$'s that appear exactly $\ell$ times among $i_1,\dots, i_n$.

    Having conditioned on $i_1,\dots,i_n$, let $j\in I_{n\#\ell}(S)$. We consider how well the algorithm distinguishes $\Pcal_{\theta_j}$ from $\Pcal_0$ (when we take the average over $\theta_j, S_j$ and $\Acal(S)$). Thinking of this as a binary classification problem between $\Pcal_{\theta_j}$ and $\Pcal_0$ where $\ell$ samples from $\Pcal_{\theta_j}$ are available, we can evaluate the error of the algorithm by
    \begin{align*}
        e_j := \frac{1}{2} \E_{\theta_{1:k}\sim \Psi^k, S_\Xcal, h \gets \Acal(S)}\left[\Pr_{X\sim \Pcal_{\theta_j}}[h(X) = 0] + \Pr_{X\sim \Pcal_{0}}[h(X) = 1] \right].
    \end{align*}
    Using Assumption~\ref{assump: error memorization scale}, we obtain that
    \begin{align*}
        I(\Acal(S); S_j \mid \theta_j) \ge c_\bP (1 - 2e_j)\cdot \mem_\ell(\bP) .
    \end{align*}
    Note that $$\sum_{j\in I_{n\# \ell}(S)}e_j = \E_{\theta_{1:k}\sim \Psi^k, S_\Xcal}\left[\errn(\Acal, \theta_{1:k},S, \ell)\right] .$$ Adding up the contribution from different $j\in I_{n\# \ell}(S)$, we get
    \begin{align*}
        \sum_{j\in I_{n\# \ell}(S)} I(\Acal(S); S_j \mid \theta_j)\ge c_\bP \cdot \E_{\theta_{1:k}\sim \Psi^k, S_\Xcal}\left[ (|I_{n\#\ell}(S)| - 2 \cdot\errn(\Acal, \theta_{1:k}, S, \ell)) \cdot \mem_\ell(\bP) \right]~.
    \end{align*}    
Finally, summing over all $\ell$ and taking the average over $\pi, i_1,\dots, i_n$ concludes the proof.










