  let game = play()
  game.mark(0, 0)
  game.mark(1, 0)
  game.mark(1, 1)
  game.mark(2, 0)
  game.mark(2, 2)
  return game.board.three_in_a_line()
\end{lstlisting}
\end{minipage}
