\subsubsection{Sensitivities for the trajectory cost}
Here, we consider an objective function with no end-point cost:

\begin{equation}
    \psi_i^{(2)}(\alpha) = \int_{t_0}^{t_f} R_i(\mathbf{u}(t),\alpha,t) dt \approx q_i(t_f)
\end{equation}

We use the same Runge-Kutta scheme to discretize the augmented ODE system with the $q_i$ variable. The scheme for the augmented system is: 

\begin{align}
    \mathbf{u}^{n+1} &= \mathbf{u}^n+\Delta t^n\sum_{m=1}^s b_m F(\mathbf{u}^{mm},\alpha,t^{mn}),
    \\
    q_i^{n+1} &= q_i^n+\Delta t^n\sum_{m=1}^s b_m R_i(\mathbf{u}^{mn},\alpha,t^{mn}),
\end{align}
and thus we define the following set of additional intermediate variables $v_i^{m,n}$:

\begin{align*}
    v_i^{0,0} &= q_i^0
    \\
    v_i^{m,n} &= R_i\big(\mathbf{u}^{mn},\alpha,t^{mn}\big) \qquad \text{if $m=1,\dots,s$}.
     \\
     v_i^{s+1,n} &= v_i^{0,n} + \Delta t^n \sum_{l=1}^s b_l v_i^{l,n},
     \\
     v^{0,n+1}_i &= v^{s+1,n}_i, \qquad \text{if $n>0$ and $n<T-1$},
\end{align*}
The last step is to compute the objective function, which is simply:

\begin{equation}
    v^{0,T}_i = q_i^T
\end{equation}
Similarly to before, to each intermediate variable $v_i^{m,n}$ and to each output vector entry $w^{0,T}_i$ corresponds an adjoint variable $\bar{v}_{i}^{m,n}$. We define the adjoint variables as the following total derivatives:

\begin{equation}
\bar{v}^{m,n}_{i} \defeq \frac{d \psi_i^{(2)}}{d v^{m,n}_i},
\end{equation}
exceptionally with no implied sum in the sub-index $i$. The seed will be $\bar{v}_i^{0,T}=1$ and the update equations will for the $\bar{v_i}^{m,n}$ adjoint variables will be:
\begin{align}
    \bar{v}^{s+1,n-1}_{i} &= \bar{v}^{0,n}_{i}
    \\
    \bar{v}^{m,n}_{i}&=\sum_{r=m+1}^{s+1}\bar{v}^{r,n}_{i}\frac{\partial v^{r,n}_i}{\partial v^{m,n}_i}
\end{align}
with no implied sum in the sub-index $i$. The update equations for the adjoint variables $\bar{w}^{mn}_{ij}$ now depend on $\bar{v_i}^{m,n}$: 

\begin{align}
    \bar{w}^{m,n}_{ij}&=\sum_{r=m+1}^{s+1}\bar{w}^{r,n}_{il}\frac{\partial w^{r,n}_l}{\partial w^{m,n}_j} + \bar{v}^{r,n}_{i}\frac{\partial v^{r,n}_i}{\partial w^{m,n}_j},
    \\
    \bar{\alpha}_{ik} &= \sum_{n=0}^{T-1}\sum_{r=0}^{s+1} 
    \bar{w}_{ij}^{r,n}\frac{\partial w^{r,n}_j}{\partial \alpha_k}+\bar{v}^{r,n}_{i}\frac{\partial v^{r,n}_i}{\partial \alpha_k},
\end{align}
with no implied sum in the sub-index $i$.


\subsubsection{Specifying the partial derivatives}
Given a forward pass algorithm for an explicit $s$-stage Runge-Kutta method, we can write the algorithm for its respective \textbf{reverse pass} following the adjoint update equations presented in the last section. This algorithm takes $\frac{\partial \psi_i}{\partial u^T_j}$ and $\frac{\partial \psi_i}{\partial \alpha_k}$ as inputs and returns $\bar{w}^{0,0}_{ij}$ and $\bar{\alpha}_{ik}$ as outputs. All that is left to complete the specification of this algorithm is to manually derive the partial derivatives appearing in the adjoint equations for a general $s$-stage Runge-Kutta method. The result is the following:

\begin{align}
    \frac{\partial w^{s+1,n}_i}{\partial w^{q,n}_j} &=
	\begin{cases}
		\delta_{ij}
		& \text{if } q=0\\
		\\
		\delta_{ij}\Delta t^n b_{q}
		& \text{if } 0<q<m
	\end{cases},
 \label{eq::partialderivatives1}
 \\
	\frac{\partial w^{m,n}_i}{\partial w^{q,n}_j} &=
	\begin{cases}
		J^x_{ij}\left(
		\mathbf{x}^{m,n},t^{m,n}\right)
		& \text{if } q=0\\
		\\
		J^x_{ij}\left(
		\mathbf{x}^{m,n},t^{m,n}\right)
		\Delta t^n a_{mq}
		& \text{if } 0<q<m
	\end{cases},
\label{eq::partialderivatives2}
\\
        \frac{\partial w_i^{m,n}}{\partial \alpha_k} &= \begin{cases}
		J^\alpha_{ik}(\mathbf{x}^{m,n},t^{m,n}) & \text{if } 0<m<s+1\\
            \\
		0 & \text{otherwise } 
	\end{cases},
\label{eq::partialderivatives3}
\\
	\frac{\partial w^{0,n}_i}{\partial w^{s+1,n-1}_j} &= \delta_{ij}.
\label{eq::partialderivatives4}
\end{align}
where the calculations and the definition of the Jacobian matrices $J^x$ and $J^\alpha$ and of the intermediate Runge-Kutta state $\mathbf{u^{m,n}}$ can be found in appendix \ref{appendix::calculations}. The vector-Jacobian products $\bar{w}^{m,n}_{il}J^{x,\alpha}_{lj}\left(\mathbf{u}^{m,n},\alpha,t^{m,n}\right)$ are \textbf{efficiently and automatically} evaluated using the automatic adjoint differentiation library AADC \cite{Matlogica}.  In  algorithm \ref{alg::reverse_pass}, we present the pseudo-code for the reverse pass for a single index $i$.

\begin{algorithm}
\caption{Reverse Pass}
\SetKwInOut{Input}{input}
\Input{$\frac{\partial \psi_i}{\partial u^T_j}$ and $\frac{\partial \psi_i}{\partial \alpha_k}$}
\SetKwBlock{Beginn}{beginn}{ende}
    \Begin{
    Initialise seed $\bar{w}_{ij}^{s+1,T-1} =\frac{\partial \psi_i}{\partial u_j(t_f)} $ and $\bar{\alpha}_{ik}$\;
    \For{\texttt{<$n=T-1$;$n\ge0$;$n--$>}}{
        $\bar{w}^{m,n}_{ij} =0, \text{if } 0\le m < s+1$\;
        \For{\texttt{<$m=s+1$;$m>0$;$m--$>}}{
            \For{\texttt{<$0\leq q\leq m-1$>}}{
                $\bar{w}^{q,n}_{ij}+=\bar{w}^{m,n}_{ir}\frac{\partial w^{m,n}_r}{\partial w^{q,n}_j}$
            }
        $\bar{\alpha}_{ik}+=\bar{w}^{m,n}_{ir}\frac{\partial w^{m,n}_r}{\partial \alpha_k}$
        }
    \If{$n>0$}{
    $\bar{w}^{s+1,n-1}_{ij}=\bar{w}^{0,n}_{il}\frac{\partial w^{0,n}_l}{\partial w_j^{s+1,n-1}}$}
    }
    }%\EndFor
\Return $\bar{\alpha}_{ik},\bar{w}^{0,0}_{ij}$
\label{alg::reverse_pass}
\end{algorithm}


\subsection{Checkpointing\label{sec::caching}}
The reverse pass requires knowledge of the forward trajectory whenever the Jacobian matrices depend explicitly on the state vector or the parameters. Effectively, we require the knowledge of the intermediate states $\mathbf{w}^{m,n}_i$ at the time instances $t^{m,n}$ determined adaptively at run-time. 

Obtaining the intermediate states $\mathbf{w}^{m,n}_i$ can be done in a mix of two distinct ways: either cache the intermediate states $\mathbf{w}^{m,n}_i$ and time instances $t^{m,n}$ during the forward pass or recompute the intermediate states by solving the ODE system backwards, a trade-off between performance and memory load. In their implementation of the continuous adjoint sensitivity analysis method \cite{DENSERKS2009}, the authors take the second approach by solving the ODE system backwards alongside the augmented adjoint system and use the dense output mechanism of Runge-Kutta methods to obtain the required intermediate states $\mathbf{u}^{m,n}$ at the correct instances of time, which need to be cached. In the unpublished paper \cite{zhuang2020ordinary}, the authors decided to employ a similar approach and reconstruct $\mathbf{u}^{n}$ from $\mathbf{u}^{n+1}$ by re-building the computational graph at time instances $t^{m,n}$, again requiring caching only $t^n$. This approach effectively requires the solution of the following system of equations:

\begin{equation}
    \begin{cases}
    \mathbf{w}^{s+1,n} &= \mathbf{w}^{0,n}+\Delta t^n \sum_{l=1}^s b_l \mathbf{w}^{l,n}
    \\
    \vdots
    \\
    \mathbf{w}^{m,n} &= F(\mathbf{w}^{0,n}+\Delta t^n\sum_{l=1}^{m-1}a_{mj}\mathbf{w}^{m,n},\alpha,t^{m,n})
    \end{cases}
\end{equation}
to find $\mathbf{w}^{0,n}$, which may be computationally cumbersome because of the inversion of $F$, and depending on the nature of the function might not even be possible to do analytically, thus introducing numerical error. In \cite{DENSERKS2009}, the authors need not to force the solver to compute at time instances $t^{m,n}$, whereas the time instances at which the state vectors are recomputed in \cite{zhuang2020ordinary} are determined by the forward run. However, the dense output estimation of the intermediate states in \cite{DENSERKS2009} is not exact up to machine precision. In FATODE's implementation \cite{fatode2014}, the time instances $t^n$ and every intermediate state $\mathbf{u}^{m,n}_i$ is cached, with memory cost $\mathcal{O}(N\times T\times s)$. In our implementation, we strike a balance between extra computation and memory load by caching only the hidden states $\mathbf{u}^n$ and time instances $t^n$ during the forward run, and using them to recompute the intermediate states $\mathbf{w}^{m,n}$ again, as if it were a forward run, with memory cost of $\mathcal{O}(N\times T)$.


\subsection{Vectorization via Advanced Vector Extensions}
This implementation of discrete adjoint sensitivity analysis is enhanced by utilising SIMD (Single Instruction, Multiple Data) vectorization through Advanced Vector Extensions (AVX) to explore the data-level parallelism inherent to this method. In our work, we employ AVX-256, specifically on an Intel Core i7-8850H CPU @ 2.60GHz × 12 processor, where each YMM register can hold up to four 64-bit double-precision floating point numbers.

The automatic differentiation framework of \cite{Matlogica} supports this SIMD vectorization, allowing us to efficiently compute vector-Jacobian products for multiple vectors concurrently. By leveraging AVX, we load the YMM registers, with entries from four different vectors of adjoint variables. For example, for a given set of indices $j$,$m$ and $n$, we load the YMM register with the entries $\bar{w}^{m,n}_{1j}$, $\bar{w}^{m,n}_{2j}$, $\bar{w}^{m,n}_{3j}$ and $\bar{w}^{m,n}_{4j}$, for given $j,m,n$. This functionality effectively allows us to evaluate the vector-Jacobian products of four distinct entries $i$ of the  objective function $\psi_i$ concurrently. This parallelism is particularly beneficial when there are multiple outputs of the objective function. This approach results in a performance increase when performing sensitivity analysis on a model with many parameters but few output objective functions. 

Notably, not only the vector-Jacobian products can be performed concurrently, bu the adjoint variables respective to each output can themselves be updated in parallel at a higher level of parallelism, i.e., multi-threading. Although this feature was not explored in the current work, it presents a promising direction for future research.

\section{Results and Validation \label{sec:results}}
In this section we validate our implementation of the discrete adjoint sensitivity method and test its performance compared to other sensitivity analysis software. We employ three different models for this purpose:

\begin{itemize}
    \item [1)] An $N_p\times N_p$ finite differences discretization of a two-dimensional heat equation with constant thermal diffusivity.
    \item  [2)] A Van der Pol oscillator
    \item [2)] The generalised Lotka-Volterra (GLV) equations.
\end{itemize}
We validate the algorithm by comparing the output sensitivities of several methods of sensitivity analysis with the analytical expression for the sensitivities of the heat equation. We further validate by exploring how the sensitivity error depends on the solution error for several implementations of adjoint sensitivity analysis. We provide a performance analysis by constructing work precision diagrams for our implementation and for other established sensitivity analysis software when applied to the computation of the sensitivities of the GLV equations.

The computations were performed on a laptop computer with an Intel Core i7-8850H CPU @ 2.60GHz × 12. The laptop had a 32.0 GB RAM. We ran the simulations on the Ubuntu 22.04.1 LTS operating system. We used \texttt{gcc} for compiling the C++ code and \texttt{gfortran} for compiling Fortran, both version 11.3.0, with the $-O3$ optimisation flag and we used double-precision floating point arithmetic. PETSc was installed with the following configuration:

\begin{lstlisting}[language=bash]
./config/examples/arch-ci-linux-gcc-pkgs-opt.py \
    --download-ssl --download-fblaslapack=1
\end{lstlisting}
In this section, we refer to our implementation of the discrete adjoint sensitivity analysis method simply as the "adjoint method".

\subsection{Two-dimensional heat equation with classic RK methods}
Consider the two-dimensional heat equation in the domain $\Omega = [0,1]\times[0,1]$ and time interval $t\in(0,t_f)$ with homogeneous Dirichlet boundary conditions:

\begin{equation}
   \frac{\partial u(\mathbf{x},t)}{\partial t} = \alpha \nabla u(\mathbf{x},t), \qquad
    u(\mathbf{x},0) = u^0(\mathbf{x}), \qquad
    u(\mathbf{x},t) = 0, \forall \mathbf{x}\in\partial\Omega,
    \label{eq::heat_equation_2D}
\end{equation}
where $u(\mathbf{x},t)$ is the temperature distribution in the domain $\Omega$ and $\alpha$ is the constant thermal diffusivity. The solution is given by,

\begin{equation}
    u(\mathbf{x},t) = \sum_{m=1}^\infty\sum_{n=1}^\infty \gamma_{mn}\sin(m\pi x)\sin(n\pi y)\exp{(-\lambda_{mn}^2 t)}
\end{equation}
where $\lambda_{mn}$ is the normal mode eigenvalue and $\gamma_{mn}$ the 2D Fourier coefficient of the initial condition $u^0(\mathbf{x})$,

\begin{equation}
    \lambda_{mn}= \sqrt{\alpha\pi^2(m^2+n^2)},
    \qquad
    \gamma_{mn} = 4\int_{0}^{1}\int_{0}^{1} u(\mathbf{x},0)\sin(m\pi x)\sin(n\pi x) \text{ }dxdy.
\end{equation}
The sensitivity of the solution $u(\mathbf{x},t_f)$ at the final time with respect to the constant thermal diffusivity, $\Bar{\alpha}(\mathbf{x})\defeq\frac{\partial u(\mathbf{x},t_f)}{\partial \alpha}$, is given in terms of the closed-form analytic expression:

\begin{equation}
    \Bar{\alpha}(\mathbf{x}) = -\pi^2 t_f\sum_{m,n=1}^\infty (m^2+n^2)\gamma_{mn}\times\sin(m\pi x)\sin(n\pi y)\exp{(-\lambda_{mn}^2 t_f)}.
\label{exactadjointheat}  
\end{equation}

We discretize equation \ref{eq::heat_equation_2D} in space using a finite-difference scheme. We define an evenly spaced grid $(x_i,y_j)$ of $N_p\times N_p$ points, where $x_i = (i-1)\Delta x$ and $y_j = (j-1)\Delta y$, with $i,j = 1,\dots,N_p$. Let $u_{k}\approx u(x_i,y_j)$, with $k = i+N_p(j-1)$, and define the set of interior grid points as $I = \left\{k\in\mathbb{N}\colon (x_{i(k)},y_{j(k)}) \in \text{int}(\Omega)\right\}$ and the set of boundary points as $B = \left\{k\in\mathbb{N}\colon (x_{i(k)},y_{j(k)}) \in \text{fr}(\Omega)\right\}$. Equation \ref{eq::heat_equation_2D} is thus approximated by the following system of ODEs:

\begin{align}
    \frac{d u_{k}(t)}{dt} &=
    \alpha \bigg(
    \frac{u_{k-1}-2u_{k}+u_{k+1}}{\Delta x^2}\nonumber
    +\frac{u_{k-N_p}-2u_{k}+u_{k+N_p}}{\Delta y^2}
    \bigg), \forall k \in I,\nonumber
    \\
    \frac{du_{k}(t)}{dt} &= 0\qquad \forall k \in B, \qquad u_k(0) = u^0(x_{i(k)},y_{j(k)}) \qquad \forall k \in I\cup B.
\label{eq::heat_equation_ode_system}
\end{align}
In the following experiments, we numerically compute  the sensitivities with respect to the thermal diffusivity with several methods of sensitivity analysis and compare them with the analytical solution. We consider $\Delta y = \Delta x = \frac{1}{N_p-1}$, $u^0(\mathbf{x}) = \sin(\pi x)\sin(\pi y)$ and $\alpha = 1$. The ODE system is integrated in the interval $t \in [0,10^{-2}]$ with a constant time step $\Delta t$ using either the explicit Euler solver or the classic $4$th order Runge-Kutta solver provided in the \texttt{boost::odeint} library.

