\section{Computing the partial derivatives\label{appendix::calculations}}
In this appendix we compute the partial derivatives shown in equation \ref{eq::partialderivatives1}, \ref{eq::partialderivatives2}, \ref{eq::partialderivatives3} and \ref{eq::partialderivatives4}, which are necessary for the full specification of the algorithm of discrete adjoint sensitivity analysis.

\subsection{Partial derivatives with respect to the intermediate variables}
It is useful to reacll the definition of the $m$th Runge-Kutta intermediate state $\mathbf{u}^{m,n}$:

\begin{equation}
\label{intermediate_state_x_m_n_definition}
u_i^{m,n}(\mathbf{w}^{0,n},\dots,\mathbf{w}^{m-1,n}) \\
= w_i^{0,n}+\Delta t^n \sum_{l=1}^{m-1} a_{ml} w_i^{l,n}, \qquad m = 1,\dots,s,
\end{equation}
and the definition of the intermediate states,

\begin{equation}
	\mathbf{w}^{m,n}=
	F\big(
	\mathbf{u}^{m,n},
	\alpha,
	t^{m,n}
	\big) \qquad  m = 1,\dots,s.
\end{equation}
Now, consider an infinitesimal displacement of the intermediate variable $w^{q,n}_j$, $w^{q,n}_j\to w^{q,n}_j+\Delta w^{q,n}_j$, and take the limit of $\frac{\Delta w^{m,n}_i}{\Delta w^{q,n}_j}$ when $\Delta w^{q,n}_j\to 0$. This limit corresponds to the sought after partial derivatives, and we proceed to analyse this limit for different values of the index $m$. The infinitesimal displacement on the $w^{q,n}_j$ intermediate variable induces a displacement on the $m$th Runge-Kutta intermediate state $\mathbf{u}^{m,n}$, namely:

\begin{align}
u^{m,n}_i(\mathbf{w}^{0,n},\dots,\mathbf{w}^{m-1,n})   &\to	u^{m,n}_i(\mathbf{w}^{0,n},\dots,w^{q,n}_j+\Delta w^{q,n}_j,\dots,\mathbf{w}^{m-1,n}) \nonumber
\\
&=u^{m,n}_i(\mathbf{w}^{0,n},\dots,\mathbf{w}^{m-1,n})+\Delta u^{m,n}_i.
\end{align}
In turn, the displacement $\Delta u^{m,n}_i$ is given by:

\begin{equation}
	\Delta u^{m,n}_i = \frac{\partial u^{m,n}_i(\mathbf{w}^{0,n},\dots,\mathbf{w}^{m-1,n})}{\partial w_j^{q,n}}\Delta w_j^{q,n}\text{ (no sum in $j$)},
\end{equation}
to first order in $\Delta w_j^{q,n}$, and the partial derivatives $\frac{\partial u^{m,n}_i}{\partial w_j^{q,n}}$ can be analytically computed from expression \ref{intermediate_state_x_m_n_definition},

\begin{equation}
	\frac{\partial u^{m,n}_i}{\partial w^{q,n}_j} =
	\begin{cases}
		\delta_{ij}
		& \text{if } q=0\\
		\\
		\Delta t^n a_{mq} \delta_{ij}
		& \text{if } q<m
	\end{cases}
\end{equation}

To compute the partial derivatives for $m=s+1$, we simply take into account the following expression,
\begin{equation}
     w^{s+1,n}_i =  w^{0,n}_i + \Delta t^n \sum_{l=1}^s b_l w_i^{l,n},
\end{equation}
and so we have:
\begin{equation}
	\frac{\partial w^{s+1,n}_i}{\partial w^{q,n}_j} =
	\begin{cases}
		\delta_{ij} & \text{if } q=0\\
		\delta_{ij} b_q \Delta t^n & \text{if } q=1,\dots,s\\
	\end{cases}.
\end{equation}
To compute the partial derivatives for any $m=1,\dots,s$, we need first to ascertain how the displacement on $w^{q,n}_j$ affects the intermediate variables $w_i^{m,n}$, namely:

\begin{equation}
w^{m,n}_i = F(\mathbf{u}^{m,n},t^{m,n}) \to
F_i(\mathbf{u}^{m,n}+\Delta\mathbf{u}^{m,n},t^{m,n}) =
w^{m,n}_i + \Delta w^{m,n}_i
\end{equation}
where, by using the chain rule, the nudge $\Delta w^{m,n}_i$ is given by:

\begin{align}
\Delta w^{m,n}_i &= F_i(\mathbf{u}^{m,n}+\Delta\mathbf{u}^{m,n},t^{m,n})-F_i(\mathbf{u}^{m,n},t^{m,n})\nonumber
 \\ 
&= J^x_{il}(\mathbf{u}^{m,n},t^{m,n})\frac{\partial u^{m,n}_l}{\partial w_j^{q,n}}\Delta w_j^{q,n} \qquad
 \text{(no sum in $j$)},
\end{align}
to first order in $\Delta w_j^{q,n}$. In the above expression,  $J^x(\mathbf{u}^{m,n},t^{m,n})$ denotes the $N\times N$ Jacobian matrix of $F$ taking $\alpha_k$ and $t^{m,n}$ as constants. The matrix is computed at the $m$th Runge-Kutta intermediate state $\mathbf{u}^{m,n}$, parameter vector $\alpha$ and intermediate time $t^{m,n}$:

\begin{equation}
	J^x(\mathbf{u},\alpha,t) =
	\begin{bmatrix}
		&\frac{\partial F_1(\mathbf{x},\alpha,t)}{\partial x_1} &\dots &\frac{\partial F_1(\mathbf{x},\alpha,t)}{\partial x_N}
		\\
		&\vdots  &\ddots &\vdots  
		\\
		&\frac{\partial F_N(\mathbf{x},\alpha,t)}{\partial x_1} &\dots &\frac{\partial F_N(\mathbf{x},\alpha,t)}{\partial x_N}
	\end{bmatrix},
\end{equation}
Finally, the partial derivatives $\frac{\partial w^{m,n}_i}{\partial w^{q,n}_j}$, for $m=1,\dots,s$, are given by the following limit:

\begin{equation}
	\frac{\partial w^{m,n}_i}{\partial w^{q,n}_j} = \lim_{\Delta w_j^{q,n}\to 0} \frac{\Delta w^{m,n}_i}{\Delta w_j^{q,n}} = J^x_{il}(\mathbf{u}^{m,n},\alpha,t^{m,n})\frac{\partial u^{m,n}_l}{\partial w_j^{q,n}}.
\end{equation}
In conclusion, we get the following expressions for the partial derivatives $\frac{\partial w^{m,n}_i}{\partial w^{q,n}_j}$ for $m=1,\dots,s$:

\begin{equation}
	\frac{\partial w^{m,n}_i}{\partial w^{q,n}_j} =
	\begin{cases}
		J^x_{ij}(\mathbf{x}^{m,n},\alpha,t^{m,n})
		& \text{if } q=0\\
		\\
		J^x_{ij}(\mathbf{x}^{m,n},\alpha,t^{m,n})
		\Delta t^n a_{mq}
		& \text{if } q<m
	\end{cases},
\end{equation}
To compute the partial derivatives for $m=0$, we take into account the following expression,
\begin{equation}
     w^{0,n}_i =  w^{s+1,n-1}_i
\end{equation}
and so we have:

\begin{equation}
	\frac{\partial w^{0,n}_i}{\partial w^{s+1,n-1}_j} = \delta_{ij}
\end{equation}


\subsection{Partial derivatives with respect to the parameters}
Consider an infinitesimal displacement of the $k$th parameter $\alpha_k \to \alpha_k+\Delta\alpha_k$, which induces a displacement on $w^{m,n}_i$ given by:

\begin{equation}
	\Delta w^{m,n}_i =F_i(\mathbf{x}^{m,n},\mathbf{\alpha}+\Delta\mathbf{\alpha},t^{m,n})-F_{\mathbf{\alpha},i}(\mathbf{x}^{m,n},\alpha,t^{m,n})= J^\alpha_{ik}\Delta \alpha_k \qquad \text{(no sum in $k$)},
\end{equation}
to first order in $\alpha_k$. Here, $J^\alpha$ corresponds to the $N\times P$ Jacobian matrix of $F$ taking all inputs except $\alpha$ as constants, computed at state $\mathbf{u}^{m,n}$, intermediate time $t^{m,n}$ and given parameters $\alpha$:

\begin{equation}
	J^\alpha(\mathbf{u},\alpha,t) = 
	\begin{bmatrix}
		&\frac{\partial F_{1}(\mathbf{u},\alpha,t)}{\partial \alpha_1} &\dots &\frac{\partial F_{1}(\mathbf{u},\alpha,t) }{\partial \alpha_M}
		\\
		&\vdots  &\ddots &\vdots  
		\\
		&\frac{\partial F_{N}(\mathbf{u},\alpha,t) }{\partial \alpha_1} &\dots &\frac{\partial F_{N}(\mathbf{u},\alpha,t) }{\partial \alpha_M}
	\end{bmatrix}.
\end{equation}
Finally, the partial derivatives $\frac{\partial w^{m,n}_i}{\partial \alpha_k}$ for $m=1,\dots,s$ are given by taking the following limit:

\begin{equation}
\frac{\partial w_i^{m,n}}{\partial \alpha_k} = \lim_{\Delta\alpha_k\to0} \frac{\Delta w_i^{m,n}}{\Delta\alpha_k}= J^\alpha_{ik}(\mathbf{u}^{m,n},\alpha,t^{m,n})
\end{equation}
and for $m=0$ and $m=s+1$ we have:

\begin{equation}
	\frac{\partial w_j^{0,n}}{\partial \alpha_k} = 0 \qquad\text{and}\qquad \frac{\partial w_j^{s+1,n}}{\partial \alpha_k} = 0
\end{equation}


